 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Console\Commands;
 6: 
 7: use Illuminate\Console\Command;
 8: use Illuminate\Support\Facades\DB;
 9: use Illuminate\Support\Facades\Storage;
10: use Throwable;
11: 
12: /**
13:  * F13: afterRollBack cleanup never runs when the process itself dies
14:  * (max_execution_time, OOM, worker restart) — the DB rolls back on
15:  * disconnect but the orphaned R2 files stay. This command deletes uuid/
16:  * folders older than the grace window that no media row references.
17:  * Compare in batches; deletions are idempotent, so re-runs are safe.
18:  */
19: class PruneOrphanMediaFiles extends Command
20: {
21:     protected $signature = 'media:prune-orphans {--disk=r2_public : المجلد العام للكتالوج} {--older-than=60 : عمر المجلد بالدقائق قبل اعتباره يتيمًا} {--dry-run : عرض فقط دون حذف}';
22: 
23:     protected $description = 'Delete orphaned uuid/ media folders with no matching media row';
24: 
25:     public function handle(): int
26:     {
27:         $diskName = (string) $this->option('disk');
28:         $olderThan = filter_var($this->option('older-than'), FILTER_VALIDATE_INT);
29:         if (! in_array($diskName, ['r2', 'r2_public'], true) || $olderThan === false || $olderThan < 60) {
30:             $this->error('Use an R2 disk and a grace period of at least 60 minutes.');
31: 
32:             return self::FAILURE;
33:         }
34:         $dryRun = (bool) $this->option('dry-run');
35:         $cutoff = now()->subMinutes($olderThan)->getTimestamp();
36: 
37:         $disk = Storage::disk($diskName);
38:         $pruned = 0;
39:         $skipped = 0;
40:         $failures = 0;
41: 
42:         foreach ($disk->directories('') as $dir) {
43:             try {
44:                 $base = basename($dir);
45:                 // uuid layout only — legacy numeric id/ folders are untouched.
46:                 if (! preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i', $base)) {
47:                     continue;
48:                 }
49:                 if (DB::table('media')->where('uuid', $base)->exists()) {
50:                     continue;
51:                 }
52:                 $files = $disk->allFiles($dir);
53:                 if ($files === []) {
54:                     $this->warn("Empty directory {$dir} — leaving it in place.");
55: 
56:                     continue;
57:                 }
58:                 $newest = 0;
59:                 foreach ($files as $file) {
60:                     $newest = max($newest, $disk->lastModified($file));
61:                 }
62:                 if ($newest >= $cutoff) {
63:                     $skipped++;
64: 
65:                     continue;
66:                 }
67:                 // Recheck after listing timestamps; a live upload may have committed
68:                 // while the storage listing was in progress.
69:                 if (DB::table('media')->where('uuid', $base)->exists()) {
70:                     continue;
71:                 }
72:                 if ($dryRun) {
73:                     $this->line("[dry-run] would delete {$dir} (".count($files).' files)');
74:                 } else {
75:                     if (! $disk->deleteDirectory($dir)) {
76:                         throw new \RuntimeException('Storage did not confirm deletion.');
77:                     }
78:                 }
79:                 $pruned++;
80:             } catch (Throwable $exception) {
81:                 $failures++;
82:                 report($exception);
83:                 $this->error('Could not process '.$dir.'; rerun after checking storage access.');
84:             }
85:         }
86: 
87:         $this->info("Pruned {$pruned} orphan media directorie(s); {$skipped} recent upload(s) left for the grace window.");
88: 
89:         return $failures === 0 ? self::SUCCESS : self::FAILURE;
90:     }
91: }

