 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Api\V1\Admin\AdminLoginRequest;
 9: use App\Http\Resources\Api\V1\Admin\UserResource;
10: use App\Models\User;
11: use Illuminate\Http\JsonResponse;
12: use Illuminate\Http\Request;
13: use Illuminate\Http\Resources\Json\JsonResource;
14: use Illuminate\Http\Response;
15: use Illuminate\Support\Facades\Hash;
16: use Illuminate\Support\Facades\RateLimiter;
17: use Illuminate\Support\Str;
18: 
19: class AuthController extends Controller
20: {
21:     private const DUMMY_PASSWORD_HASH = '$2y$12$dRibbzvWAKqkXBRPna4QCuri7dR8TKHRGDIt.RsplFZRfRcJzmPlq';
22: 
23:     public function login(AdminLoginRequest $request): JsonResource|JsonResponse
24:     {
25:         $credentials = $request->validated();
26:         $user = User::query()
27:             ->whereRaw('LOWER(email) = ?', [$credentials['email']])
28:             ->first();
29:         $storedHash = $user instanceof User ? $user->password : self::DUMMY_PASSWORD_HASH;
30:         $passwordMatches = Hash::check($credentials['password'], $storedHash);
31: 
32:         if (! $user instanceof User || ! $user->is_active || ! $passwordMatches) {
33:             return response()->json([
34:                 'message' => 'بيانات تسجيل الدخول غير صحيحة أو الحساب غير نشط.',
35:             ], 401);
36:         }
37: 
38:         $emailKey = hash('sha256', Str::transliterate(Str::lower(trim($credentials['email']))));
39:         RateLimiter::clear('admin-login-email:'.$emailKey);
40:         RateLimiter::clear('admin-login-email-hour:'.$emailKey);
41: 
42:         $user->load(['branch', 'roles.permissions', 'permissions']);
43:         $token = $user->createToken('staff-token')->plainTextToken;
44: 
45:         return UserResource::make($user)->additional(['token' => $token]);
46:     }
47: 
48:     public function me(Request $request): JsonResource
49:     {
50:         $user = $request->user('staff');
51: 
52:         abort_unless($user instanceof User, 403);
53: 
54:         $user->load(['branch', 'roles.permissions', 'permissions']);
55: 
56:         return UserResource::make($user);
57:     }
58: 
59:     public function logout(Request $request): Response
60:     {
61:         $request->user('staff')?->currentAccessToken()?->delete();
62: 
63:         return response()->noContent();
64:     }
65: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Brand\StoreBrandRequest;
 9: use App\Http\Requests\Admin\Brand\UpdateBrandRequest;
10: use App\Http\Resources\Admin\BrandResource;
11: use App\Models\Brand;
12: use App\Services\Catalog\BrandService;
13: use App\Services\SearchTerm;
14: use Illuminate\Http\JsonResponse;
15: use Illuminate\Http\Request;
16: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
17: use Illuminate\Routing\Controllers\HasMiddleware;
18: use Illuminate\Routing\Controllers\Middleware;
19: 
20: class BrandController extends Controller implements HasMiddleware
21: {
22:     public function __construct(private BrandService $service) {}
23: 
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:brands.view', only: ['index', 'show']),
28:             new Middleware('can:brands.create', only: ['store']),
29:             new Middleware('can:brands.update', only: ['update']),
30:             new Middleware('can:brands.delete', only: ['destroy']),
31:         ];
32:     }
33: 
34:     public function index(Request $request): AnonymousResourceCollection
35:     {
36:         $filters = $request->validate([
37:             'search' => ['nullable', 'string', 'max:100'],
38:             'is_active' => ['nullable', 'boolean'],
39:             'per_page' => ['nullable', 'integer', 'min:1'],
40:         ]);
41: 
42:         $perPage = min((int) ($filters['per_page'] ?? 15), 100);
43: 
44:         $brands = Brand::query()
45:             ->with('media')
46:             // F16: also expose the trashed-inclusive count so the UI can
47:             // explain why delete fails on a "0 products" row.
48:             ->withCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()])
49:             ->when(isset($filters['search']) && $filters['search'] !== '', function ($query) use ($filters): void {
50:                 $pattern = SearchTerm::pattern($filters['search']);
51:                 $query->where(fn ($q) => $q->whereLike('name_ar', $pattern, caseSensitive: false)
52:                     ->orWhereLike('name_en', $pattern, caseSensitive: false));
53:             })
54:             ->when(isset($filters['is_active']), fn ($query) => $query->where('is_active', filter_var($filters['is_active'], FILTER_VALIDATE_BOOLEAN)))
55:             ->orderBy('sort_order')
56:             ->orderBy('id')
57:             ->paginate($perPage)
58:             ->withQueryString();
59: 
60:         return BrandResource::collection($brands);
61:     }
62: 
63:     public function show(Brand $brand): BrandResource
64:     {
65:         $brand->load('media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
66: 
67:         return BrandResource::make($brand);
68:     }
69: 
70:     public function store(StoreBrandRequest $request): JsonResponse
71:     {
72:         $brand = $this->service->create($request->validated(), $request->file('logo'));
73:         $brand->load('media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
74: 
75:         return BrandResource::make($brand)->response()->setStatusCode(201);
76:     }
77: 
78:     // ملحوظة: تحديث براند مع لوجو بيتبعت POST مع _method=PUT، لأن PHP لا يقرأ ملفات multipart مع PUT.
79:     public function update(UpdateBrandRequest $request, Brand $brand): BrandResource
80:     {
81:         $brand = $this->service->update($brand, $request->validated(), $request->file('logo'));
82:         $brand->load('media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
83: 
84:         return BrandResource::make($brand);
85:     }
86: 
87:     public function destroy(Brand $brand): JsonResponse
88:     {
89:         $this->service->delete($brand);
90: 
91:         return response()->json(['message' => 'تم الحذف']);
92:     }
93: }

