20: class PriceListItemController extends Controller implements HasMiddleware
21: {
22:     public function __construct(private readonly PriceListService $priceLists) {}
23: 
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:price_lists.view', only: ['index', 'show']),
28:             new Middleware('can:price_lists.create', only: ['store']),
29:             new Middleware('can:price_lists.update', only: ['update']),
30:             new Middleware('can:price_lists.delete', only: ['destroy']),
