35:     {
36:         $filters = $request->validate([
37:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
38:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
39:         ]);
40: 
41:         return PriceListItemResource::collection($this->priceLists->paginateItems($priceList, $filters, $request->user()));
42:     }
43: 
44:     public function store(StorePriceListItemRequest $request, PriceList $priceList): JsonResponse
45:     {
46:         $item = $this->priceLists->createItem($priceList, $request->validated(), $request->user());
47: 
48:         return (new PriceListItemResource($item))
49:             ->additional(['message' => 'تمت إضافة سعر الصنف بنجاح'])
50:             ->response()
51:             ->setStatusCode(201);
52:     }
53: 
54:     public function show(Request $request, PriceList $priceList, PriceListItem $item): PriceListItemResource
55:     {
56:         $this->priceLists->assertListAccess($request->user(), $priceList);
57: 
58:         return new PriceListItemResource($item->load('variant.product'));
59:     }
60: 
61:     public function update(UpdatePriceListItemRequest $request, PriceList $priceList, PriceListItem $item): PriceListItemResource
62:     {
63:         return new PriceListItemResource($this->priceLists->updateItem($item, $request->validated(), $request->user()));
64:     }
65: 
66:     public function destroy(Request $request, PriceList $priceList, PriceListItem $item): JsonResponse
67:     {
68:         $this->priceLists->deleteItem($item, $request->user());
69: 
70:         return response()->json(['message' => 'تم حذف سعر الصنف بنجاح']);
71:     }
72: }

