  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\StaffRole;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Requests\Api\V1\Admin\StoreRoleRequest;
 10: use App\Http\Requests\Api\V1\Admin\UpdateRoleRequest;
 11: use App\Http\Resources\Api\V1\Admin\RoleResource;
 12: use App\Models\User;
 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 16: use Illuminate\Http\Response;
 17: use Illuminate\Support\Facades\DB;
 18: use Spatie\Permission\Models\Role;
 19: 
 20: class RoleController extends Controller
 21: {
 22:     public function index(Request $request): AnonymousResourceCollection
 23:     {
 24:         $validated = $request->validate([
 25:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 26:         ]);
 27: 
 28:         $roles = Role::query()
 29:             ->where('guard_name', 'staff')
 30:             ->with('permissions')
 31:             ->orderBy('id')
 32:             ->paginate($validated['per_page'] ?? 15)
 33:             ->withQueryString();
 34: 
 35:         return RoleResource::collection($roles);
 36:     }
 37: 
 38:     public function store(StoreRoleRequest $request): JsonResponse
 39:     {
 40:         $validated = $request->validated();
 41:         $permissions = $validated['permissions'] ?? [];
 42:         $currentUser = $request->user('staff');
 43: 
 44:         if ($validated['name'] === StaffRole::SuperAdmin->value) {
 45:             return response()->json([
 46:                 'message' => 'لا يمكن إنشاء دور Super Admin من هذه الواجهة.',
 47:             ], 403);
 48:         }
 49: 
 50:         if (! $this->mayGrantPermissions($currentUser, $permissions)) {
 51:             return response()->json([
 52:                 'message' => 'لا يمكنك إسناد صلاحيات لا تملكها.',
 53:             ], 403);
 54:         }
 55: 
 56:         $role = DB::transaction(function () use ($validated, $permissions): Role {
 57:             $role = Role::create([
 58:                 'name' => $validated['name'],
 59:                 'guard_name' => 'staff',
 60:             ]);
 61:             $role->syncPermissions($permissions);
 62: 
 63:             return $role->load('permissions');
 64:         });
 65: 
 66:         return RoleResource::make($role)->response()->setStatusCode(201);
 67:     }
 68: 
 69:     public function show(Role $role): RoleResource
 70:     {
 71:         $this->ensureStaffRole($role);
 72: 
 73:         return RoleResource::make($role->load('permissions'));
 74:     }
 75: 
 76:     public function update(UpdateRoleRequest $request, Role $role): RoleResource|JsonResponse
 77:     {
 78:         $validated = $request->validated();
 79:         $permissions = $validated['permissions'] ?? null;
 80:         $currentUser = $request->user('staff');
 81: 
 82:         if (array_key_exists('name', $validated) && $validated['name'] === StaffRole::SuperAdmin->value) {
 83:             return response()->json([
 84:                 'message' => 'لا يمكن تسمية دور آخر باسم Super Admin.',
 85:             ], 403);
 86:         }
 87: 
 88:         if (is_array($permissions) && ! $this->mayGrantPermissions($currentUser, $permissions)) {
 89:             return response()->json([
 90:                 'message' => 'لا يمكنك إسناد صلاحيات لا تملكها.',
 91:             ], 403);
 92:         }
 93: 
 94:         $failure = DB::transaction(function () use ($role, $validated, $permissions): ?string {
 95:             $lockedRole = Role::query()->whereKey($role->getKey())->lockForUpdate()->firstOrFail();
 96:             $this->ensureStaffRole($lockedRole);
 97: 
 98:             if ($lockedRole->name === StaffRole::SuperAdmin->value) {
 99:                 return 'protected';
100:             }
101: 
102:             if (array_key_exists('name', $validated)) {
103:                 $lockedRole->name = $validated['name'];
104:                 $lockedRole->save();
105:             }
106: 
107:             if ($permissions !== null) {
108:                 $lockedRole->syncPermissions($permissions);
109:             }
110: 
111:             return null;
112:         });
113: 
114:         if ($failure !== null) {
115:             return response()->json([
116:                 'message' => 'لا يمكن تعديل دور Super Admin الأساسي.',
117:             ], 403);
118:         }
119: 
120:         return RoleResource::make($role->refresh()->load('permissions'));
121:     }
122: 
123:     public function destroy(Role $role): JsonResponse|Response
124:     {
125:         $this->ensureStaffRole($role);
126: 
127:         $result = DB::transaction(function () use ($role): string {
128:             $lockedRole = Role::query()->whereKey($role->getKey())->lockForUpdate()->firstOrFail();
129:             $this->ensureStaffRole($lockedRole);
130: 
131:             if ($lockedRole->name === StaffRole::SuperAdmin->value) {
132:                 return 'protected';
133:             }
134: 
135:             if ($lockedRole->users()->exists()) {
136:                 return 'in_use';
137:             }
138: 
139:             $lockedRole->delete();
140: 
141:             return 'deleted';
142:         });
143: 
144:         if ($result === 'protected') {
145:             return response()->json([
146:                 'message' => 'لا يمكن حذف دور Super Admin الأساسي.',
147:             ], 403);
148:         }
149: 
150:         if ($result === 'in_use') {
151:             return response()->json([
152:                 'message' => 'لا يمكن حذف دور مسند إلى موظفين. انقل الموظفين إلى دور آخر أولًا.',
153:             ], 409);
154:         }
155: 
156:         return response()->noContent();
157:     }
158: 
159:     private function mayGrantPermissions(mixed $user, array $permissions): bool
160:     {
161:         if (! $user instanceof User) {
162:             return false;
163:         }
164: 
165:         return $user->hasRole(StaffRole::SuperAdmin->value, 'staff')
166:             || $user->hasAllPermissions($permissions);
167:     }
168: 
169:     private function ensureStaffRole(Role $role): void
170:     {
171:         abort_unless($role->guard_name === 'staff', 404);
172:     }
173: }

