 5: namespace App\Models\Concerns;
 6: 
 7: use Illuminate\Database\Eloquent\Model;
 8: 
 9: trait TracksEditVersion
10: {
11:     public static function bootTracksEditVersion(): void
12:     {
13:         static::updating(function (Model $model): void {
14:             // A timestamp rounded to seconds cannot distinguish two edits in
15:             // the same second. Updates occur under the service's row lock.
16:             $model->lock_version = (int) $model->getOriginal('lock_version') + 1;
17:         });
18:     }
19: }

