 5: namespace App\Rules;
 6: 
 7: use Closure;
 8: use Illuminate\Contracts\Validation\ValidationRule;
 9: use Illuminate\Http\UploadedFile;
10: 
11: class MaxImagePixels implements ValidationRule
12: {
13:     public function __construct(private int $maxPixels = 16000000) {}
14: 
15:     public function validate(string $attribute, mixed $value, Closure $fail): void
16:     {
17:         if (! $value instanceof UploadedFile) {
18:             return;
19:         }
20:         // F7: a single-color 6000x6000 PNG compresses under 5MB, so the
21:         // max:kilobytes rule cannot stop a decompression bomb — GD needs
22:         // ~144MB to rasterize it. Cap total pixels instead of edge length.
23:         $size = @getimagesize($value->getPathname());
24:         if (is_array($size) && $this->maxPixels < $size[0] * $size[1]) {
25:             $fail('الصورة تتجاوز الحد الأقصى لعدد البكسلات ('.number_format($this->maxPixels).').');
26:         }
27:     }
28: }

