 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Catalog;
 6: 
 7: use App\Enums\ProductStatus;
 8: use App\Exceptions\BusinessException;
 9: use App\Models\Category;
10: use App\Models\Product;
11: 
12: class CategoryHierarchy
13: {
14:     public static function snapshot(): array
15:     {
16:         return Category::query()->get(['id', 'parent_id', 'is_active'])->keyBy('id')->toArray();
17:     }
18: 
19:     public static function assertValid(array $nodes): void
20:     {
21:         foreach (array_keys($nodes) as $id) {
22:             $seen = [];
23:             while ($id !== null) {
24:                 if (isset($seen[$id])) {
25:                     throw new BusinessException('توجد دورة في شجرة الأقسام');
26:                 }
27:                 if (! isset($nodes[$id])) {
28:                     throw new BusinessException('القسم الأب غير موجود');
29:                 }
30:                 $seen[$id] = true;
31:                 if (count($seen) > 3) {
32:                     throw new BusinessException('أقصى عمق للأقسام 3 مستويات');
33:                 }
34:                 $id = $nodes[$id]['parent_id'];
35:             }
36:         }
37:     }
38: 
39:     public static function assertPublishedPathsActive(array $nodes): void
40:     {
41:         $categoryIds = Product::query()->where('status', ProductStatus::Published)->distinct()->pluck('category_id');
42:         foreach ($categoryIds as $id) {
43:             while ($id !== null) {
44:                 if (! isset($nodes[$id]) || ! $nodes[$id]['is_active']) {
45:                     throw new BusinessException('لا يمكن تعطيل أو نقل قسم يحتوي على منتجات منشورة إلى سلسلة أقسام غير نشطة');
46:                 }
47:                 $id = $nodes[$id]['parent_id'];
48:             }
49:         }
50:     }
51: 
52:     public static function activePath(?Category $category): bool
53:     {
54:         $seen = [];
55:         while ($category) {
56:             if (! $category->is_active || isset($seen[$category->id]) || count($seen) >= 3) {
57:                 return false;
58:             }
59:             $seen[$category->id] = true;
60:             if ($category->parent_id === null) {
61:                 return true;
62:             }
63:             $category = Category::find($category->parent_id);
64:         }
65: 
66:         return false;
67:     }
68: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Catalog;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\Product;
 9: 
10: /**
11:  * قواعد قابلية النشر: بتتفحص وقت النشر، وبتتعاد بعد أي تعديل على منتج منشور
12:  * عشان المنتج المنشور يفضل دايمًا مستوفي الشروط (H1).
13:  */
14: class ProductPublishabilityChecker
15: {
16:     public function assertPublishable(Product $product): void
17:     {
18:         // نشتغل على نسخة حديثة من قاعدة البيانات عشان الفحص يشوف آخر تعديلات
19:         $product = $product->fresh() ?? $product;
20: 
21:         $errors = [];
22:         $active = $product->variants()->where('is_active', true)->get();
23: 
24:         if ($active->isEmpty()) {
25:             $errors[] = 'يجب وجود متغير واحد نشط على الأقل';
26:         }
27:         if ($product->sales_channel->allowsRetail() && $active->contains(fn ($v) => ! $v->retail_price || $v->retail_price <= 0)) {
28:             $errors[] = 'كل المتغيرات النشطة لازم يكون لها سعر قطاعي';
29:         }
30:         if ($product->sales_channel->allowsWholesale() && $active->contains(fn ($v) => ! $v->wholesale_price || $v->wholesale_price <= 0)) {
31:             $errors[] = 'كل المتغيرات النشطة لازم يكون لها سعر جملة';
32:         }
33:         if (! $this->hasImages($product)) {
34:             $errors[] = 'يجب رفع صورة واحدة على الأقل';
35:         }
36:         if (! CategoryHierarchy::activePath($product->category)) {
37:             $errors[] = 'القسم أو أحد أقسامه الأب غير نشط';
38:         }
39: 
40:         if ($errors) {
41:             throw new BusinessException('لا يمكن نشر المنتج', ['status' => $errors]);
42:         }
43:     }
44: 
45:     public function hasImages(Product $product): bool
46:     {
47:         return $product->media()->where('collection_name', 'images')->exists()
48:             || $product->variants()->where('is_active', true)
49:                 ->whereHas('media', fn ($query) => $query->where('collection_name', 'images'))->exists();
50:     }
51: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: // بيولّد باركود EAN-13 داخلي. الباركود بيبدأ بـ 2، ودي البادئة المخصصة للاستخدام الداخلي.
 8: class BarcodeGenerator
 9: {
10:     public static function fromId(int $id): string
11:     {
12:         $base = '2'.str_pad((string) $id, 11, '0', STR_PAD_LEFT); // 12 رقم
13:         $sum = 0;
14:         for ($i = 0; $i < 12; $i++) {
15:             $d = (int) $base[$i];
16:             $sum += ($i % 2 === 0) ? $d : $d * 3;
17:         }
18: 
19:         return $base.((10 - ($sum % 10)) % 10);
20:     }
21: }

