 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Console\Commands;
 6: 
 7: use Illuminate\Console\Command;
 8: use Illuminate\Support\Facades\DB;
 9: use Illuminate\Support\Facades\Storage;
10: use Spatie\MediaLibrary\MediaCollections\Models\Media;
11: 
12: class BackfillMediaPathLayouts extends Command
13: {
14:     protected $signature = 'media:backfill-path-layouts';
15: 
16:     protected $description = 'Record existing numeric/UUID media layouts without moving files';
17: 
18:     public function handle(): int
19:     {
20:         $count = 0;
21:         Media::query()->whereNull('custom_properties->path_layout')->chunkById(100, function ($items) use (&$count): void {
22:             foreach ($items as $item) {
23:                 DB::transaction(function () use ($item, &$count): void {
24:                     $media = Media::whereKey($item->id)->lockForUpdate()->first();
25:                     if (! $media || $media->hasCustomProperty('path_layout')) {
26:                         return;
27:                     }
28:                     // One-time console probe (never at request time): legacy rows
29:                     // live under id/<file>, newer rows under uuid/<file>.
30:                     $layout = Storage::disk($media->disk)->exists($media->id.'/'.$media->file_name) ? 'id' : 'uuid';
31:                     $media->setCustomProperty('path_layout', $layout);
32:                     $media->save();
33:                     $count++;
34:                 });
35:             }
36:         });
37:         $this->info("Updated {$count} media layouts.");
38: 
39:         return self::SUCCESS;
40:     }
41: }

