 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Enums\PriceListType;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\Pricing\ImportPriceListItemsRequest;
10: use App\Http\Requests\Admin\Pricing\StorePriceListRequest;
11: use App\Http\Requests\Admin\Pricing\UpdatePriceListRequest;
12: use App\Http\Resources\Admin\PriceListResource;
13: use App\Models\PriceList;
14: use App\Services\PriceListService;
15: use Illuminate\Http\JsonResponse;
16: use Illuminate\Http\Request;
17: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
18: use Illuminate\Routing\Controllers\HasMiddleware;
19: use Illuminate\Routing\Controllers\Middleware;
20: use Illuminate\Validation\Rule;
21: use Symfony\Component\HttpFoundation\StreamedResponse;
22: 
23: class PriceListController extends Controller implements HasMiddleware
24: {
25:     public function __construct(private readonly PriceListService $priceLists) {}
26: 
27:     public static function middleware(): array
28:     {
29:         return [
30:             new Middleware('can:price_lists.view', only: ['index', 'show']),
31:             new Middleware('can:price_lists.create', only: ['store']),
32:             new Middleware('can:price_lists.update', only: ['update']),
33:             new Middleware('can:price_lists.delete', only: ['destroy']),
34:             new Middleware('can:price_lists.import', only: ['import']),
35:             new Middleware('can:price_lists.export', only: ['export']),
36:         ];
37:     }
38: 
39:     public function index(Request $request): AnonymousResourceCollection
40:     {
41:         $filters = $request->validate([
42:             'type' => ['nullable', Rule::in(array_column(PriceListType::cases(), 'value'))],
43:             'customer_id' => ['nullable', 'integer', 'min:1'],
44:             'customer_group_id' => ['nullable', 'integer', 'min:1'],
45:             'branch_id' => ['nullable', 'integer', 'min:1'],
46:             'is_active' => ['nullable', 'boolean'],
47:             'search' => ['nullable', 'string', 'max:100'],
48:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
49:         ]);
50: 
51:         return PriceListResource::collection($this->priceLists->paginate($filters, $request->user()));
52:     }
53: 
54:     public function store(StorePriceListRequest $request): JsonResponse
55:     {
56:         $priceList = $this->priceLists->create($request->validated(), $request->user());
57: 
58:         return PriceListResource::make($priceList)
59:             ->additional(['message' => 'تم إنشاء قائمة الأسعار بنجاح'])
60:             ->response()
61:             ->setStatusCode(201);
62:     }
63: 
64:     public function show(Request $request, PriceList $priceList): PriceListResource
65:     {
66:         return PriceListResource::make($this->priceLists->find($priceList->id, $request->user()));
67:     }
68: 
69:     public function update(UpdatePriceListRequest $request, PriceList $priceList): PriceListResource
70:     {
71:         return PriceListResource::make($this->priceLists->update($priceList, $request->validated(), $request->user()));
72:     }
73: 
74:     public function destroy(Request $request, PriceList $priceList): JsonResponse
75:     {
76:         $this->priceLists->delete($priceList, $request->user());
77: 
78:         return response()->json(['message' => 'تم حذف قائمة الأسعار بنجاح']);
79:     }
80: 
81:     /** استيراد أسعار من CSV (updateOrCreate على القائمة/المتغير/حد الكمية). */
82:     public function import(ImportPriceListItemsRequest $request, PriceList $priceList): JsonResponse
83:     {
84:         $report = $this->priceLists->importCsv($priceList, $request->file('file'), $request->user());
85: 
86:         return response()->json([
87:             'message' => 'تم تنفيذ الاستيراد',
88:             'data' => $report,
89:         ]);
90:     }
91: 
92:     /** تصدير عناصر القائمة كملف CSV قابل لإعادة الاستيراد. */
93:     public function export(Request $request, PriceList $priceList): StreamedResponse
94:     {
95:         return $this->priceLists->exportCsv($priceList, $request->user());
96:     }
97: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\StaffRole;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Requests\Api\V1\Admin\StoreUserRequest;
 10: use App\Http\Requests\Api\V1\Admin\UpdateUserRequest;
 11: use App\Http\Resources\Api\V1\Admin\UserResource;
 12: use App\Models\User;
 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 16: use Illuminate\Support\Arr;
 17: use Illuminate\Support\Facades\DB;
 18: use Illuminate\Validation\Rule;
 19: use Spatie\Permission\Models\Role;
 20: 
 21: class UserController extends Controller
 22: {
 23:     public function index(Request $request): AnonymousResourceCollection
 24:     {
 25:         $filters = $request->validate([
 26:             'branch_id' => ['sometimes', 'nullable', 'integer', Rule::exists('branches', 'id')],
 27:             'role' => [
 28:                 'sometimes',
 29:                 'nullable',
 30:                 'string',
 31:                 Rule::exists('roles', 'name')->where('guard_name', 'staff'),
 32:             ],
 33:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 34:         ]);
 35: 
 36:         $users = User::query()
 37:             ->with(['branch', 'roles'])
 38:             ->when(array_key_exists('branch_id', $filters), function ($query) use ($filters): void {
 39:                 if ($filters['branch_id'] === null) {
 40:                     $query->whereNull('branch_id');
 41: 
 42:                     return;
 43:                 }
 44: 
 45:                 $query->where('branch_id', $filters['branch_id']);
 46:             })
 47:             ->when(! empty($filters['role']), function ($query) use ($filters): void {
 48:                 $query->whereHas('roles', function ($roles) use ($filters): void {
 49:                     $roles->where('name', $filters['role'])->where('guard_name', 'staff');
 50:                 });
 51:             })
 52:             ->orderBy('id')
 53:             ->paginate($filters['per_page'] ?? 15)
 54:             ->withQueryString();
 55: 
 56:         return UserResource::collection($users);
 57:     }
 58: 
 59:     public function store(StoreUserRequest $request): JsonResponse
 60:     {
 61:         $validated = $request->validated();
 62:         $roles = $validated['roles'] ?? [];
 63:         $currentUser = $request->user('staff');
 64: 
 65:         if (
 66:             in_array(StaffRole::SuperAdmin->value, $roles, true)
 67:             && (! $currentUser instanceof User || ! $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff'))
 68:         ) {
 69:             return response()->json([
 70:                 'message' => 'يجب أن تكون Super Admin لإسناد هذا الدور.',
 71:             ], 403);
 72:         }
 73: 
 74:         if (! $this->mayManageUser($currentUser, roles: $roles)) {
 75:             return $this->insufficientPermissionsResponse();
 76:         }
 77: 
 78:         $userAttributes = Arr::except($validated, ['roles']);
 79:         $userAttributes['is_active'] ??= true;
 80: 
 81:         $user = DB::transaction(function () use ($userAttributes, $roles): User {
 82:             $user = User::create($userAttributes);
 83:             $user->syncRoles($roles);
 84: 
 85:             return $user->load(['branch', 'roles.permissions', 'permissions']);
 86:         });
 87: 
 88:         return UserResource::make($user)->response()->setStatusCode(201);
 89:     }
 90: 
 91:     public function show(User $user): UserResource
 92:     {
 93:         return UserResource::make($user->load(['branch', 'roles.permissions', 'permissions']));
 94:     }
 95: 
 96:     public function update(UpdateUserRequest $request, User $user): UserResource|JsonResponse
 97:     {
 98:         $validated = $request->validated();
 99:         $currentUser = $request->user('staff');
100:         $isCurrentUser = $currentUser instanceof User && $currentUser->is($user);
101: 
102:         if ($isCurrentUser && (array_key_exists('roles', $validated) || array_key_exists('is_active', $validated))) {
103:             return response()->json([
104:                 'message' => 'لا يمكنك تغيير أدوارك أو حالة تنشيط حسابك الحالي.',
105:             ], 403);
106:         }
107: 
108:         $roles = $validated['roles'] ?? null;
109:         $userAttributes = Arr::except($validated, ['roles']);
110: 
111:         if (array_key_exists('password', $userAttributes) && $userAttributes['password'] === null) {
112:             unset($userAttributes['password']);
113:         }
114: 
115:         $isSuperAdminRequester = $currentUser instanceof User
116:             && $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff');
117:         $assigningSuperAdmin = is_array($roles)
118:             && in_array(StaffRole::SuperAdmin->value, $roles, true);
119: 
120:         $failure = DB::transaction(function () use (
121:             $user,
122:             $userAttributes,
123:             $roles,
124:             $currentUser,
125:             $isSuperAdminRequester,
126:             $assigningSuperAdmin,
127:         ): ?string {
128:             $lockedUser = User::query()->whereKey($user->getKey())->lockForUpdate()->firstOrFail();
129:             $targetIsSuperAdmin = $lockedUser->hasRole(StaffRole::SuperAdmin->value, 'staff');
130: 
131:             if ($targetIsSuperAdmin && (
132:                 (array_key_exists('is_active', $userAttributes) && ! (bool) $userAttributes['is_active'])
133:                 || ($roles !== null && ! in_array(StaffRole::SuperAdmin->value, $roles, true))
134:             )) {
135:                 return 'protected_super_admin';
136:             }
137: 
138:             if (! $isSuperAdminRequester && (
139:                 $targetIsSuperAdmin || $assigningSuperAdmin
140:             )) {
141:                 return 'protected';
142:             }
143: 
144:             if (! $this->mayManageUser($currentUser, $lockedUser, $roles ?? [])) {
145:                 return 'insufficient_permissions';
146:             }
147: 
148:             $emailChanged = isset($userAttributes['email']) && $userAttributes['email'] !== $lockedUser->email;
149:             $lockedUser->update($userAttributes);
150: 
151:             if ($roles !== null) {
152:                 $lockedUser->syncRoles($roles);
153:             }
154: 
155:             $passwordChanged = array_key_exists('password', $userAttributes);
156:             $deactivated = array_key_exists('is_active', $userAttributes)
157:                 && ! (bool) $userAttributes['is_active'];
158: 
159:             if ($passwordChanged || $emailChanged || $deactivated) {
160:                 $lockedUser->tokens()->delete();
161:             }
162: 
163:             return null;
164:         });
165: 
166:         if ($failure !== null) {
167:             if ($failure === 'insufficient_permissions') {
168:                 return $this->insufficientPermissionsResponse();
169:             }
170: 
171:             return response()->json([
172:                 'message' => $failure === 'protected_super_admin'
173:                     ? 'لا يمكن تعطيل حساب Super Admin الأساسي أو إزالة دوره.'
174:                     : 'لا يمكن للمستخدم الحالي تعديل حساب Super Admin أو إسناد دوره.',
175:             ], 403);
176:         }
177: 
178:         return UserResource::make($user->refresh()->load(['branch', 'roles.permissions', 'permissions']));
179:     }
180: 
181:     public function destroy(Request $request, User $user): JsonResponse
182:     {
183:         $currentUser = $request->user('staff');
184: 
185:         if ($currentUser instanceof User && $currentUser->is($user)) {
186:             return response()->json([
187:                 'message' => 'لا يمكنك تعطيل حسابك الحالي.',
188:             ], 403);
189:         }
190: 
191:         $deleted = DB::transaction(function () use ($currentUser, $user): bool {
192:             $lockedUser = User::query()->whereKey($user->getKey())->lockForUpdate()->firstOrFail();
193: 
194:             if ($lockedUser->hasRole(StaffRole::SuperAdmin->value, 'staff')
195:                 || ! $this->mayManageUser($currentUser, $lockedUser)) {
196:                 return false;
197:             }
198: 
199:             $lockedUser->forceFill(['is_active' => false])->save();
200:             $lockedUser->tokens()->delete();
201: 
202:             return true;
203:         });
204: 
205:         if (! $deleted) {
206:             return response()->json([
207:                 'message' => 'لا يمكن تعطيل حساب Super Admin أو حساب يمتلك صلاحيات لا تملكها.',
208:             ], 403);
209:         }
210: 
211:         return response()->json([
212:             'message' => 'تم تعطيل حساب الموظف وإلغاء رموزه.',
213:             'data' => UserResource::make($user->refresh()->load(['branch', 'roles.permissions', 'permissions']))->resolve($request),
214:         ]);
215:     }
216: 
217:     /** @param list<string> $roles */
218:     private function mayManageUser(mixed $actor, ?User $target = null, array $roles = []): bool
219:     {
220:         if (! $actor instanceof User) {
221:             return false;
222:         }
223: 
224:         if ($actor->hasRole(StaffRole::SuperAdmin->value, 'staff')) {
225:             return true;
226:         }
227: 
228:         $permissions = Role::query()
229:             ->where('guard_name', 'staff')
230:             ->whereIn('name', $roles)
231:             ->with('permissions')
232:             ->get()
233:             ->flatMap(fn (Role $role) => $role->permissions->pluck('name'));
234: 
235:         if ($target !== null) {
236:             $permissions = $permissions->merge($target->getAllPermissions()->pluck('name'));
237:         }
238: 
239:         return $actor->hasAllPermissions($permissions->unique()->all());
240:     }
241: 
242:     private function insufficientPermissionsResponse(): JsonResponse
243:     {
244:         return response()->json([
245:             'message' => 'لا يمكنك إدارة حساب أو إسناد دور يمتلك صلاحيات لا تملكها.',
246:         ], 403);
247:     }
248: }

