 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Enums\WholesalePaymentNoticeStatus;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\ReviewPaymentNoticeRequest;
10: use App\Http\Resources\Wholesale\WholesalePaymentNoticeResource;
11: use App\Models\WholesalePaymentNotice;
12: use App\Services\WholesalePaymentNoticeService;
13: use Illuminate\Http\JsonResponse;
14: use Illuminate\Http\Request;
15: use Illuminate\Routing\Controllers\HasMiddleware;
16: use Illuminate\Routing\Controllers\Middleware;
17: use Illuminate\Validation\Rule;
18: 
19: class WholesalePaymentNoticeController extends Controller implements HasMiddleware
20: {
21:     public function __construct(private readonly WholesalePaymentNoticeService $service) {}
22: 
23:     public static function middleware(): array
24:     {
25:         return [
26:             new Middleware('can:payment_notices.view', only: ['index', 'show']),
27:             new Middleware('can:payment_notices.approve', only: ['approve']),
28:             new Middleware('can:payment_notices.reject', only: ['reject']),
29:         ];
30:     }
31: 
32:     public function index(Request $request): JsonResponse
33:     {
34:         $filters = $request->validate([
35:             'status' => ['nullable', Rule::in(array_column(WholesalePaymentNoticeStatus::cases(), 'value'))],
36:             'customer_id' => ['nullable', 'integer', 'min:1'],
37:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
38:         ]);
39: 
40:         $notices = WholesalePaymentNotice::query()
41:             ->with(['customer', 'order'])
42:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
43:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
44:             ->latest('id')
45:             ->paginate($filters['per_page'] ?? 15);
46: 
47:         return WholesalePaymentNoticeResource::collection($notices)->response();
48:     }
49: 
50:     public function show(int $paymentNotice): JsonResponse
51:     {
52:         $notice = WholesalePaymentNotice::query()
53:             ->with(['customer', 'order', 'treasury'])
54:             ->findOrFail($paymentNotice);
55: 
56:         return (new WholesalePaymentNoticeResource($notice))->response();
57:     }
58: 
59:     public function approve(ReviewPaymentNoticeRequest $request, int $paymentNotice): JsonResponse
60:     {
61:         $notice = WholesalePaymentNotice::query()->findOrFail($paymentNotice);
62:         $data = $request->validated();
63: 
64:         $approved = $this->service->approve(
65:             $notice,
66:             (int) $request->user()->id,
67:             isset($data['treasury_id']) ? (int) $data['treasury_id'] : null,
68:             $data['admin_notes'] ?? null,
69:         );
70: 
71:         return (new WholesalePaymentNoticeResource($approved))->response();
72:     }
73: 
74:     public function reject(ReviewPaymentNoticeRequest $request, int $paymentNotice): JsonResponse
75:     {
76:         $notice = WholesalePaymentNotice::query()->findOrFail($paymentNotice);
77: 
78:         $rejected = $this->service->reject($notice, (int) $request->user()->id, $request->validated('admin_notes'));
79: 
80:         return (new WholesalePaymentNoticeResource($rejected))->response();
81:     }
82: }

