13: 
14: /**
15:  * يتحقق من أن الكاشير لديه وردية مفتوحة في الفرع المسجل دخوله.
16:  * يُحقن الوردية في الطلب تحت المفتاح 'pos_shift' لاستخدامها في المتحكمات.
17:  */
18: class EnsureOpenPosShift
19: {
20:     public function handle(Request $request, Closure $next): Response
21:     {
22:         $user = $request->user('staff');
23: 
24:         if (! $user instanceof User || $user->branch_id === null) {
25:             return response()->json([
26:                 'message' => 'لا يمكن استخدام نقطة البيع بدون ارتباط بفرع.',
27:             ], 403);
28:         }
29: 
30:         $shift = PosShift::query()
31:             ->where('user_id', $user->id)
32:             ->where('branch_id', $user->branch_id)
33:             ->where('status', PosShiftStatus::Open)
34:             ->latest('id')
35:             ->first();
36: 
37:         if ($shift === null) {
38:             return response()->json([
39:                 'message' => 'لا توجد وردية مفتوحة. افتح وردية أولًا لإتمام العملية.',
40:                 'code'    => 'no_open_shift',
41:             ], 403);
42:         }
43: 
44:         $request->attributes->set('pos_shift', $shift);
45: 
46:         return $next($request);
47:     }
48: }

