 4: 
 5: namespace App\Http\Requests\Admin\Product;
 6: 
 7: use App\Enums\SalesChannel;
 8: use App\Http\Requests\Admin\Concerns\LimitsArrayInput;
 9: use App\Http\Requests\Admin\Variant\VariantRules;
10: use App\Models\Product;
11: use App\Rules\UniqueCatalogIdentifier;
12: use Illuminate\Contracts\Validation\ValidationRule;
13: use Illuminate\Foundation\Http\FormRequest;
14: use Illuminate\Support\Str;
15: use Illuminate\Validation\Rule;
16: use Illuminate\Validation\Rules\Unique;
17: 
18: class StoreProductRequest extends FormRequest
19: {
20:     use LimitsArrayInput;
21: 
22:     protected function arrayLimits(): array
23:     {
24:         return ['variants' => 100];
25:     }
26: 
27:     public function authorize(): bool
28:     {
29:         return $this->user() !== null;
30:     }
31: 
32:     /**
33:      * @return array<string, array<mixed>|string|ValidationRule>
34:      */
35:     public function rules(): array
36:     {
37:         $rules = [
38:             'category_id' => ['required', 'integer', Rule::exists('categories', 'id')->whereNull('deleted_at')],
39:             'brand_id' => ['prohibited'],
40:             'supplier_id' => ['prohibited'],
41:             'name_ar' => ['required', 'string', 'max:255'],
42:             'name_en' => ['required', 'string', 'max:255'],
43:             'slug' => ['nullable', 'alpha_dash:ascii', 'max:255', new UniqueCatalogIdentifier('products', 'slug')],
44:             'description_ar' => ['nullable', 'string'],
45:             'description_en' => ['nullable', 'string'],
46:             'material_ar' => ['nullable', 'string', 'max:150'],
47:             'material_en' => ['nullable', 'string', 'max:150'],
48:             'length_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
49:             'width_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
50:             'height_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
51:             'weight_kg' => ['nullable', 'numeric', 'min:0', 'max:99999.999'],
52:             'warranty_months' => ['nullable', 'integer', 'min:0', 'max:120'],
53:             'warranty_details' => ['nullable', 'string', 'max:255'],
54:             'country_of_origin' => ['nullable', 'string', 'max:100'],
55:             'status' => ['nullable', Rule::in(['draft'])],
56:             // F9: idempotency key for product creation — one UUID per creation
57:             // session, reused across retries so a lost response cannot duplicate.
58:             'create_key' => ['nullable', 'uuid'],
59:             'sales_channel' => ['required', Rule::enum(SalesChannel::class)],
60:             'is_featured' => ['nullable', 'boolean'],
61:             // اختياري: متغيرات مع الإنشاء
62:             'variants' => ['nullable', 'array', 'max:100'],
63:             'variants.*' => ['array:'.implode(',', array_keys(VariantRules::base()))],
64:         ];
65: 
66:         foreach (VariantRules::base(null, 'variants.*.') as $field => $rule) {
67:             if (in_array($field, ['sku', 'barcode'], true)) {
68:                 $rule[] = 'distinct';
69:             }
70:             $rules["variants.*.$field"] = $rule;
71:         }
72: 
73:         // A replay with an explicit slug/SKU now legitimately collides with
74:         // its own saved rows. The service verifies the request fingerprint
75:         // and returns the saved product before any write.
76:         $key = $this->input('create_key');
77:         if (is_string($key) && Str::isUuid($key)
78:             && Product::withTrashed()->where('created_by', $this->user()->id)->where('create_key', $key)->exists()) {
79:             foreach ($rules as $field => $rule) {
80:                 if (is_array($rule)) {
81:                     $rules[$field] = array_values(array_filter($rule, fn ($item) => ! $item instanceof UniqueCatalogIdentifier
82:                         && ! $item instanceof Unique));
83:                 }
84:             }
85:         }
86: 
87:         return $rules;
88:     }
89: }

