22:     public function authorize(): bool
23:     {
24:         return $this->user() !== null;
25:     }
26: 
27:     /**
28:      * @return array<string, array<int, mixed>>
29:      */
30:     public function rules(): array
31:     {
32:         return [
33:             'name' => ['sometimes', 'required', 'string', 'max:255'],
34:             'email' => [
35:                 'sometimes',
36:                 'required',
37:                 'email',
38:                 'max:255',
39:                 Rule::unique('users', 'email')->ignore($this->route('user')),
40:                 new EmailNotUsedByOtherAccountType('users'),
41:             ],
42:             'phone' => ['sometimes', 'nullable', 'string', 'max:30'],
43:             'password' => ['sometimes', 'nullable', 'string', 'min:8', 'max:255'],
44:             'branch_id' => ['sometimes', 'nullable', 'integer', Rule::exists('branches', 'id')],
45:             'is_active' => ['sometimes', 'boolean'],
46:             'roles' => ['sometimes', 'array'],
47:             'roles.*' => [
48:                 'string',
49:                 'distinct',
50:                 Rule::exists('roles', 'name')->where('guard_name', 'staff'),
51:             ],
52:         ];
53:     }
54: }

