10: use Illuminate\Database\Eloquent\Relations\HasMany;
11: use Illuminate\Database\Eloquent\SoftDeletes;
12: use Spatie\Image\Enums\Fit;
13: use Spatie\MediaLibrary\HasMedia;
14: use Spatie\MediaLibrary\InteractsWithMedia;
15: use Spatie\MediaLibrary\MediaCollections\Models\Media;
16: 
17: class Brand extends Model implements HasMedia
18: {
19:     /** @use HasFactory<BrandFactory> */
20:     use HasFactory, InteractsWithMedia, SoftDeletes;
21: 
22:     protected $fillable = ['name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order', 'is_active'];
23: 
24:     protected $casts = ['is_active' => 'boolean'];
25: 
26:     public function products(): HasMany
27:     {
28:         return $this->hasMany(Product::class);
29:     }
30: 
31:     public function registerMediaCollections(): void
32:     {
33:         $this->addMediaCollection('logo')->singleFile()->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
34:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
35:     }
36: 
37:     // L5: brand tiles render small thumbs — generate them once instead of
38:     // serving up-to-6000px originals in storefront tiles.
39:     public function registerMediaConversions(?Media $media = null): void
40:     {
41:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
42:             ->performOnCollections('logo');
43:         $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
44:             ->performOnCollections('logo');
45:     }
46: }

