  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services\Catalog;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Brand;
  9: use App\Services\SlugService;
 10: use Illuminate\Database\UniqueConstraintViolationException;
 11: use Illuminate\Http\UploadedFile;
 12: use Illuminate\Support\Facades\DB;
 13: 
 14: class BrandService
 15: {
 16:     public function create(array $data, ?UploadedFile $logo): Brand
 17:     {
 18:         // M1: retry once on auto-slug races; explicit conflicts surface as 409.
 19:         $autoSlug = empty($data['slug'] ?? null);
 20:         for ($attempt = 0; ; $attempt++) {
 21:             try {
 22:                 $brand = DB::transaction(function () use ($data) {
 23:                     unset($data['logo']);
 24:                     $data = array_filter($data, fn ($value) => $value !== null);
 25: 
 26:                     if (empty($data['slug'])) {
 27:                         $data['slug'] = SlugService::make(Brand::class, $data['name_en']);
 28:                     }
 29: 
 30:                     return Brand::create($data);
 31:                 });
 32: 
 33:                 // F2: the R2 upload runs outside the row lock, in its own
 34:                 // short transaction — network I/O must not hold the lock.
 35:                 if ($logo) {
 36:                     $this->attachLogo($brand, $logo);
 37:                 }
 38: 
 39:                 return $brand;
 40:             } catch (UniqueConstraintViolationException $e) {
 41:                 if ($autoSlug && $attempt === 0) {
 42:                     $data['slug'] = SlugService::make(Brand::class, $data['name_en']);
 43: 
 44:                     continue;
 45:                 }
 46:                 throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 47:             }
 48:         }
 49:     }
 50: 
 51:     public function update(Brand $brand, array $data, ?UploadedFile $logo): Brand
 52:     {
 53:         // F8: a concurrent update can win the slug between validation and the
 54:         // write — surface it as 409, not 500.
 55:         try {
 56:             $updated = DB::transaction(function () use ($brand, $data) {
 57:                 $brand = Brand::whereKey($brand->id)->lockForUpdate()->firstOrFail();
 58:                 unset($data['logo'], $data['remove_logo']);
 59: 
 60:                 if (array_key_exists('slug', $data) && empty($data['slug'])) {
 61:                     $data['slug'] = SlugService::make(Brand::class, $data['name_en'] ?? $brand->name_en, $brand->id);
 62:                 }
 63: 
 64:                 foreach (['sort_order', 'is_active'] as $field) {
 65:                     if (array_key_exists($field, $data) && $data[$field] === null) {
 66:                         unset($data[$field]);
 67:                     }
 68:                 }
 69: 
 70:                 $brand->update($data);
 71: 
 72:                 return $brand;
 73:             });
 74:         } catch (UniqueConstraintViolationException $e) {
 75:             throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 76:         }
 77: 
 78:         // F2: logo changes run outside the row lock (see create()).
 79:         $removeLogo = (bool) ($data['remove_logo'] ?? false);
 80:         if ($logo) {
 81:             $this->attachLogo($updated, $logo);
 82:         } elseif ($removeLogo) {
 83:             DB::transaction(fn () => $updated->clearMediaCollection('logo'));
 84:         }
 85: 
 86:         return $updated;
 87:     }
 88: 
 89:     /**
 90:      * F2: attach the logo in its own short transaction with no row lock.
 91:      * The logo is optional, so a failed upload keeps the saved row and
 92:      * reports a clear message instead of rolling back the data.
 93:      */
 94:     private function attachLogo(Brand $brand, UploadedFile $logo): void
 95:     {
 96:         try {
 97:             DB::transaction(fn () => $brand->addMedia($logo)->toMediaCollection('logo'));
 98:         } catch (\Throwable $e) {
 99:             report($e);
100:             throw new BusinessException('تم حفظ العلامة لكن فشل رفع الشعار؛ أعد رفعه من صفحة التعديل.', ['brand_id' => [$brand->id]], 422, 'brand_logo_failed');
101:         }
102:     }
103: 
104:     public function delete(Brand $brand): void
105:     {
106:         DB::transaction(function () use ($brand): void {
107:             // قفل الصف بيمنع حذف البراند في نفس لحظة إنشاء منتج عليه
108:             $locked = Brand::whereKey($brand->id)->lockForUpdate()->firstOrFail();
109: 
110:             if ($locked->products()->exists()) {
111:                 throw new BusinessException('لا يمكن حذف براند مرتبط بمنتجات');
112:             }
113: 
114:             $locked->delete();
115:         });
116:     }
117: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services\Catalog;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Product;
 10: use App\Models\ProductVariant;
 11: use Illuminate\Database\UniqueConstraintViolationException;
 12: use Illuminate\Http\UploadedFile;
 13: use Illuminate\Support\Collection;
 14: use Illuminate\Support\Facades\DB;
 15: use Spatie\MediaLibrary\MediaCollections\Models\Media;
 16: 
 17: class ProductMediaService
 18: {
 19:     public function index(Product $product): Collection
 20:     {
 21:         $variantIds = $product->variants()->withTrashed()->pluck('id');
 22:         $media = Media::query()
 23:             ->where(fn ($q) => $q->where(['model_type' => Product::class, 'model_id' => $product->id])
 24:                 ->orWhere(fn ($w) => $w->where('model_type', ProductVariant::class)->whereIn('model_id', $variantIds)))
 25:             ->orderBy('order_column')->orderBy('id')->get();
 26: 
 27:         return $media;
 28:     }
 29: 
 30:     public function upload(Product $product, array $data, array $files = [], ?UploadedFile $file = null): Collection
 31:     {
 32:         // H2: no product row lock here — uploads only append images, so they must
 33:         // not hold the product lock (and DB connection) while files stream to R2
 34:         // and conversions render. Delete/reorder keep their own locks.
 35:         $product = Product::whereKey($product->id)->firstOrFail();
 36:         $owner = ! empty($data['variant_id']) ? $product->variants()->findOrFail($data['variant_id']) : $product;
 37:         if ($data['collection'] === 'video') {
 38:             if ($owner instanceof ProductVariant) {
 39:                 throw new BusinessException('الفيديو للمنتج فقط');
 40:             }
 41: 
 42:             return DB::transaction(function () use ($product, $file) {
 43:                 $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 44: 
 45:                 return collect([$product->addMedia($file)->toMediaCollection('video')]);
 46:             });
 47:         }
 48: 
 49:         // H2 + M9: one short transaction per file; a retried client_upload_id
 50:         // replays the stored row instead of uploading a duplicate.
 51:         $clientIds = array_values((array) ($data['client_upload_ids'] ?? []));
 52: 
 53:         return collect(array_values($files))->map(fn ($image, $index) => $this->storeOne($owner, $image, $clientIds[$index] ?? null));
 54:     }
 55: 
 56:     private function storeOne(Product|ProductVariant $owner, UploadedFile $image, ?string $clientUploadId): Media
 57:     {
 58:         if (is_string($clientUploadId) && $clientUploadId !== '') {
 59:             $existing = Media::query()
 60:                 ->where('model_type', $owner->getMorphClass())
 61:                 ->where('model_id', $owner->getKey())
 62:                 ->where('custom_properties->client_upload_id', $clientUploadId)
 63:                 ->first();
 64:             if ($existing) {
 65:                 return $existing;
 66:             }
 67:         }
 68: 
 69:         try {
 70:             return DB::transaction(function () use ($owner, $image, $clientUploadId) {
 71:                 if (is_string($clientUploadId) && $clientUploadId !== '') {
 72:                     $existing = Media::query()
 73:                         ->where('model_type', $owner->getMorphClass())
 74:                         ->where('model_id', $owner->getKey())
 75:                         ->where('custom_properties->client_upload_id', $clientUploadId)
 76:                         ->lockForUpdate()
 77:                         ->first();
 78:                     if ($existing) {
 79:                         return $existing;
 80:                     }
 81: 
 82:                     return $owner->addMedia($image)->withCustomProperties(['client_upload_id' => $clientUploadId])->toMediaCollection('images');
 83:                 }
 84: 
 85:                 return $owner->addMedia($image)->toMediaCollection('images');
 86:             });
 87:         } catch (UniqueConstraintViolationException $exception) {
 88:             // Concurrent retry with the same client_upload_id: replay the winner.
 89:             $existing = Media::query()
 90:                 ->where('model_type', $owner->getMorphClass())
 91:                 ->where('model_id', $owner->getKey())
 92:                 ->where('custom_properties->client_upload_id', $clientUploadId)
 93:                 ->first();
 94:             if ($clientUploadId && $existing) {
 95:                 return $existing;
 96:             }
 97:             throw $exception;
 98:         }
 99:     }
100: 
101:     public function reorder(Product $product, array $ids): void
102:     {
103:         DB::transaction(function () use ($product, $ids): void {
104:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
105:             $this->assertMediaBelongs($product, $ids);
106:             Media::setNewOrder($ids);
107:         });
108:     }
109: 
110:     public function delete(Product $product, Media $media): void
111:     {
112:         DB::transaction(function () use ($product, $media): void {
113:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
114:             $media = Media::whereKey($media->id)->firstOrFail();
115:             $this->assertMediaBelongs($product, [$media->id]);
116:             $media->delete();
117:             if ($product->status === ProductStatus::Published && $media->collection_name === 'images'
118:                 && ! app(ProductPublishabilityChecker::class)->hasImages($product)) {
119:                 throw new BusinessException('لا يمكن حذف آخر صورة لمنتج منشور');
120:             }
121:         });
122:     }
123: 
124:     private function assertMediaBelongs(Product $product, array $ids): void
125:     {
126:         $variantIds = $product->variants()->withTrashed()->pluck('id')->all();
127:         $count = Media::whereIn('id', $ids)->where(fn ($q) => $q
128:             ->where(fn ($w) => $w->where('model_type', Product::class)->where('model_id', $product->id))
129:             ->orWhere(fn ($w) => $w->where('model_type', ProductVariant::class)->whereIn('model_id', $variantIds))
130:         )->count();
131:         if ($count !== count(array_unique($ids))) {
132:             abort(404, 'ملف غير تابع لهذا المنتج');
133:         }
134:     }
135: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Concerns;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\InventoryIdempotencyKey;
 9: use App\Services\BranchAccess;
10: use App\Services\IdempotencyFingerprint;
11: use Illuminate\Database\Eloquent\Model;
12: use Illuminate\Database\UniqueConstraintViolationException;
13: use Illuminate\Support\Facades\DB;
14: 
15: /**
16:  * إنشاء بمفتاح عدم تكرار لنهايات الإنشاء (تحويل/جرد): إعادة المحاولة بعد
17:  * timeout بنفس المفتاح تعيد النموذج المنشأ بدل نسخة مكررة، ونفس المفتاح
18:  * بحمولة مختلفة يُرفض 409. المفتاح يُدرج في نفس معاملة الإنشاء، ففشل
19:  * الإنشاء يلغيه معه (L-7 — نفس نمط مفتاح التسويات).
20:  */
21: trait HandlesIdempotentCreation
22: {
23:     /**
24:      * @param  list<string>  $relations
25:      * @param  callable(): Model  $creator
26:      */
27:     private function createIdempotently(string $context, array $payload, int $userId, ?string $idempotencyKey, string $modelClass, array $relations, callable $creator): Model
28:     {
29:         if ($idempotencyKey === null) {
30:             return $creator();
31:         }
32: 
33:         $requestHash = IdempotencyFingerprint::hash(['__context' => $context, 'payload' => $payload]);
34: 
35:         try {
36:             return DB::transaction(function () use ($userId, $idempotencyKey, $requestHash, $creator): Model {
37:                 $record = InventoryIdempotencyKey::query()->create([
38:                     'user_id' => $userId,
39:                     'key' => $idempotencyKey,
40:                     'request_hash' => $requestHash,
41:                 ]);
42: 
43:                 $model = $creator();
44: 
45:                 $record->update(['response' => [$model->id], 'status_code' => 201]);
46: 
47:                 return $model;
48:             });
49:         } catch (UniqueConstraintViolationException $e) {
50:             if (! str_contains($e->getMessage(), 'inventory_idempotency_keys_user_id_key_unique')) {
51:                 throw $e;
52:             }
53: 
54:             $record = InventoryIdempotencyKey::query()
55:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
56: 
57:             if ($record === null || ! hash_equals($record->request_hash, $requestHash)) {
58:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
59:             }
60: 
61:             $model = $modelClass::query()->with($relations)->findOrFail((int) ($record->response[0] ?? 0));
62:             app(BranchAccess::class)->assertBranch($userId, (int) ($model->getAttribute('branch_id') ?? $model->getAttribute('from_branch_id')));
63: 
64:             return $model;
65:         }
66:     }
67: }

