 8: use Spatie\MediaLibrary\Support\PathGenerator\PathGenerator;
 9: 
10: // مسارات الميديا بالـ uuid بدل الـ id المتسلسل، فصور المسودات مبتتخمنش بترقيم بسيط
11: class UuidPathGenerator implements PathGenerator
12: {
13:     public function getPath(Media $media): string
14:     {
15:         // M3: never hit the network here — this runs per URL (original + every
16:         // conversion). Legacy rows without a layout live under id/; the
17:         // media:backfill-path-layouts command persists the layout separately.
18:         if ($media->getCustomProperty('path_layout') === 'uuid' && $media->uuid) {
19:             return $media->uuid.'/';
20:         }
21: 
22:         return $media->id.'/';
23:     }
24: 
25:     public function getPathForConversions(Media $media): string
26:     {
27:         return $this->getPath($media).'conversions/';
28:     }
29: 
30:     public function getPathForResponsiveImages(Media $media): string
31:     {
32:         return $this->getPath($media).'responsive-images/';
33:     }
34: }

