 4: 
 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\CustomerGroup;
 9: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
10: use Illuminate\Database\QueryException;
11: use Illuminate\Support\Facades\DB;
12: 
13: class CustomerGroupService
14: {
15:     public function paginate(array $filters): LengthAwarePaginator
16:     {
17:         return CustomerGroup::query()
18:             ->withCount('customers')
19:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->where(fn ($search) => $search
20:                 ->whereLike('name', SearchTerm::pattern($v), caseSensitive: false)
21:                 ->orWhereLike('code', SearchTerm::pattern($v), caseSensitive: false)))
22:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
23:             ->orderBy('name')
24:             ->orderBy('id')
25:             ->paginate($filters['per_page'] ?? 15);
26:     }
27: 
28:     public function create(array $data): CustomerGroup
29:     {
30:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['discount_percentage', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
31: 
32:         return CustomerGroup::query()->create($data);
33:     }
34: 
35:     public function update(CustomerGroup $group, array $data): CustomerGroup
36:     {
37:         $group->update($data);
38: 
39:         return $group;
40:     }
41: 
42:     public function delete(CustomerGroup $group): void
43:     {
44:         try {
45:             DB::transaction(function () use ($group): void {
46:                 // قفل الصف قبل الفحص والحذف حتى لا يتسلل عميل/قائمة بينهما (L3):
47:                 // عميل يُضاف أثناء الحذف كان يفقد مجموعته بصمت عبر nullOnDelete.
48:                 $group = CustomerGroup::query()->lockForUpdate()->findOrFail($group->id);
49: 
50:                 if ($group->customers()->exists()) {
51:                     throw new BusinessException('لا يمكن حذف مجموعة مرتبطة بعملاء؛ انقل العملاء أولًا أو عطّل المجموعة.');
52:                 }
53: 
54:                 if ($group->priceLists()->exists()) {
55:                     throw new BusinessException('لا يمكن حذف مجموعة مرتبطة بقوائم أسعار.');
56:                 }
57: 
58:                 $group->delete();
59:             });
60:         } catch (QueryException $e) {
61:             // أي سباق متبقٍ عند قيد FK يظهر كـ 422 مفهوم لا 500
62:             if (($e->errorInfo[0] ?? $e->getCode()) === '23503') {
63:                 throw new BusinessException('لا يمكن حذف مجموعة مرتبطة بعملاء أو قوائم أسعار.');
64:             }
65: 
66:             throw $e;
67:         }
68:     }
69: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Customer;
  9: use App\Notifications\CustomerPhoneVerificationCode;
 10: use Illuminate\Http\Request;
 11: use Illuminate\Support\Facades\DB;
 12: use Illuminate\Support\Facades\Hash;
 13: use Illuminate\Support\Facades\Notification;
 14: use Illuminate\Support\Str;
 15: use Illuminate\Validation\ValidationException;
 16: 
 17: class CustomerPhoneVerificationService
 18: {
 19:     public function send(string $phone): void
 20:     {
 21:         if (Customer::withTrashed()->where('phone', $phone)->exists()) {
 22:             return;
 23:         }
 24:         $code = (string) random_int(100000, 999999);
 25:         $key = hash('sha256', $phone);
 26:         $created = DB::transaction(function () use ($key, $code): bool {
 27:             DB::table('customer_phone_verifications')->insertOrIgnore([
 28:                 'phone_key' => $key, 'code_hash' => '', 'created_at' => now()->subDay(), 'expires_at' => now()->subDay(),
 29:             ]);
 30:             $row = DB::table('customer_phone_verifications')->where('phone_key', $key)->lockForUpdate()->first();
 31:             if ($row->verified_at !== null && now()->lt($row->expires_at)) {
 32:                 return false;
 33:             }
 34:             if (now()->subSeconds(60)->lt($row->created_at) || ! app(CustomerMessageBudget::class)->claim('verify:'.$key)) {
 35:                 return false;
 36:             }
 37:             DB::table('customer_phone_verifications')->where('phone_key', $key)->update([
 38:                 'code_hash' => Hash::make($code), 'proof_hash' => null, 'attempts' => 0, 'verified_at' => null,
 39:                 'created_at' => now(), 'expires_at' => now()->addMinutes(10),
 40:             ]);
 41: 
 42:             return true;
 43:         });
 44:         if ($created) {
 45:             try {
 46:                 Notification::route('customer_sms', $phone)->notify(new CustomerPhoneVerificationCode($code));
 47:                 logger()->info('Customer OTP delivered.');
 48:             } catch (\Throwable $exception) {
 49:                 logger()->error('Customer OTP delivery failed.', ['exception' => $exception::class]);
 50:                 throw $exception;
 51:             }
 52:         }
 53:     }
 54: 
 55:     public function verify(string $phone, string $code): string
 56:     {
 57:         $proof = DB::transaction(function () use ($phone, $code): ?string {
 58:             $key = hash('sha256', $phone);
 59:             $row = DB::table('customer_phone_verifications')->where('phone_key', $key)->lockForUpdate()->first();
 60:             $valid = Hash::check($code, $row?->code_hash ?: CustomerAuthService::dummyHash());
 61:             if ($row === null || $row->attempts >= 5 || now()->gte($row->expires_at) || $row->verified_at !== null) {
 62:                 return null;
 63:             }
 64:             DB::table('customer_phone_verifications')->where('phone_key', $key)->increment('attempts');
 65:             if (! $valid) {
 66:                 return null;
 67:             }
 68:             $proof = Str::random(64);
 69:             DB::table('customer_phone_verifications')->where('phone_key', $key)->update([
 70:                 'proof_hash' => hash('sha256', $proof), 'verified_at' => now(), 'expires_at' => now()->addMinutes(10),
 71:             ]);
 72: 
 73:             return $proof;
 74:         });
 75:         if ($proof === null) {
 76:             throw new BusinessException('رمز التحقق غير صالح أو انتهت صلاحيته.');
 77:         }
 78: 
 79:         return $proof;
 80:     }
 81: 
 82:     public function requireProof(Request $request): void
 83:     {
 84:         if (! config('auth.require_phone_verification')) {
 85:             return;
 86:         }
 87:         $phone = $request->input('phone');
 88:         $proof = $request->input('phone_verification_token');
 89:         if (! is_string($phone) || ! is_string($proof) || strlen($proof) !== 64 || ! $this->validProof($phone, $proof)) {
 90:             throw ValidationException::withMessages(['phone_verification_token' => 'تحقق من ملكية رقم الهاتف أولًا.']);
 91:         }
 92:     }
 93: 
 94:     private function validProof(string $phone, string $proof, bool $consume = false): bool
 95:     {
 96:         $query = DB::table('customer_phone_verifications')->where('phone_key', hash('sha256', $phone));
 97:         $row = ($consume ? $query->lockForUpdate() : $query)->first();
 98:         $stored = $row?->proof_hash ?? '';
 99:         $matches = strlen($stored) === 64 ? hash_equals($stored, hash('sha256', $proof))
100:             : ($stored !== '' && Hash::check($proof, $stored));
101:         $valid = $matches && $row !== null && $row->verified_at !== null && now()->lt($row->expires_at);
102:         if ($valid && $consume) {
103:             $query->delete();
104:         }
105: 
106:         return $valid;
107:     }
108: 
109:     public function consume(array $data): bool
110:     {
111:         if (! config('auth.require_phone_verification')) {
112:             return false;
113:         }
114:         if (! $this->validProof($data['phone'], $data['phone_verification_token'] ?? '', true)) {
115:             throw new BusinessException('إثبات ملكية الهاتف غير صالح أو تم استخدامه.');
116:         }
117: 
118:         return true;
119:     }
120: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use Illuminate\Database\Eloquent\Model;
 9: use Illuminate\Support\Facades\DB;
10: 
11: class OperationIdempotencyService
12: {
13:     public function run(string $operation, Model $actor, ?string $key, array $payload, callable $execute): Model
14:     {
15:         if ($key === null || ! preg_match('/\A[A-Za-z0-9._:-]{1,128}\z/', $key)) {
16:             throw new BusinessException('ترويسة Idempotency-Key مطلوبة (حتى 128 حرفًا إنجليزيًا أو رقمًا).');
17:         }
18:         $scope = ['operation' => $operation, 'actor_type' => $actor->getMorphClass(), 'actor_id' => $actor->getKey(), 'key' => $key];
19:         $hash = IdempotencyFingerprint::hash($payload);
20: 
21:         return DB::transaction(function () use ($scope, $hash, $execute): Model {
22:             $inserted = DB::table('operation_idempotency_keys')->insertOrIgnore([
23:                 ...$scope, 'request_hash' => $hash, 'created_at' => now(),
24:             ]);
25:             $record = DB::table('operation_idempotency_keys')->where($scope)->lockForUpdate()->first();
26:             if (! $inserted) {
27:                 if (! hash_equals($record->request_hash, $hash)) {
28:                     throw new BusinessException('مفتاح عدم التكرار مستخدم مع بيانات مختلفة.', [], 409);
29:                 }
30:                 $result = $record->result_type::query()->find($record->result_id);
31:                 if ($result === null) {
32:                     throw new BusinessException('العملية سبق تنفيذها ثم أزيل مستندها؛ استخدم عملية جديدة.', [], 409);
33:                 }
34: 
35:                 return $result;
36:             }
37:             $result = $execute();
38:             DB::table('operation_idempotency_keys')->where($scope)->update([
39:                 'result_type' => $result::class, 'result_id' => $result->getKey(),
40:             ]);
41: 
42:             return $result;
43:         }, 3);
44:     }
45: }

