 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\Customer;
 9: use App\Models\ProductVariant;
10: use App\Models\StockLevel;
11: 
12: /**
13:  * صفوف قائمة أسعار الجملة لتاجر بعينه (المرحلة 12.2): كل متغير نشط لمنتج
14:  * منشور بسعره الخاص بهذا التاجر وشرائح كمياته — مصدر موحّد لتصديرَي
15:  * Excel وPDF حتى لا يختلفا أبدًا.
16:  */
17: class WholesalePriceListService
18: {
19:     public function __construct(private readonly PricingService $pricing) {}
20: 
21:     /**
22:      * @return list<array{sku: string, barcode: string|null, product_name: string|null, base_price: float|null, wholesale_price: float|null, tier_prices: list<array{min_qty: float, unit_price: float}>, available_qty: float}>
23:      */
24:     public function rows(Customer $customer): array
25:     {
26:         $variants = ProductVariant::query()->with('product')
27:             ->where('is_active', true)
28:             ->whereHas('product', fn ($q) => $q->where('status', 'published'))
29:             ->orderBy('sku')
30:             ->get();
31: 
32:         $availability = StockLevel::query()
33:             ->whereIn('product_variant_id', $variants->pluck('id')->all())
34:             ->groupBy('product_variant_id')
35:             ->selectRaw('product_variant_id, SUM(available) AS total_available')
36:             ->pluck('total_available', 'product_variant_id')
37:             ->map(fn ($v) => (float) $v)
38:             ->all();
39: 
40:         // F17: one context for the whole export, not one group lookup per row.
41:         $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());
42: 
43:         return $variants->map(function (ProductVariant $variant) use ($customer, $availability, $ctx): array {
44:             try {
45:                 $resolved = $this->pricing->resolve($variant, $customer, 1, null, $ctx);
46:                 $price = $resolved['unit_price'];
47:                 $base = $resolved['base_price'];
48:                 $tiers = $this->pricing->tiersFor($variant, $customer, $ctx);
49:             } catch (BusinessException) {
50:                 // متغير غير مُسعَّر: يظهر في القائمة بلا سعر بدل إسقاط التصدير كله
51:                 $price = null;
52:                 $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
53:                 $tiers = [];
54:             }
55: 
56:             return [
57:                 'sku' => $variant->sku,
58:                 'barcode' => $variant->barcode,
59:                 'product_name' => $variant->product?->name_ar,
60:                 'base_price' => $base,
61:                 'wholesale_price' => $price,
62:                 'tier_prices' => $tiers,
63:                 'available_qty' => $availability[$variant->id] ?? 0.0,
64:             ];
65:         })->all();
66:     }
67: }

