 96: // ---------- البراند ----------
 97: 
 98: export function brandFromApi(b: AdminBrand): UiBrand {
 99:   return {
100:     id: b.id,
101:     ar: b.name_ar, en: b.name_en, slug: b.slug,
102:     desc_ar: b.description_ar ?? '', desc_en: b.description_en ?? '',
103:     order: b.sort_order,
104:     status: b.is_active ? 'active' : 'inactive',
105:     logo: b.logo_url,
106:     products: b.products_count,
107:   };
108: }
109: 
110: export function brandToPayload(u: UiBrandForm): BrandPayload {
111:   const p: BrandPayload = {
112:     name_ar: u.ar,
113:     name_en: u.en,
114:     slug: u.slug.trim() === '' ? null : u.slug,   // فاضي = null والسيرفر يولّده
115:     description_ar: u.desc_ar,
116:     description_en: u.desc_en,
117:     sort_order: u.order,
118:     is_active: u.status === 'active',
119:   };
120:   if (u.logoFile) p.logo = u.logoFile;
121:   else if (u.removeLogo) p.remove_logo = true;    // شال اللوجو من غير رفع جديد
122:   return p;                                       // من غير لوجو جديد ماتبعتش logo خالص
123: }
124: 
125: // ---------- المنتج: قراءة ----------
126: 
127: interface ApiVariantLike {
128:   lock_version?: number;
129:   id: number; sku: string; barcode: string | null;
130:   color_name_ar?: string | null; color_name_en?: string | null; color_hex?: string | null;
131:   color?: { name_ar?: string | null; name_en?: string | null; hex?: string | null } | null;
132:   size: string | null; capacity: string | null;
133:   cost_price?: string | number | null;
134:   retail_price: string | number | null; wholesale_price: string | number | null; compare_at_price: string | number | null;
135:   reorder_level: number | null; weight_kg: string | number | null;
136:   sort_order: number; is_active: boolean;
137:   media?: AdminMedia[]; images?: AdminMedia[];
138: }
139: 
140: function variantMediaOf(v: ApiVariantLike): AdminMedia[] {
141:   return v.media ?? v.images ?? [];
142: }
143: 
144: export function productFromApi(
145:   product: AdminProduct,
146:   media: AdminMedia[] = [],
147:   opts: { canViewCost: boolean },
148: ): UiProductState {
149:   const apiVariants = (product.variants ?? []) as ApiVariantLike[];
150:   const sorted = [...apiVariants].sort((a, b) => a.sort_order - b.sort_order);
151: 
152:   const rows: UiVariantRow[] = sorted.map((v, i) => {
153:     const colorEn = v.color_name_en ?? v.color?.name_en ?? null;
154:     const colorAr = v.color_name_ar ?? v.color?.name_ar ?? null;
155:     const colorHex = v.color_hex ?? v.color?.hex ?? null;
156:     return {
157:       _id: `srv-${v.id}`,
158:       serverId: v.id,
159:       lock_version: v.lock_version,
160:       color: colorEn || colorAr || colorHex
161:         ? { ar: colorAr ?? '', en: colorEn ?? '', hex: colorHex ?? '' }
162:         : null,
163:       size: v.size ?? '', capacity: v.capacity ?? '',
164:       sku: v.sku ?? '', barcode: v.barcode ?? '',
165:       retail: str(v.retail_price), wholesale: str(v.wholesale_price),
166:       cost: opts.canViewCost ? str(v.cost_price ?? '') : '',
167:       compare: str(v.compare_at_price),
168:       weight: str(v.weight_kg), reorder: v.reorder_level === null || v.reorder_level === undefined ? '' : String(v.reorder_level),
169:       order: v.sort_order ?? i,
170:       status: v.is_active ? 'active' : 'inactive',
171:     };
172:   });
173: 
174:   // mode عند التحميل: متغير واحد من غير لون ولا مقاس ولا سعة = single
175:   const single = rows.length === 1 && rows[0].color === null && rows[0].size === '' && rows[0].capacity === '';
176:   const mode: 'single' | 'matrix' = single ? 'single' : 'matrix';
177: 
178:   // axes من القيم الفريدة: الألوان unique بـ color_name_en من غير حساسية حروف
179:   const seenColors = new Set<string>();
180:   const colors: UiColor[] = [];
181:   const sizes: string[] = [];
182:   const capacities: string[] = [];
183:   rows.forEach(r => {
184:     if (r.color && r.color.en.trim() !== '') {
185:       const k = r.color.en.trim().toLowerCase();
186:       if (!seenColors.has(k)) { seenColors.add(k); colors.push(r.color); }
187:     }
188:     if (r.size.trim() !== '' && !sizes.some(s => s.trim().toLowerCase() === r.size.trim().toLowerCase())) sizes.push(r.size);
189:     if (r.capacity.trim() !== '' && !capacities.some(c => c.trim().toLowerCase() === r.capacity.trim().toLowerCase())) capacities.push(r.capacity);
190:   });
191: 
192:   const byId = new Map(sorted.map(v => [v.id, v] as const));
193:   const general: UiMediaItem[] = media
194:     .filter(m => m.collection === 'images' && (m.variant_id === null || m.variant_id === undefined))
195:     .sort((a, b) => a.order - b.order)
196:     .map(m => ({
197:       id: `srv-${m.id}`, serverId: m.id,
198:       name: m.url.split('/').pop()?.split('?')[0] || `image-${m.id}`,
199:       status: 'done' as const, url: m.thumb_url || m.url,
200:     }));
201: 
202:   const byVariant: Record<string, UiMediaItem[]> = {};
203:   media
204:     .filter(m => m.collection === 'images' && m.variant_id !== null && m.variant_id !== undefined)
205:     .sort((a, b) => a.order - b.order)
206:     .forEach(m => {
207:       const v = byId.get(m.variant_id as number);
208:       const colorEn = v ? (v.color_name_en ?? v.color?.name_en ?? '') : '';
209:       if (!colorEn) return;
210:       (byVariant[colorEn] = byVariant[colorEn] || []).push({
211:         id: `srv-${m.id}`, serverId: m.id, variantId: m.variant_id ?? undefined,
212:         name: m.url.split('/').pop()?.split('?')[0] || `image-${m.id}`,
213:         status: 'done' as const, url: m.thumb_url || m.url,
214:       });
215:     });
216: 
217:   const videoSrc = media.find(m => m.collection === 'video') ?? null;
218:   const d = product.dimensions ?? { length_cm: null, width_cm: null, height_cm: null };
219: 
220:   return {
221:     status: product.status, code: product.code,
222:     lock_version: product.lock_version, updated_at: product.updated_at,
223:     basic: {
224:       ar: product.name_ar, en: product.name_en,
225:       category: product.category?.id ?? null,
226:       brand: product.brand?.id ?? null,
227:       channel: product.sales_channel,
228:       slug: product.slug,
229:       desc_ar: product.description_ar ?? '', desc_en: product.description_en ?? '',
230:       mat_ar: product.material_ar ?? '', mat_en: product.material_en ?? '',
231:       l: str(d.length_cm), w: str(d.width_cm), h: str(d.height_cm),
232:       kg: str(product.weight_kg),
233:       warranty: product.warranty_months === null || product.warranty_months === undefined ? '' : String(product.warranty_months),
234:       warranty_details: product.warranty_details ?? '',
235:       origin: product.country_of_origin ?? '',
236:       featured: product.is_featured,
237:       supplier: product.supplier_id,
238:     },
239:     mode,
240:     axes: { colors, sizes, capacities },
241:     rows,
242:     media: {
243:       general, byVariant,
244:       video: videoSrc ? {
245:         id: `srv-${videoSrc.id}`, serverId: videoSrc.id,
246:         name: videoSrc.url.split('/').pop()?.split('?')[0] || `video-${videoSrc.id}`,
247:         status: 'done' as const, url: videoSrc.url,
248:       } : null,
249:     },
250:   };
