255: export function productToPayload(basic: UiBasic): ProductPayload {
256:   const numOrNull = (v: string): string | null => (v.trim() === '' ? null : v);
257:   return {
258:     name_ar: basic.ar,
259:     name_en: basic.en,
260:     slug: basic.slug.trim() === '' ? null : basic.slug,
261:     category_id: basic.category ?? undefined,
262:     description_ar: basic.desc_ar, description_en: basic.desc_en,
263:     material_ar: basic.mat_ar, material_en: basic.mat_en,
264:     length_cm: numOrNull(basic.l), width_cm: numOrNull(basic.w), height_cm: numOrNull(basic.h),
265:     weight_kg: numOrNull(basic.kg),
266:     warranty_months: basic.warranty.trim() === '' ? null : parseInt(basic.warranty, 10),
267:     warranty_details: basic.warranty_details,
268:     country_of_origin: basic.origin,
269:     sales_channel: basic.channel,
270:     is_featured: basic.featured,
271:   };
