274: export function variantToPayload(
275:   row: UiVariantRow & { sort?: number },
276:   opts: { canViewCost: boolean; isCreate: boolean },
277: ): VariantPayload {
278:   const p: VariantPayload = {};
279: 
280:   // sku: فاضي في الإنشاء = ماتبعتوش (السيرفر يولّده). وفي التعديل ماتبعتش فاضي أبدًا.
281:   if (row.sku.trim() !== '') p.sku = row.sku;
282:   if (row.barcode.trim() !== '') p.barcode = row.barcode;
283: 
284:   if (row.color) {
285:     if (row.color.ar.trim() !== '') p.color_name_ar = row.color.ar;
286:     else if (!opts.isCreate) p.color_name_ar = null;
287:     if (row.color.en.trim() !== '') p.color_name_en = row.color.en;
288:     else if (!opts.isCreate) p.color_name_en = null;
289:     if (row.color.hex.trim() !== '') p.color_hex = row.color.hex;
290:     else if (!opts.isCreate) p.color_hex = null;
291:   } else if (!opts.isCreate) {
292:     p.color_name_ar = null; p.color_name_en = null; p.color_hex = null;
293:   }
294: 
295:   p.size = nullIfEmpty(row.size);
296:   p.capacity = nullIfEmpty(row.capacity);
297: 
298:   // التكلفة: لو معندوش الصلاحية ماتحطش cost_price خالص (الـ backend بيشيله أصلًا بس ماتعتمدش على ده)
299:   if (opts.canViewCost) p.cost_price = nullIfEmpty(row.cost);
300: 
301:   p.retail_price = nullIfEmpty(row.retail);
302:   p.wholesale_price = nullIfEmpty(row.wholesale);
303:   p.compare_at_price = nullIfEmpty(row.compare);
304: 
305:   p.reorder_level = row.reorder.trim() === '' ? null : parseInt(row.reorder, 10);
306:   p.weight_kg = nullIfEmpty(row.weight);
307:   p.sort_order = typeof row.sort === 'number' ? row.sort : row.order;
308:   p.is_active = row.status === 'active';
309:   return p;
310: }
