 1: import { useEffect, useState } from 'react';
 2: import { isAxiosCancel } from '@alfarid/api-client';
 3: import { normalizeError, type ApiError } from './errors';
 4: 
 5: export function useApi<T>(fn: (signal: AbortSignal) => Promise<T>, deps: unknown[]) {
 6:   const [state, set] = useState<{ data?: T; loading: boolean; error?: ApiError }>({ loading: true });
 7:   const [tick, setTick] = useState(0);
 8:   useEffect(() => {
 9:     const ac = new AbortController();
10:     set(s => ({ ...s, loading: true, error: undefined }));   // خلي الداتا القديمة ظاهرة أثناء التحميل
11:     fn(ac.signal).then(data => { if (!ac.signal.aborted) set({ data, loading: false }); })
12:       .catch(e => { if (!ac.signal.aborted && !isAxiosCancel(e)) set(s => ({ ...s, loading: false, error: normalizeError(e) })); });
13:     return () => ac.abort();
14:     // eslint-disable-next-line react-hooks/exhaustive-deps
15:   }, [...deps, tick]);
16:   return { ...state, reload: () => setTick(t => t + 1) };
17: }

 1: const FIELD_MAP = {
 2:   name_ar: 'ar', name_en: 'en', slug: 'slug',
 3:   description_ar: 'desc_ar', description_en: 'desc_en',
 4:   sort_order: 'order', parent_id: 'parentId', is_active: 'status', image: 'img',
 5: };
 6: 
 7: const FALLBACK = {
 8:   0:   'تعذّر الاتصال بالخادم، تأكد من الإنترنت وحاول تاني',
 9:   403: 'ليس لديك صلاحية لتنفيذ هذا الإجراء',
10:   404: 'القسم غير موجود أو تم حذفه',
11:   409: 'البيانات اتغيرت من مستخدم تاني، حدّث الصفحة',
12:   422: 'البيانات غير صالحة',
13:   429: 'محاولات كتير، استنى شوية وحاول تاني',
14:   500: 'حصل خطأ في الخادم',
15: };
16: 
17: export function parseApiError(err) {
18:   const status = err?.response?.status ?? 0;
19:   const data = err?.response?.data ?? {};
20:   const fieldErrors = {};
21:   Object.entries(data.errors ?? {}).forEach(([k, msgs]) => {
22:     const key = FIELD_MAP[k] ?? (k.startsWith('items') ? 'items' : k);
23:     fieldErrors[key] = Array.isArray(msgs) ? msgs[0] : String(msgs);
24:   });
25:   return {
26:     status,
27:     message: data.message || FALLBACK[status] || FALLBACK[500],
28:     fieldErrors,
29:     isValidation: status === 422 && Object.keys(fieldErrors).length > 0,
30:   };
31: }

