 72:   show: (id: number, signal?: AbortSignal) =>
 73:     apiClient.get<{ data: Branch }>(`${BASE}/branches/${id}`, { signal }).then((r) => r.data.data),
 74:   create: (p: BranchPayload) =>
 75:     apiClient.post<{ data: Branch }>(`${BASE}/branches`, p).then((r) => r.data.data),
