 746:     /* Custom Range Slider for Manage Card Controls */
 747:     input[type="range"].v-slider {
 748:       -webkit-appearance: none;
 749:       appearance: none;
 750:       width: 100%;
 751:       height: 5px;
 752:       border-radius: 999px;
 753:       outline: none;
 754:       cursor: pointer;
 755:     }
 756:     input[type="range"].v-slider::-webkit-slider-thumb {
 757:       -webkit-appearance: none;
 758:       appearance: none;
 759:       width: 18px;
 760:       height: 18px;
 761:       border-radius: 50%;
 762:       background: #ffffff;
 763:       border: 3.5px solid #e0491f;
 764:       box-shadow: 0 2px 6px rgba(224, 73, 31, 0.35);
 765:       cursor: grab;
 766:       transition: transform 0.15s ease;
 767:     }
 768:     input[type="range"].v-slider::-webkit-slider-thumb:active {
 769:       cursor: grabbing;
 770:       transform: scale(1.12);
 771:     }
