3: 
4: export function cn(...inputs: ClassValue[]): string {
5:   return twMerge(clsx(inputs));
6: }

1: export * from './currency';
2: export * from './date';
3: export * from './enums';
4: export * from './permissions';

 1: /**
 2:  * Check if the staff user has a specific permission.
 3:  * Supports exact permission matches and wildcard matches (e.g. '*' or 'orders.*').
 4:  */
 5: export function hasPermission(
 6:   userPermissions: string[] | null | undefined,
 7:   requiredPermission: string
 8: ): boolean {
 9:   if (!userPermissions || !Array.isArray(userPermissions)) {
10:     return false;
11:   }
12: 
13:   if (userPermissions.includes('*') || userPermissions.includes('super_admin')) {
14:     return true;
15:   }
16: 
17:   if (userPermissions.includes(requiredPermission)) {
18:     return true;
19:   }
20: 
21:   const [module] = requiredPermission.split('.');
22:   if (module && userPermissions.includes(`${module}.*`)) {
23:     return true;
24:   }
25: 
26:   return false;
27: }
28: 
29: export function hasAnyPermission(
30:   userPermissions: string[] | null | undefined,
31:   requiredPermissions: string[]
32: ): boolean {
33:   return requiredPermissions.some((perm) => hasPermission(userPermissions, perm));
34: }
35: 
36: export function hasAllPermissions(
37:   userPermissions: string[] | null | undefined,
38:   requiredPermissions: string[]
39: ): boolean {
40:   return requiredPermissions.every((perm) => hasPermission(userPermissions, perm));
41: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Console\Commands;
 6: 
 7: use App\Services\Ai\GeminiClient;
 8: use App\Services\Ai\GeminiException;
 9: use Illuminate\Console\Command;
10: use Illuminate\Support\Facades\Http;
11: use Illuminate\Support\Facades\Storage;
12: use Illuminate\Support\Str;
13: use RuntimeException;
14: use Throwable;
15: 
16: class CheckIntegrations extends Command
17: {
18:     protected $signature = 'integrations:check {--live : Test R2 with a temporary image and send a minimal Gemini request}';
19: 
20:     protected $description = 'Verify R2 and Gemini configuration without displaying credentials';
21: 
22:     public function handle(GeminiClient $gemini): int
23:     {
24:         foreach (['key', 'secret', 'bucket', 'endpoint', 'root'] as $key) {
25:             if (! config('filesystems.disks.r2.'.$key)) {
26:                 $this->error('R2 configuration is incomplete.');
27: 
28:                 return self::FAILURE;
29:             }
30:         }
31:         if (! config('filesystems.disks.r2_public.bucket') || ! config('filesystems.disks.r2_public.url')
32:             || config('filesystems.disks.r2_public.bucket') === config('filesystems.disks.r2.bucket')) {
33:             $this->error('Catalog R2 requires a separate public bucket and its public URL.');
34: 
35:             return self::FAILURE;
36:         }
37:         if (! config('services.gemini.api_key') || ! config('services.gemini.model')) {
38:             $this->error('Gemini configuration is incomplete.');
39: 
40:             return self::FAILURE;
41:         }
42:         if (! $this->option('live')) {
43:             $this->info('R2 and Gemini are configured. Use --live to verify the services.');
44: 
45:             return self::SUCCESS;
46:         }
47: 
48:         $success = true;
49:         $path = '_setup-check/'.Str::uuid().'.png';
50:         $disk = Storage::disk('r2');
51:         $created = false;
52:         try {
53:             $image = base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jBZkAAAAASUVORK5CYII=');
54:             $created = $disk->put($path, $image, ['ContentType' => 'image/png']);
55:             if (! $created || $disk->get($path) !== $image) {
56:                 throw new RuntimeException('R2 verification failed.');
57:             }
58:             $response = Http::timeout(20)->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
59:                 ->get($disk->temporaryUrl($path, now()->addMinute()));
60:             if (! $response->successful() || $response->body() !== $image) {
61:                 throw new RuntimeException('R2 image URL verification failed.');
62:             }
63:             $this->info('R2 upload, download and signed image URL: OK.');
64:         } catch (Throwable) {
65:             $success = false;
66:             $this->error('R2 live check failed. Verify bucket access and endpoint settings.');
67:         } finally {
68:             if ($created) {
69:                 try {
70:                     if (! $disk->delete($path)) {
71:                         throw new RuntimeException('Cleanup failed.');
72:                     }
73:                 } catch (Throwable) {
74:                     $success = false;
75:                     $this->error('R2 verification image cleanup failed.');
76:                 }
77:             }
78:         }
79: 
80:         try {
81:             $gemini->generate('Reply with OK only.');
82:             $this->info('Gemini text generation: OK.');
83:         } catch (GeminiException $exception) {
84:             $success = false;
85:             $this->error('Gemini live check failed'.($exception->providerStatus ? ' (HTTP '.$exception->providerStatus.')' : '').'.');
86:         } catch (Throwable) {
87:             $success = false;
88:             $this->error('Gemini live check failed. Verify the model and API key settings.');
89:         }
90: 
91:         return $success ? self::SUCCESS : self::FAILURE;
92:     }
93: }

