 17: use Throwable;
 18: 
 19: class MigrateUploadsToR2 extends Command
 20: {
 21:     protected $signature = 'uploads:migrate-to-r2 {--delete-source : Remove local copies only after SHA-256 verification}';
 22: 
 23:     protected $description = 'Move existing catalog media and private uploads to R2 with content verification';
 24: 
 25:     public function handle(R2UploadMigration $migration): int
 26:     {
 27:         $count = 0;
 28:         $failures = [];
 29:         $catalogPrefixes = [];
 30:         Media::query()
 31:             ->chunkById(100, function ($items) use ($migration, &$count, &$failures, &$catalogPrefixes): void {
 32:                 foreach ($items as $item) {
 33:                     if ($this->targetDiskFor($item) === 'r2_public') {
 34:                         $catalogPrefixes[$item->id] = true;
 35:                         if ($item->uuid) {
 36:                             $catalogPrefixes[$item->uuid] = true;
 37:                         }
 38:                     }
 39:                     try {
 40:                         DB::transaction(function () use ($item, $migration, &$count): void {
 41:                             $media = Media::query()->lockForUpdate()->findOrFail($item->id);
 42:                             $target = $this->targetDiskFor($media);
 43:                             $base = app(UuidPathGenerator::class)->getPath($media);
 44:                             $rekey = $target === 'r2_public' && $base !== $media->uuid.'/';
 45:                             if ($media->disk === $target && ($media->conversions_disk ?: $media->disk) === $target && ! $rekey) {
 46:                                 return;
 47:                             }
 48:                             if ($rekey && ! $media->uuid) {
 49:                                 throw new \RuntimeException('Catalog media requires a UUID: '.$media->id);
 50:                             }
 51:                             $targetBase = $rekey ? $media->uuid.'/' : $base;
 52:                             if (! Storage::disk($media->disk)->exists($base.$media->file_name)) {
 53:                                 // M10: a single missing original must not abort the run;
 54:                                 // record it and continue with the next row.
 55:                                 throw new \RuntimeException('Missing media original; record unchanged: '.$media->id);
 56:                             }
 57:                             $sources = $media->getCustomProperty('r2_migration_sources', []);
 58:                             foreach (array_unique([$media->disk, $media->conversions_disk ?: $media->disk]) as $disk) {
 59:                                 if ($disk === $target && ! $rekey) {
 60:                                     continue;
 61:                                 }
 62:                                 foreach (Storage::disk($disk)->allFiles(rtrim($base, '/')) as $path) {
 63:                                     $targetPath = $targetBase.substr($path, strlen($base));
 64:                                     $migration->copy($disk, $path, $target, $targetPath);
 65:                                     $sources[] = [$disk, $path, $target, $targetPath];
 66:                                 }
 67:                             }
 68:                             $media->disk = $target;
 69:                             $media->conversions_disk = $target;
 70:                             if ($rekey) {
 71:                                 $media->setCustomProperty('path_layout', 'uuid');
 72:                             }
 73:                             $media->setCustomProperty('r2_migration_sources', $sources);
 74:                             $media->save();
 75:                             $count++;
 76:                         });
 77:                         if ($this->option('delete-source')) {
 78:                             $this->deleteSources($item->id, $migration);
 79:                         }
 80:                     } catch (Throwable $e) {
 81:                         $failures[] = $item->id.': '.$e->getMessage();
 82:                         $this->error('Skipped media '.$item->id.': '.$e->getMessage());
 83:                     }
 84:                 }
 85:             });
 86: 
 87:         // Include orphaned uploads, excluding certificates and application internals.
 88:         $directories = ['customer_documents', 'return_requests', 'supplier_deliveries', 'supplier_invoices', 'wholesale_payment_notices'];
 89:         foreach (['public', 'local'] as $disk) {
 90:             try {
 91:                 $paths = $disk === 'public' ? Storage::disk($disk)->allFiles() : collect($directories)
 92:                     ->flatMap(fn ($directory) => Storage::disk($disk)->allFiles($directory))->all();
 93:             } catch (Throwable $e) {
 94:                 $failures[] = $disk.': '.$e->getMessage();
 95:                 $this->error('Skipped disk '.$disk.': '.$e->getMessage());
 96: 
 97:                 continue;
 98:             }
 99:             foreach ($paths as $path) {
100:                 if (basename($path) === '.gitignore') {
101:                     continue;
102:                 }
103:                 if ($disk === 'public' && isset($catalogPrefixes[explode('/', $path, 2)[0]])) {
104:                     continue;
105:                 }
106:                 try {
107:                     $migration->copy($disk, $path);
108:                     if ($this->option('delete-source')) {
109:                         $migration->deleteVerifiedSource($disk, $path);
110:                     }
111:                     $count++;
112:                 } catch (Throwable $e) {
113:                     $failures[] = $path.': '.$e->getMessage();
114:                     $this->error('Skipped file '.$path.': '.$e->getMessage());
115:                 }
116:             }
117:         }
118:         if ($failures !== []) {
119:             $this->error('R2 migration finished with '.count($failures).' failures; rerun after fixing them.');
120:             $this->info('R2 migration verified: '.$count.' media records / remaining files processed.');
121: 
122:             return self::FAILURE;
123:         }
124:         // M10: --delete-source only removes SHA-256-verified copies, and the app
125:         // reads private documents exclusively via Storage::disk('r2') — no
126:         // explicit local/public reads remain outside this command.
127:         $this->info('R2 migration verified: '.$count.' media records / remaining files processed.');
128: 
129:         return self::SUCCESS;
130:     }
131: 
132:     private function targetDiskFor(Media $media): string
133:     {
134:         // H5: catalog models land on the public bucket; everything else stays private.
135:         return in_array($media->model_type, [Product::class, ProductVariant::class, Category::class, Brand::class], true)
136:             ? 'r2_public'
137:             : 'r2';
138:     }
139: 
140:     private function deleteSources(int $id, R2UploadMigration $migration): void
141:     {
142:         // The manifest survives the metadata commit, so failed cleanup can be retried.
143:         DB::transaction(function () use ($id, $migration): void {
144:             $media = Media::query()->lockForUpdate()->findOrFail($id);
145:             if (! $media->hasCustomProperty('r2_migration_sources')) {
146:                 return;
147:             }
148:             foreach ($media->getCustomProperty('r2_migration_sources', []) as $source) {
149:                 $migration->deleteVerifiedSource(...$source);
150:             }
151:             $media->forgetCustomProperty('r2_migration_sources');
152:             $media->save();
153:         });
154:     }
155: }

