 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Pricing\StoreCustomerGroupRequest;
 9: use App\Http\Requests\Admin\Pricing\UpdateCustomerGroupRequest;
10: use App\Http\Resources\Admin\CustomerGroupResource;
11: use App\Models\CustomerGroup;
12: use App\Services\BranchAccess;
13: use App\Services\CustomerGroupService;
14: use Illuminate\Http\JsonResponse;
15: use Illuminate\Http\Request;
16: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
17: use Illuminate\Routing\Controllers\HasMiddleware;
18: use Illuminate\Routing\Controllers\Middleware;
19: 
20: class CustomerGroupController extends Controller implements HasMiddleware
21: {
22:     public function __construct(private readonly CustomerGroupService $groups) {}
23: 
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:customer_groups.view', only: ['index', 'show']),
28:             new Middleware('can:customer_groups.create', only: ['store']),
29:             new Middleware('can:customer_groups.update', only: ['update']),
30:             new Middleware('can:customer_groups.delete', only: ['destroy']),
31:         ];
32:     }
33: 
34:     public function index(Request $request): AnonymousResourceCollection
35:     {
36:         $filters = $request->validate([
37:             'search' => ['nullable', 'string', 'max:100'],
38:             'is_active' => ['nullable', 'boolean'],
39:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
40:         ]);
41: 
42:         return CustomerGroupResource::collection($this->groups->paginate($filters));
43:     }
44: 
45:     public function store(StoreCustomerGroupRequest $request): JsonResponse
46:     {
47:         app(BranchAccess::class)->assertCentralAccess($request->user());
48:         $group = $this->groups->create($request->validated());
49: 
50:         return CustomerGroupResource::make($group)
51:             ->additional(['message' => 'تم إنشاء مجموعة العملاء بنجاح'])
52:             ->response()
53:             ->setStatusCode(201);
54:     }
55: 
56:     public function show(CustomerGroup $customerGroup): CustomerGroupResource
57:     {
58:         return CustomerGroupResource::make($customerGroup->loadCount('customers'));
59:     }
60: 
61:     public function update(UpdateCustomerGroupRequest $request, CustomerGroup $customerGroup): CustomerGroupResource
62:     {
63:         app(BranchAccess::class)->assertCentralAccess($request->user());
64: 
65:         return CustomerGroupResource::make($this->groups->update($customerGroup, $request->validated()));
66:     }
67: 
68:     public function destroy(Request $request, CustomerGroup $customerGroup): JsonResponse
69:     {
70:         app(BranchAccess::class)->assertCentralAccess($request->user());
71:         $this->groups->delete($customerGroup);
72: 
73:         return response()->json(['message' => 'تم حذف مجموعة العملاء بنجاح']);
74:     }
75: }

