  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\TreasuryTransactionType;
  8: use App\Http\Controllers\Controller;
  9: use App\Models\Expense;
 10: use App\Services\SearchTerm;
 11: use App\Services\SettingService;
 12: use App\Services\TreasuryService;
 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: use Illuminate\Routing\Controllers\HasMiddleware;
 16: use Illuminate\Routing\Controllers\Middleware;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: class ExpenseController extends Controller implements HasMiddleware
 20: {
 21:     public static function middleware(): array
 22:     {
 23:         return [
 24:             new Middleware('can:expenses.view', only: ['index', 'show']),
 25:             new Middleware('can:expenses.create', only: ['store']),
 26:             new Middleware('can:expenses.update', only: ['update']),
 27:             new Middleware('can:expenses.delete', only: ['destroy']),
 28:         ];
 29:     }
 30: 
 31:     public function __construct(
 32:         private readonly TreasuryService $treasury,
 33:         private readonly SettingService $settings,
 34:     ) {}
 35: 
 36:     public function index(Request $request): JsonResponse
 37:     {
 38:         $filters = $request->validate([
 39:             'branch_id' => ['nullable', 'integer', 'min:1'],
 40:             'treasury_id' => ['nullable', 'integer', 'min:1'],
 41:             'shift_id' => ['nullable', 'integer', 'min:1'],
 42:             'category' => ['nullable', 'string', 'max:100'],
 43:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 44:             'to_date' => ['nullable', 'date_format:Y-m-d'],
 45:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 46:         ]);
 47: 
 48:         $expenses = Expense::query()
 49:             ->with(['branch', 'treasury', 'creator'])
 50:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 51:             ->when($filters['treasury_id'] ?? null, fn ($q, $v) => $q->where('treasury_id', $v))
 52:             ->when($filters['shift_id'] ?? null, fn ($q, $v) => $q->where('shift_id', $v))
 53:             ->when($filters['category'] ?? null, fn ($q, $v) => $q->whereLike('category', SearchTerm::pattern($v), caseSensitive: false))
 54:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '>=', $v))
 55:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '<=', $v))
 56:             ->orderByDesc('id')
 57:             ->paginate($filters['per_page'] ?? 15);
 58: 
 59:         return response()->json($expenses);
 60:     }
 61: 
 62:     public function store(Request $request): JsonResponse
 63:     {
 64:         $data = $request->validate([
 65:             'branch_id' => ['required', 'integer', 'min:1', 'exists:branches,id'],
 66:             'treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id'],
 67:             'category' => ['required', 'string', 'max:191'],
 68:             'amount' => ['required', 'numeric', 'min:0.01', 'max:99999999'],
 69:             'expense_date' => ['required', 'date_format:Y-m-d'],
 70:             'notes' => ['nullable', 'string', 'max:500'],
 71:         ]);
 72: 
 73:         $expense = DB::transaction(function () use ($data, $request): Expense {
 74:             $expenseNumber = $this->settings->generateNextNumber('expense');
 75: 
 76:             $expense = Expense::create([
 77:                 ...$data,
 78:                 'expense_number' => $expenseNumber,
 79:                 'created_by' => $request->user()->id,
 80:             ]);
 81: 
 82:             // خصم من الخزينة
 83:             $this->treasury->record([
 84:                 'treasury_id' => $data['treasury_id'],
 85:                 'type' => TreasuryTransactionType::Expense,
 86:                 'amount' => -(float) $data['amount'],
 87:                 'reference_type' => Expense::class,
 88:                 'reference_id' => $expense->id,
 89:                 'created_by' => $request->user()->id,
 90:                 'notes' => "مصروف إداري: {$data['category']} #{$expenseNumber}",
 91:             ]);
 92: 
 93:             return $expense;
 94:         });
 95: 
 96:         return response()->json([
 97:             'message' => 'تم تسجيل المصروف بنجاح.',
 98:             'data' => $expense->load(['branch', 'treasury', 'creator']),
 99:         ], 201);
100:     }
101: 
102:     public function show(Expense $expense): JsonResponse
103:     {
104:         return response()->json(['data' => $expense->load(['branch', 'treasury', 'shift', 'creator'])]);
105:     }
106: 
107:     public function update(Request $request, Expense $expense): JsonResponse
108:     {
109:         $data = $request->validate([
110:             'category' => ['sometimes', 'string', 'max:191'],
111:             'notes' => ['nullable', 'string', 'max:500'],
112:         ]);
113: 
114:         $expense->update($data);
115: 
116:         return response()->json(['message' => 'تم تحديث المصروف.', 'data' => $expense]);
117:     }
118: 
119:     public function destroy(Expense $expense): JsonResponse
120:     {
121:         $expense->delete();
122: 
123:         return response()->json(['message' => 'تم حذف المصروف.']);
124:     }
125: }

