 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Variant\StoreVariantRequest;
 9: use App\Http\Requests\Admin\Variant\UpdateVariantRequest;
10: use App\Http\Resources\Admin\VariantResource;
11: use App\Models\Product;
12: use App\Models\ProductVariant;
13: use App\Services\Catalog\VariantService;
14: use Illuminate\Http\JsonResponse;
15: use Illuminate\Http\Request;
16: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
17: use Illuminate\Routing\Controllers\HasMiddleware;
18: use Illuminate\Routing\Controllers\Middleware;
19: 
20: class ProductVariantController extends Controller implements HasMiddleware
21: {
22:     public function __construct(private VariantService $service) {}
23: 
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:products.view', only: ['index', 'show']),
28:             // تعديل المتغيرات معناه تعديل المنتج نفسه
29:             new Middleware('can:products.update', only: ['store', 'update', 'destroy']),
30:         ];
31:     }
32: 
33:     public function index(Product $product): AnonymousResourceCollection
34:     {
35:         return VariantResource::collection($product->variants()->with('media')->get());
36:     }
37: 
38:     public function store(StoreVariantRequest $request, Product $product): JsonResponse
39:     {
40:         $data = $this->filterCostPrice($request->validated(), $request);
41:         $variant = $this->service->create($product, $data);
42: 
43:         return $this->variantResource($variant, $product)->response()->setStatusCode(201);
44:     }
45: 
46:     public function show(Product $product, ProductVariant $variant): VariantResource
47:     {
48:         return $this->variantResource($variant, $product);
49:     }
50: 
51:     public function update(UpdateVariantRequest $request, Product $product, ProductVariant $variant): VariantResource
52:     {
53:         $data = $this->filterCostPrice($request->validated(), $request);
54:         $variant = $this->service->update($variant, $data);
55: 
56:         return $this->variantResource($variant, $product);
57:     }
58: 
59:     public function destroy(Product $product, ProductVariant $variant): JsonResponse
60:     {
61:         $this->service->delete($variant);
62: 
63:         return response()->json(['message' => 'تم الحذف']);
64:     }
65: 
66:     private function variantResource(ProductVariant $variant, Product $product): VariantResource
67:     {
68:         $variant->loadMissing('media');
69:         $variant->setRelation('product', $product);
70: 
71:         return VariantResource::make($variant);
72:     }
73: 
74:     /**
75:      * @param  array<string, mixed>  $data
76:      * @return array<string, mixed>
77:      */
78:     private function filterCostPrice(array $data, Request $request): array
79:     {
80:         if (! $request->user()->can('products.view_cost')) {
81:             unset($data['cost_price']);
82:         }
83: 
84:         return $data;
85:     }
86: }

