 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Promotion\PromotionRequest;
 9: use App\Http\Resources\Admin\PromotionResource;
10: use App\Models\Promotion;
11: use Illuminate\Http\JsonResponse;
12: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
13: use Illuminate\Routing\Controllers\HasMiddleware;
14: use Illuminate\Routing\Controllers\Middleware;
15: 
16: /** إدارة العروض التلقائية. */
17: class PromotionController extends Controller implements HasMiddleware
18: {
19:     public static function middleware(): array
20:     {
21:         return [
22:             new Middleware('can:promotions.view', only: ['index', 'show']),
23:             new Middleware('can:promotions.create', only: ['store']),
24:             new Middleware('can:promotions.update', only: ['update']),
25:             new Middleware('can:promotions.delete', only: ['destroy']),
26:         ];
27:     }
28: 
29:     public function index(): AnonymousResourceCollection
30:     {
31:         return PromotionResource::collection(Promotion::query()->latest('id')->paginate(20));
32:     }
33: 
34:     public function store(PromotionRequest $request): JsonResponse
35:     {
36:         $promotion = Promotion::create($this->withoutNulls($request->validated()));
37: 
38:         return PromotionResource::make($promotion)->response()->setStatusCode(201);
39:     }
40: 
41:     public function show(Promotion $promotion): PromotionResource
42:     {
43:         return PromotionResource::make($promotion);
44:     }
45: 
46:     public function update(PromotionRequest $request, Promotion $promotion): PromotionResource
47:     {
48:         $promotion->update($this->withoutNulls($request->validated()));
49: 
50:         return PromotionResource::make($promotion);
51:     }
52: 
53:     /**
54:      * ‏null صريح لحقول NOT NULL يُحذف من الحمولة بدل ما يكسر الحفظ بـ 500 (M8).
55:      *
56:      * @param  array<string, mixed>  $data
57:      * @return array<string, mixed>
58:      */
59:     private function withoutNulls(array $data): array
60:     {
61:         foreach (['value', 'applies_to', 'is_active'] as $key) {
62:             if (array_key_exists($key, $data) && $data[$key] === null) {
63:                 unset($data[$key]);
64:             }
65:         }
66: 
67:         return $data;
68:     }
69: 
70:     public function destroy(Promotion $promotion): JsonResponse
71:     {
72:         $promotion->delete();
73: 
74:         return response()->json(['message' => 'تم حذف العرض']);
75:     }
76: }

