34:         );
35:     }
36: 
37:     public function store(ShippingZoneRequest $request): JsonResponse
38:     {
39:         $data = $request->validated();
40:         $zone = DB::transaction(function () use ($data): ShippingZone {
41:             $zone = ShippingZone::create($data);
