 5: namespace App\Http\Controllers\Api\V1\Store;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Store\ProductFilterRequest;
 9: use App\Http\Resources\Store\StoreProductCardResource;
10: use App\Http\Resources\Store\StoreProductResource;
11: use App\Services\StoreCatalogService;
12: use Illuminate\Http\JsonResponse;
13: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
14: 
15: /** تصفح منتجات المتجر: قائمة بفلاتر، وصفحة منتج بالـ slug، ومنتجات مشابهة. كله عام. */
16: class ProductController extends Controller
17: {
18:     public function __construct(private readonly StoreCatalogService $catalog) {}
19: 
20:     public function index(ProductFilterRequest $request): AnonymousResourceCollection
21:     {
22:         $filters = $request->validated();
23:         $total = in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)
24:             && ! isset($filters['price_min']) && ! isset($filters['price_max'])
25:             ? fn () => $this->catalog->applyFilters($this->catalog->publishedQuery(), [...$filters, 'sort' => 'newest'])
26:                 ->reorder()->count('products.id') : null;
27:         $products = $this->catalog->applyFilters($this->catalog->publishedQuery(), $request->validated())
28:             ->paginate(20, total: $total)->withQueryString();
29: 
30:         return StoreProductCardResource::collection($products);
31:     }
32: 
33:     public function show(string $slug): StoreProductResource
34:     {
35:         $product = $this->catalog->publishedQuery()
36:             ->where('products.slug', $slug)
37:             ->firstOrFail();
38: 
39:         $resource = new StoreProductResource($product);
40:         $resource->availability = $this->catalog->availabilityMap($product->variants->pluck('id')->all());
41: 
42:         return $resource;
43:     }
44: 
45:     public function similar(string $slug): JsonResponse
46:     {
47:         $product = $this->catalog->publishedQuery()
48:             ->withoutEagerLoads()
49:             // F19: similar() only matches on category_id — brand links are
50:             // legacy (brand_id is always null), so don't select the column.
51:             ->select(['products.id', 'products.category_id'])
52:             ->where('products.slug', $slug)
53:             ->firstOrFail();
54: 
55:         return response()->json([
56:             'data' => StoreProductCardResource::collection($this->catalog->similar($product))->resolve(),
57:         ]);
58:     }
59: }

