 5: namespace App\Models;
 6: 
 7: use Database\Factories\CouponFactory;
 8: use Illuminate\Database\Eloquent\Factories\HasFactory;
 9: use Illuminate\Database\Eloquent\Model;
10: use Illuminate\Database\Eloquent\Relations\HasMany;
11: 
12: class Coupon extends Model
13: {
14:     /** @use HasFactory<CouponFactory> */
15:     use HasFactory;
16: 
17:     protected $fillable = [
18:         'code',
19:         'type',
20:         'value',
21:         'min_order_amount',
22:         'max_discount_amount',
23:         'usage_limit',
24:         'usage_limit_per_customer',
25:         'used_count',
26:         'starts_at',
27:         'ends_at',
28:         'is_active',
29:     ];
30: 
31:     protected static function booted(): void
32:     {
33:         static::saving(function (Coupon $coupon): void {
34:             $coupon->code = strtoupper(trim($coupon->code));
35:         });
36:     }
37: 
38:     protected function casts(): array
39:     {
40:         return [
41:             'value' => 'decimal:2',
42:             'min_order_amount' => 'decimal:2',
43:             'max_discount_amount' => 'decimal:2',
44:             'usage_limit' => 'integer',
45:             'usage_limit_per_customer' => 'integer',
46:             'used_count' => 'integer',
47:             'starts_at' => 'datetime',
48:             'ends_at' => 'datetime',
49:             'is_active' => 'boolean',
50:         ];
51:     }
52: 
53:     /** @return HasMany<CouponUsage, $this> */
54:     public function usages(): HasMany
55:     {
56:         return $this->hasMany(CouponUsage::class);
57:     }
58: 
59:     public function isRedeemableNow(): bool
60:     {
61:         if (! $this->is_active) {
62:             return false;
63:         }
64:         if ($this->starts_at !== null && $this->starts_at->isFuture()) {
65:             return false;
66:         }
67:         if ($this->ends_at !== null && $this->ends_at->isPast()) {
68:             return false;
69:         }
70: 
71:         return $this->usage_limit === null || $this->used_count < $this->usage_limit;
72:     }
73: }

