 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Notifications\Channels;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use Illuminate\Notifications\Notification;
 9: use Illuminate\Support\Facades\Http;
10: 
11: class CustomerSmsChannel
12: {
13:     public function send(object $customer, Notification $notification): void
14:     {
15:         $url = config('services.customer_sms.url');
16:         $token = config('services.customer_sms.token');
17:         if (! is_string($url) || ! str_starts_with($url, 'https://') || ! is_string($token) || $token === '') {
18:             throw new BusinessException('خدمة الرسائل النصية غير مهيأة حاليًا.', [], 503);
19:         }
20: 
21:         $response = Http::withToken($token)->connectTimeout(3)->timeout(10)->post($url, [
22:             'to' => $customer->routeNotificationFor('customer_sms', $notification) ?? $customer->phone,
23:             'message' => $notification->toSms($customer),
24:         ])->throw();
25:         if ($response->json('success') !== true) {
26:             throw new BusinessException('رفض مزود الرسائل إرسال الرسالة.', [], 503);
27:         }
28:     }
29: }

