 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Rules;
 6: 
 7: use Closure;
 8: use Illuminate\Contracts\Validation\ValidationRule;
 9: use Illuminate\Support\Facades\DB;
10: 
11: /** يمنع تسجيل بريد مستخدم أصلًا في نوع حساب آخر (users / supplier_users / customers). */
12: final class EmailNotUsedByOtherAccountType implements ValidationRule
13: {
14:     public function __construct(private readonly string $ownTable) {}
15: 
16:     public function validate(string $attribute, mixed $value, Closure $fail): void
17:     {
18:         if (! is_string($value) || trim($value) === '') {
19:             return;
20:         }
21:         $email = mb_strtolower(trim($value));
22:         foreach (['users', 'supplier_users', 'customers'] as $table) {
23:             if ($table === $this->ownTable) {
24:                 continue;
25:             }
26:             $query = DB::table($table)->whereRaw('LOWER(email) = ?', [$email]);
27:             if ($table === 'customers') {
28:                 $query->whereNull('deleted_at');
29:                 // M13: إيميل عميل غير موثّق لا يحجز الإيميل — أي شخص يسجل به
30:                 // مستقبلًا يمنع إنشاء حساب الموظف/المورد، والعميل نفسه لا
31:                 // يستطيع الدخول بهذا الإيميل أصلًا.
32:                 $query->whereNotNull('email_verified_at');
33:             }
34:             if ($query->exists()) {
35:                 $fail('هذا البريد مستخدم بحساب آخر في النظام.');
36: 
37:                 return;
38:             }
39:         }
40:     }
41: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services\Catalog;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Category;
  9: use App\Services\SlugService;
 10: use Illuminate\Database\UniqueConstraintViolationException;
 11: use Illuminate\Http\UploadedFile;
 12: use Illuminate\Support\Collection;
 13: use Illuminate\Support\Facades\DB;
 14: 
 15: class CategoryService
 16: {
 17:     public function create(array $data, ?UploadedFile $image): Category
 18:     {
 19:         // M1: retry once on auto-slug races; M5: shared tree lock + FOR SHARE on
 20:         // the parent — creating a leaf must not take the exclusive tree lock.
 21:         $autoSlug = empty($data['slug'] ?? null);
 22:         for ($attempt = 0; ; $attempt++) {
 23:             try {
 24:                 $category = DB::transaction(function () use ($data) {
 25:                     CatalogLock::tree(shared: true);
 26: 
 27:                     unset($data['image']);
 28:                     $data = array_filter($data, fn ($value) => $value !== null);
 29: 
 30:                     if (empty($data['slug'])) {
 31:                         $data['slug'] = SlugService::make(Category::class, $data['name_en']);
 32:                     }
 33: 
 34:                     if (! empty($data['parent_id'])) {
 35:                         $parent = Category::whereKey($data['parent_id'])->sharedLock()->firstOrFail();
 36:                         if ($parent->depth() >= 3) {
 37:                             throw new BusinessException('أقصى عمق للأقسام 3 مستويات');
 38:                         }
 39:                     }
 40: 
 41:                     return Category::create($data);
 42:                 });
 43: 
 44:                 // F2: the R2 upload (and any sync conversion) runs outside the
 45:                 // tree lock, in its own short transaction — network I/O must
 46:                 // not hold an advisory lock that serializes all catalog writes.
 47:                 if ($image) {
 48:                     $this->attachImage($category, $image);
 49:                 }
 50: 
 51:                 return $category;
 52:             } catch (UniqueConstraintViolationException $e) {
 53:                 if ($autoSlug && $attempt === 0) {
 54:                     $data['slug'] = SlugService::make(Category::class, $data['name_en']);
 55: 
 56:                     continue;
 57:                 }
 58:                 throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 59:             }
 60:         }
 61:     }
 62: 
 63:     public function update(Category $category, array $data, ?UploadedFile $image): Category
 64:     {
 65:         $removeImage = (bool) ($data['remove_image'] ?? false);
 66:         unset($data['image'], $data['remove_image']);
 67:         if (isset($data['parent_id'])) {
 68:             $data['parent_id'] = (int) $data['parent_id'];
 69:         }
 70: 
 71:         foreach (['sort_order', 'is_active'] as $field) {
 72:             if (array_key_exists($field, $data) && $data[$field] === null) {
 73:                 unset($data[$field]);
 74:             }
 75:         }
 76:         $apply = function (bool $exclusive) use ($category, $data): ?Category {
 77:             return DB::transaction(function () use ($category, $data, $exclusive) {
 78:                 CatalogLock::tree(shared: ! $exclusive);
 79:                 $category = Category::whereKey($category->id)->lockForUpdate()->firstOrFail();
 80:                 $parentChanged = array_key_exists('parent_id', $data) && $data['parent_id'] !== $category->parent_id;
 81:                 $activeChanged = isset($data['is_active']) && (bool) $data['is_active'] !== $category->is_active;
 82:                 if (($parentChanged || $activeChanged) && ! $exclusive) {
 83:                     return null;
 84:                 }
 85:                 if ($parentChanged || $activeChanged) {
 86:                     $nodes = CategoryHierarchy::snapshot();
 87:                     $nodes[$category->id] = array_replace($nodes[$category->id], array_intersect_key($data, array_flip(['parent_id', 'is_active'])));
 88:                     CategoryHierarchy::assertValid($nodes);
 89:                     CategoryHierarchy::assertPublishedPathsActive($nodes);
 90:                 }
 91:                 if (array_key_exists('slug', $data) && empty($data['slug'])) {
 92:                     $data['slug'] = SlugService::make(Category::class, $data['name_en'] ?? $category->name_en, $category->id);
 93:                 }
 94: 
 95:                 foreach (['sort_order', 'is_active'] as $field) {
 96:                     if (array_key_exists($field, $data) && $data[$field] === null) {
 97:                         unset($data[$field]);
 98:                     }
 99:                 }
100: 
101:                 $category->update($data);
102: 
103:                 return $category;
104:             });
105:         };
106: 
107:         // F8: a concurrent update can win the slug between validation and the
108:         // write — surface it as 409, not 500.
109:         try {
110:             $updated = $apply(false) ?? $apply(true);
111:         } catch (UniqueConstraintViolationException $e) {
112:             throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
113:         }
114: 
115:         // F2: image changes run outside the tree lock (see create()).
116:         if ($image) {
117:             $this->attachImage($updated, $image);
118:         } elseif ($removeImage) {
119:             DB::transaction(fn () => $updated->clearMediaCollection('image'));
120:         }
121: 
122:         return $updated;
123:     }
124: 
125:     /**
126:      * F2: attach the image in its own short transaction with no tree lock.
127:      * The image is optional, so a failed upload keeps the saved row and
128:      * reports a clear message instead of rolling back the data.
129:      */
130:     private function attachImage(Category $category, UploadedFile $image): void
131:     {
132:         try {
133:             DB::transaction(fn () => $category->addMedia($image)->toMediaCollection('image'));
134:         } catch (\Throwable $e) {
135:             report($e);
136:             throw new BusinessException('تم حفظ القسم لكن فشل رفع الصورة؛ أعد رفعها من صفحة التعديل.', ['category_id' => [$category->id]], 422, 'category_image_failed');
137:         }
138:     }
139: 
140:     public function delete(Category $category): void
141:     {
142:         DB::transaction(function () use ($category): void {
143:             $this->lockTree();
144:             $locked = Category::whereKey($category->id)->lockForUpdate()->firstOrFail();
145: 
146:             if ($locked->children()->exists()) {
147:                 throw new BusinessException('لا يمكن حذف قسم يحتوي على أقسام فرعية');
148:             }
149: 
150:             if ($locked->products()->exists()) {
151:                 throw new BusinessException('لا يمكن حذف قسم مرتبط بمنتجات');
152:             }
153: 
154:             $locked->delete();
155:         });
156:     }
157: 
158:     public function reorder(array $items): void
159:     {
160:         // Retry with an exclusive tree lock only if the fresh snapshot contains a move.
161:         // Never upgrade a shared advisory lock while retaining it.
162:         $apply = function (bool $exclusive) use ($items): bool {
163:             return DB::transaction(function () use ($items, $exclusive): bool {
164:                 CatalogLock::tree(shared: ! $exclusive);
165:                 $categories = Category::query()->get()->keyBy('id');
166:                 $nodes = $categories->toArray();
167:                 $moved = false;
168:                 foreach ($items as $item) {
169:                     if (! array_key_exists('parent_id', $item)) {
170:                         throw new BusinessException('يجب إرسال parent_id لكل عنصر في الترتيب');
171:                     }
172:                     $category = $categories->get($item['id']);
173:                     if (! $category) {
174:                         throw new BusinessException('القسم غير موجود', ['items' => ['أحد الأقسام لم يعد متاحًا']]);
175:                     }
176:                     $parentId = $item['parent_id'] === null ? null : (int) $item['parent_id'];
177:                     $moved = $moved || $parentId !== $category->parent_id;
178:                     $nodes[$category->id]['parent_id'] = $parentId;
179:                 }
180:                 if ($moved && ! $exclusive) {
181:                     return false;
182:                 }
183:                 if ($moved) {
184:                     CategoryHierarchy::assertValid($nodes);
185:                     CategoryHierarchy::assertPublishedPathsActive($nodes);
186:                 }
187:                 // M11: apply row updates in id order so concurrent order-only
188:                 // requests acquire row locks in the same order (no deadlock).
189:                 $ordered = collect($items)->sortBy('id')->values()->all();
190:                 foreach ($ordered as $item) {
191:                     $categories->get($item['id'])->update(['parent_id' => $nodes[$item['id']]['parent_id'], 'sort_order' => $item['sort_order']]);
192:                 }
193: 
194:                 return true;
195:             });
196:         };
197:         if (! $apply(false)) {
198:             $apply(true);
199:         }
200:     }
201: 
202:     public function tree(bool $onlyActive = false): Collection
203:     {
204:         $all = Category::query()->with('media')->withCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()])
205:             ->when($onlyActive, fn ($q) => $q->where('is_active', true))
206:             ->orderBy('sort_order')->orderBy('id')->get();
207:         $grouped = $all->groupBy('parent_id');
208:         $build = function ($parentId) use (&$build, $grouped) {
209:             return ($grouped[$parentId ?? ''] ?? collect())->map(function ($cat) use ($build) {
210:                 $cat->setRelation('children', $build($cat->id));
211: 
212:                 return $cat;
213:             })->values();
214:         };
215: 
216:         return $build(null);
217:     }
218: 
219:     public function assertValidParent(Category $category, ?int $parentId): void
220:     {
221:         $nodes = CategoryHierarchy::snapshot();
222:         $nodes[$category->id]['parent_id'] = $parentId;
223:         CategoryHierarchy::assertValid($nodes);
224:         CategoryHierarchy::assertPublishedPathsActive($nodes);
225:     }
226: 
227:     private function lockTree(): void
228:     {
229:         CatalogLock::tree();
230:     }
231: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services\Catalog;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Product;
 10: use App\Models\ProductVariant;
 11: use App\Models\StockLevel;
 12: use App\Services\BarcodeGenerator;
 13: use Illuminate\Database\UniqueConstraintViolationException;
 14: use Illuminate\Support\Facades\DB;
 15: 
 16: class VariantService
 17: {
 18:     public function __construct(private ProductPublishabilityChecker $publishability) {}
 19: 
 20:     public function create(Product $product, array $data): ProductVariant
 21:     {
 22:         $data = array_filter($data, fn ($value) => $value !== null);
 23: 
 24:         // M1: auto-SKU races retry once; explicit conflicts surface as 409.
 25:         $autoSku = empty($data['sku']);
 26:         for ($attempt = 0; ; $attempt++) {
 27:             try {
 28:                 return DB::transaction(function () use ($product, $data) {
 29:                     $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail(); // منع تكرار الترقيم
 30:                     $this->assertUniqueCombination($product, $data);
 31: 
 32:                     if (empty($data['sku'])) {
 33:                         $seq = $product->variants()->withTrashed()->count() + 1;
 34:                         do {
 35:                             $sku = $product->code.'-'.str_pad((string) $seq, 2, '0', STR_PAD_LEFT);
 36:                             $seq++;
 37:                         } while (ProductVariant::withTrashed()->where('sku', $sku)->exists());
 38:                         $data['sku'] = $sku;
 39:                     }
 40: 
 41:                     $variant = $product->variants()->create($data);
 42: 
 43:                     if (empty($variant->barcode)) {
 44:                         $variant->update(['barcode' => BarcodeGenerator::fromId($variant->id)]);
 45:                     }
 46: 
 47:                     // متغير جديد على منتج منشور لازم ميكسرش قواعد النشر، وإلا التعديل كله يتلغي
 48:                     if ($product->status === ProductStatus::Published) {
 49:                         $this->publishability->assertPublishable($product);
 50:                     }
 51: 
 52:                     return $variant;
 53:                 });
 54:             } catch (UniqueConstraintViolationException $e) {
 55:                 if ($autoSku && $attempt === 0) {
 56:                     continue;
 57:                 }
 58:                 throw new BusinessException('الـ SKU أو الباركود مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 59:             }
 60:         }
 61:     }
 62: 
 63:     public function update(ProductVariant $variant, array $data): ProductVariant
 64:     {
 65:         $expectedVersion = $data['expected_version'] ?? null;
 66:         unset($data['expected_version']);
 67:         foreach (['cost_price', 'reorder_level', 'sort_order', 'is_active'] as $field) {
 68:             if (array_key_exists($field, $data) && $data[$field] === null) {
 69:                 unset($data[$field]);
 70:             }
 71:         }
 72: 
 73:         // F8: a concurrent update can win the SKU/barcode between validation
 74:         // and the write — surface it as 409, not 500.
 75:         try {
 76:             return DB::transaction(function () use ($variant, $data, $expectedVersion) {
 77:                 $product = Product::whereKey($variant->product_id)->lockForUpdate()->firstOrFail();
 78:                 $variant = $product->variants()->whereKey($variant->id)->lockForUpdate()->firstOrFail();
 79:                 if ($expectedVersion !== null && (int) $expectedVersion !== (int) $variant->lock_version) {
 80:                     throw new BusinessException('المتغير تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
 81:                 }
 82:                 $this->assertUniqueCombination($product, array_merge($variant->only(['color_name_en', 'size', 'capacity']), $data), $variant->id);
 83: 
 84:                 if (array_key_exists('is_active', $data) && ! $data['is_active']) {
 85:                     $this->assertNotLastActiveOfPublished($variant);
 86:                 }
 87:                 if (array_key_exists('barcode', $data) && blank($data['barcode'])) {
 88:                     $data['barcode'] = BarcodeGenerator::fromId($variant->id);
 89:                 }
 90:                 $variant->update($data);
 91: 
 92:                 // أي تعديل على متغير منتج منشور بيعيد فحص قواعد النشر جوه نفس الـ transaction
 93:                 if ($product->status === ProductStatus::Published) {
 94:                     $this->publishability->assertPublishable($product);
 95:                 }
 96: 
 97:                 return $variant->fresh(['media', 'product']);
 98:             });
 99:         } catch (UniqueConstraintViolationException $e) {
100:             throw new BusinessException('الـ SKU أو الباركود مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
101:         }
102:     }
103: 
104:     public function delete(ProductVariant $variant): void
105:     {
106:         DB::transaction(function () use ($variant): void {
107:             $product = Product::whereKey($variant->product_id)->lockForUpdate()->firstOrFail();
108:             // H3: lock the variant rows (id-ordered) before the balance check so a
109:             // concurrent receipt serializes here; in READ COMMITTED the check then
110:             // sees its committed movement instead of a phantom zero.
111:             ProductVariant::whereKey($variant->id)->orderBy('id')->lockForUpdate()->firstOrFail();
112:             $variant = $product->variants()->whereKey($variant->id)->firstOrFail();
113:             $this->assertNotLastActiveOfPublished($variant);
114:             // متغير له رصيد في أي وعاء لا يُحذف: الحذف الناعم كان يحبس الرصيد
115:             // لأن فحوص وجود المتغير تستبعد المحذوف (M-9). صفِّ الرصيد أولًا.
116:             if (StockLevel::query()->where('product_variant_id', $variant->id)->hasNonZeroBalance()->exists()) {
117:                 throw new BusinessException('لا يمكن حذف متغير له رصيد مخزون؛ صفِّ رصيده أولًا أو عطّله بدلًا من حذفه.');
118:             }
119:             $variant->delete();
120: 
121:             if ($product->status === ProductStatus::Published) {
122:                 $this->publishability->assertPublishable($product);
123:             }
124:         });
125:     }
126: 
127:     private function assertUniqueCombination(Product $product, array $d, ?int $ignoreId = null): void
128:     {
129:         // المقارنة من غير حساسية لحالة الحروف: Black وblack نفس اللون
130:         $matchField = fn ($q, string $column, ?string $value) => $value === null
131:             ? $q->whereNull($column)
132:             : $q->whereRaw("lower({$column}) = ?", [mb_strtolower($value)]);
133: 
134:         $exists = $product->variants()
135:             ->when($ignoreId, fn ($q) => $q->where('id', '!=', $ignoreId))
136:             ->where(fn ($q) => $matchField($q, 'color_name_en', $d['color_name_en'] ?? null))
137:             ->where(fn ($q) => $matchField($q, 'size', $d['size'] ?? null))
138:             ->where(fn ($q) => $matchField($q, 'capacity', $d['capacity'] ?? null))
139:             ->exists();
140:         if ($exists) {
141:             throw new BusinessException('يوجد متغير بنفس اللون والمقاس والسعة لهذا المنتج');
142:         }
143:     }
144: 
145:     private function assertNotLastActiveOfPublished(ProductVariant $variant): void
146:     {
147:         $product = $variant->product;
148:         if ($product->status === ProductStatus::Published
149:             && $product->variants()->where('is_active', true)->where('id', '!=', $variant->id)->doesntExist()) {
150:             throw new BusinessException('لا يمكن حذف/تعطيل آخر متغير نشط في منتج منشور');
151:         }
152:     }
153: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Media;
 6: 
 7: use Spatie\MediaLibrary\Support\UrlGenerator\DefaultUrlGenerator;
 8: 
 9: class MediaUrlGenerator extends DefaultUrlGenerator
10: {
11:     public function getUrl(): string
12:     {
13:         // H5: the private disk always yields a temporary URL — even when a public
14:         // URL is configured — so enabling public catalog URLs can never leak
15:         // private documents. Catalog media lives on r2_public (stable public URLs).
16:         if ($this->getDiskName() === 'r2') {
17:             $ttl = max(60, min(604800, (int) config('filesystems.disks.r2.download_url_ttl_seconds', 3600)));
18: 
19:             return $this->getTemporaryUrl(now()->addSeconds($ttl));
20:         }
21: 
22:         return parent::getUrl();
23:     }
24: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Media;
 6: 
 7: use Illuminate\Support\Facades\Storage;
 8: use RuntimeException;
 9: 
10: class R2UploadMigration
11: {
12:     public function copy(string $disk, string $path, string $targetDisk = 'r2', ?string $targetPath = null): void
13:     {
14:         $targetPath ??= $path;
15:         $this->validateSource($disk, $path);
16:         $this->validateSource($targetDisk, $targetPath);
17:         $this->validateTarget($targetDisk);
18:         $hash = $this->hash($disk, $path);
19:         $target = Storage::disk($targetDisk);
20:         if (! $target->exists($targetPath)) {
21:             $stream = Storage::disk($disk)->readStream($path);
22:             try {
23:                 if (! $target->put($targetPath, $stream)) {
24:                     throw new RuntimeException('R2 upload failed: '.$path);
25:                 }
26:             } finally {
27:                 if (is_resource($stream)) {
28:                     fclose($stream);
29:                 }
30:             }
31:         }
32:         if (! hash_equals($hash, $this->hash($targetDisk, $targetPath))) {
33:             throw new RuntimeException('R2 content verification failed; source preserved: '.$path);
34:         }
35:     }
36: 
37:     public function deleteVerifiedSource(string $disk, string $path, string $targetDisk = 'r2', ?string $targetPath = null): void
38:     {
39:         $targetPath ??= $path;
40:         $this->validateSource($disk, $path);
41:         $this->validateSource($targetDisk, $targetPath);
42:         $this->validateTarget($targetDisk);
43:         if ($disk === $targetDisk && $path === $targetPath) {
44:             throw new RuntimeException('Cannot delete the active target.');
45:         }
46:         if (! Storage::disk($disk)->exists($path)) {
47:             return;
48:         }
49:         if (! hash_equals($this->hash($disk, $path), $this->hash($targetDisk, $targetPath))) {
50:             throw new RuntimeException('Source changed; local copy preserved: '.$path);
51:         }
52:         if (! Storage::disk($disk)->delete($path)) {
53:             throw new RuntimeException('Could not remove verified source: '.$path);
54:         }
55:     }
56: 
57:     private function validateTarget(string $targetDisk): void
58:     {
59:         if (! in_array($targetDisk, ['r2', 'r2_public'], true)) {
60:             throw new RuntimeException('Unsupported R2 target.');
61:         }
62:         if ($targetDisk === 'r2_public' && config('filesystems.disks.r2_public.bucket')
63:             && config('filesystems.disks.r2_public.bucket') === config('filesystems.disks.r2.bucket')) {
64:             throw new RuntimeException('Catalog media requires a separate public R2 bucket.');
65:         }
66:     }
67: 
68:     private function validateSource(string $disk, string $path): void
69:     {
70:         if (! in_array($disk, ['local', 'public', 'r2', 'r2_public'], true) || str_contains($path, '..') || str_starts_with($path, '/')) {
71:             throw new RuntimeException('Unsupported upload source.');
72:         }
73:     }
74: 
75:     private function hash(string $disk, string $path): string
76:     {
77:         $stream = Storage::disk($disk)->readStream($path);
78:         if (! is_resource($stream)) {
79:             throw new RuntimeException('Missing or unreadable upload: '.$path);
80:         }
81:         try {
82:             $context = hash_init('sha256');
83:             hash_update_stream($context, $stream);
84: 
85:             return hash_final($context);
86:         } finally {
87:             fclose($stream);
88:         }
89:     }
90: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Media;
 6: 
 7: use Spatie\MediaLibrary\MediaCollections\Filesystem;
 8: use Spatie\MediaLibrary\MediaCollections\Models\Media;
 9: use Spatie\MediaLibrary\MediaCollections\Models\Observers\MediaObserver;
10: 
11: class TransactionalMediaObserver extends MediaObserver
12: {
13:     public function creating(Media $media): void
14:     {
15:         // H5: catalog collections (Product/Variant/Category/Brand) use the public
16:         // bucket; everything else stays on the private bucket.
17:         if (! in_array($media->disk, ['r2', 'r2_public'], true)
18:             || ($media->conversions_disk && ! in_array($media->conversions_disk, ['r2', 'r2_public'], true))) {
19:             throw new \LogicException('Uploaded media must be stored on R2.');
20:         }
21:         $media->conversions_disk = $media->conversions_disk ?: $media->disk;
22:         if (in_array('r2_public', [$media->disk, $media->conversions_disk], true)
23:             && config('filesystems.disks.r2_public.bucket')
24:             && config('filesystems.disks.r2_public.bucket') === config('filesystems.disks.r2.bucket')) {
25:             throw new \LogicException('Catalog media requires a separate public R2 bucket.');
26:         }
27:         parent::creating($media);
28:         $media->setCustomProperty('path_layout', 'uuid');
29:     }
30: 
31:     public function created(Media $media): void
32:     {
33:         if ($media->getConnection()->transactionLevel() > 0) {
34:             $media->getConnection()->afterRollBack(fn () => app(Filesystem::class)->removeAllFiles($media));
35:         }
36:     }
37: 
38:     public function deleted(Media $media): void
39:     {
40:         // Resolve legacy paths while the original file still exists.
41:         $copy = clone $media;
42:         $path = app(UuidPathGenerator::class)->getPath($copy);
43:         $copy->setCustomProperty('path_layout', $path === $copy->id.'/' ? 'id' : 'uuid');
44:         $media->getConnection()->afterCommit(fn () => parent::deleted($copy));
45:     }
46: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\PriceListType;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\PriceList;
 10: use App\Models\PriceListItem;
 11: use App\Models\ProductVariant;
 12: use App\Models\User;
 13: use Carbon\Carbon;
 14: use DateTimeInterface;
 15: use Illuminate\Auth\Access\AuthorizationException;
 16: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 17: use Illuminate\Database\Eloquent\ModelNotFoundException;
 18: use Illuminate\Http\UploadedFile;
 19: use Illuminate\Support\Facades\DB;
 20: use Illuminate\Support\Facades\Log;
 21: use Illuminate\Support\Facades\Validator;
 22: use Symfony\Component\HttpFoundation\StreamedResponse;
 23: 
 24: /**
 25:  * إدارة قوائم الأسعار وعناصرها واستيراد/تصدير CSV.
 26:  * منطق حساب السعر نفسه في PricingService.
 27:  */
 28: class PriceListService
 29: {
 30:     public function paginate(array $filters, ?User $user = null): LengthAwarePaginator
 31:     {
 32:         return PriceList::query()
 33:             ->with(['customer', 'customerGroup', 'branch'])
 34:             ->withCount('items')
 35:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 36:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 37:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
 38:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 39:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 40:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
 41:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('name', SearchTerm::pattern($v), caseSensitive: false))
 42:             ->orderByDesc('priority')
 43:             ->orderByDesc('id')
 44:             ->paginate($filters['per_page'] ?? 15);
 45:     }
 46: 
 47:     public function find(int $id, ?User $user = null): PriceList
 48:     {
 49:         return PriceList::query()
 50:             ->with(['customer', 'customerGroup', 'branch'])
 51:             ->withCount('items')
 52:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 53:             ->findOrFail($id);
 54:     }
 55: 
 56:     public function create(array $data, ?User $user = null): PriceList
 57:     {
 58:         $restricted = $this->restrictedBranch($user);
 59:         if ($restricted !== null) {
 60:             if (isset($data['branch_id']) && (int) $data['branch_id'] !== $restricted) {
 61:                 throw new AuthorizationException('لا تملك صلاحية إنشاء قوائم أسعار لفرع آخر.');
 62:             }
 63:             $data['branch_id'] = $restricted;
 64:         }
 65:         $data = $this->normalizeDates($data);
 66:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['currency', 'priority', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
 67:         $this->validateDates($data);
 68:         $data = $this->withValidOwner($data);
 69: 
 70:         return PriceList::query()->create($data)->load(['customer', 'customerGroup', 'branch']);
 71:     }
 72: 
 73:     public function update(PriceList $priceList, array $data, ?User $user = null): PriceList
 74:     {
 75:         $this->assertListAccess($user, $priceList);
 76:         $restricted = $this->restrictedBranch($user);
 77:         // array_key_exists لا isset: إرسال branch_id = null كان يتخطى الفحص كله
 78:         // ويحوّل قائمة الفرع إلى قائمة عامة لكل الفروع (C-1).
 79:         if ($restricted !== null && array_key_exists('branch_id', $data)
 80:             && ($data['branch_id'] === null || (int) $data['branch_id'] !== $restricted)) {
 81:             throw new AuthorizationException('لا تملك صلاحية نقل قائمة أسعار إلى فرع آخر.');
 82:         }
 83:         $data = $this->normalizeDates($data);
 84: 
 85:         return DB::transaction(function () use ($priceList, $data, $user): PriceList {
 86:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
 87:             // إعادة الفحص على الصف المقفول: القائمة قد تكون انتقلت لفرع آخر بين
 88:             // فحص الـ route binding والقفل (L-1).
 89:             $this->assertListAccess($user, $priceList);
 90:             $this->validateDates($data, $priceList);
 91:             $data = $this->withValidOwner($data, $priceList);
 92:             $priceList->update($data);
 93: 
 94:             return $priceList->load(['customer', 'customerGroup', 'branch']);
 95:         });
 96:     }
 97: 
 98:     private function withValidOwner(array $data, ?PriceList $priceList = null): array
 99:     {
100:         // فرض ربط النوع بالمالك على الحالة النهائية: النوع الخاص بعميل لازم له عميل،
101:         // والخاص بمجموعة لازم له مجموعة، وأي نوع تاني بيصفّي الحقلين تلقائيًا
102:         $type = $data['type'] ?? $priceList?->type;
103:         $typeValue = $type instanceof PriceListType ? $type->value : $type;
104: 
105:         if ($typeValue === PriceListType::CustomerSpecific->value) {
106:             $customerId = array_key_exists('customer_id', $data) ? $data['customer_id'] : $priceList?->customer_id;
107:             if ($customerId === null) {
108:                 throw new BusinessException('قائمة الأسعار الخاصة بعميل تتطلب تحديد العميل.');
109:             }
110:             $data['customer_id'] = $customerId;
111:             $data['customer_group_id'] = null;
112:         } elseif ($typeValue === PriceListType::CustomerGroup->value) {
113:             $groupId = array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $priceList?->customer_group_id;
114:             if ($groupId === null) {
115:                 throw new BusinessException('قائمة أسعار المجموعة تتطلب تحديد مجموعة العملاء.');
116:             }
117:             $data['customer_group_id'] = $groupId;
118:             $data['customer_id'] = null;
119:         } else {
120:             $data['customer_id'] = null;
121:             $data['customer_group_id'] = null;
122:         }
123: 
124:         return $data;
125:     }
126: 
127:     public function delete(PriceList $priceList, ?User $user = null): void
128:     {
129:         $this->assertListAccess($user, $priceList);
130: 
131:         DB::transaction(function () use ($priceList, $user): void {
132:             $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
133:             $this->assertListAccess($user, $locked); // إعادة فحص بعد القفل (L-1)
134:             $locked->delete(); // العناصر بتتحذف بـ cascade في القاعدة
135:         });
136:     }
137: 
138:     // ---------- Items ----------
139: 
140:     public function paginateItems(PriceList $priceList, array $filters, ?User $user = null): LengthAwarePaginator
141:     {
142:         $this->assertListAccess($user, $priceList);
143: 
144:         return $priceList->items()
145:             ->with(['variant.product'])
146:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
147:             ->orderBy('product_variant_id')
148:             ->orderBy('min_qty')
149:             ->orderBy('id')
150:             ->paginate($filters['per_page'] ?? 15);
151:     }
152: 
153:     public function createItem(PriceList $priceList, array $data, ?User $user = null): PriceListItem
154:     {
155:         $this->assertListAccess($user, $priceList);
156:         $data = $this->normalizeDates($data);
157: 
158:         return DB::transaction(function () use ($priceList, $data, $user): PriceListItem {
159:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
160:             $this->assertListAccess($user, $priceList); // إعادة فحص بعد القفل (L-1)
161:             $data['min_qty'] = $data['min_qty'] ?? 1;
162:             $this->validateDates($data);
163:             $this->assertNoDuplicateTier($priceList, (int) $data['product_variant_id'], (float) $data['min_qty']);
164: 
165:             return $priceList->items()->create($data)->load('variant.product');
166:         });
167:     }
168: 
169:     public function updateItem(PriceListItem $item, array $data, ?User $user = null): PriceListItem
170:     {
171:         $this->assertListAccess($user, $item->priceList);
172:         $data = $this->normalizeDates($data);
173: 
174:         return DB::transaction(function () use ($item, $data, $user): PriceListItem {
175:             $lockedList = PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
176:             $this->assertListAccess($user, $lockedList); // إعادة فحص بعد القفل (L-1)
177:             $item = PriceListItem::query()->lockForUpdate()->findOrFail($item->id);
178:             $this->validateDates($data, $item);
179:             if (isset($data['product_variant_id']) || isset($data['min_qty'])) {
180:                 $this->assertNoDuplicateTier(
181:                     $item->priceList,
182:                     (int) ($data['product_variant_id'] ?? $item->product_variant_id),
183:                     (float) ($data['min_qty'] ?? $item->min_qty),
184:                     $item->id,
185:                 );
186:             }
187: 
188:             $item->update($data);
189: 
190:             return $item->load('variant.product');
191:         });
192:     }
193: 
194:     public function deleteItem(PriceListItem $item, ?User $user = null): void
195:     {
196:         $this->assertListAccess($user, $item->priceList);
197: 
198:         DB::transaction(function () use ($item, $user): void {
199:             $lockedList = PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
200:             $this->assertListAccess($user, $lockedList); // إعادة فحص بعد القفل (L-1)
201:             PriceListItem::query()->lockForUpdate()->findOrFail($item->id)->delete();
202:         });
203:     }
204: 
205:     private function assertNoDuplicateTier(PriceList $priceList, int $variantId, float $minQty, ?int $ignoreItemId = null): void
206:     {
207:         $exists = $priceList->items()
208:             ->where('product_variant_id', $variantId)
209:             ->where('min_qty', $minQty)
210:             ->when($ignoreItemId !== null, fn ($q) => $q->whereKeyNot($ignoreItemId))
211:             ->exists();
212: 
213:         if ($exists) {
214:             throw new BusinessException('توجد شريحة بنفس المتغير وحد الكمية داخل هذه القائمة بالفعل.');
215:         }
216:     }
217: 
218:     // ---------- CSV ----------
219: 
220:     /** تصدير عناصر القائمة كـ CSV بنفس أعمدة الاستيراد عشان إعادة الاستيراد تشتغل. */
221:     public function exportCsv(PriceList $priceList, ?User $user = null): StreamedResponse
222:     {
223:         $this->assertListAccess($user, $priceList);
224: 
225:         return response()->streamDownload(function () use ($priceList): void {
226:             $handle = fopen('php://output', 'w');
227:             try {
228:                 // escape: '' — آلية الهروب الخاصة بـ PHP تكسر الحقول المنتهية بشرطة
229:                 // مائلة ومُهملة في PHP 8.4 (L-5).
230:                 fputcsv($handle, ['sku', 'variant_id', 'product_name', 'min_qty', 'price', 'starts_at', 'ends_at'], escape: '');
231: 
232:                 $priceList->items()
233:                     ->with(['variant.product' => fn ($query) => $query->withTrashed()])
234:                     ->chunkById(500, function ($items) use ($handle): void {
235:                         foreach ($items as $item) {
236:                             fputcsv($handle, [
237:                                 $this->csvText($item->variant?->sku ?? ''),
238:                                 $item->product_variant_id,
239:                                 $this->csvText($item->variant?->product?->name_ar ?? ''),
240:                                 $item->min_qty,
241:                                 $item->price,
242:                                 $item->starts_at?->toIso8601String(),
243:                                 $item->ends_at?->toIso8601String(),
244:                             ], escape: '');
245:                         }
246:                     });
247: 
248:             } catch (\Throwable $e) {
249:                 // فشل في منتصف البث يترك ملفًا مبتورًا عند العميل بحالة 200؛
250:                 // لا يمكن التراجع، لكن الفشل لازم يتسجل (L-5).
251:                 Log::error('فشل تصدير قائمة أسعار أثناء البث', [
252:                     'price_list_id' => $priceList->id,
253:                     'exception' => $e->getMessage(),
254:                 ]);
255: 
256:                 throw $e;
257:             } finally {
258:                 fclose($handle);
259:             }
260:         }, 'price-list-'.$priceList->id.'.csv', [
261:             'Content-Type' => 'text/csv; charset=UTF-8',
262:             'X-Row-Count' => (string) $priceList->items()->count(),
263:         ]);
264:     }
265: 
266:     private function csvText(string $value): string
267:     {
268:         return preg_match('/^[\s]*[=+@\-\t\r\n]/u', $value) ? "'".$value : $value;
269:     }
270: 
271:     /**
272:      * استيراد CSV: كل صف بيحدّث أو ينشئ عنصرًا بمفتاح (القائمة، المتغير، min_qty)
273:      * داخل transaction واحدة. أخطاء الصفوف الفردية بتتجمع في التقرير من غير ما توقف الكل.
274:      *
275:      * @return array{created: int, updated: int, skipped: int, errors: list<array{line: int, message: string}>}
276:      */
277:     public function importCsv(PriceList $priceList, UploadedFile $file, ?User $user = null): array
278:     {
279:         $this->assertListAccess($user, $priceList);
280:         $handle = fopen($file->getRealPath(), 'r');
281:         if ($handle === false) {
282:             throw new BusinessException('تعذرت قراءة ملف الاستيراد.');
283:         }
284:         try {
285:             $header = fgetcsv($handle, escape: '');
286:             if ($header === false) {
287:                 throw new BusinessException('ملف الاستيراد فارغ.');
288:             }
289:             $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string) $header[0]);
290:             $columns = array_map(fn ($h) => strtolower(trim((string) $h)), $header);
291:             $index = array_flip($columns);
292:             if (count($index) !== count($columns) || ! isset($index['price']) || (! isset($index['variant_id']) && ! isset($index['sku']))) {
293:                 throw new BusinessException('يجب أن يحتوي الملف على price وsku أو variant_id، دون أعمدة مكررة.');
294:             }
295:             $rows = [];
296:             $line = 1;
297:             while (($row = fgetcsv($handle, escape: '')) !== false) {
298:                 $line++;
299:                 if ($line > 10000) {
300:                     throw new BusinessException('عدد أسطر الملف يتجاوز الحد المسموح.');
301:                 }
302:                 if ($row === [null] || trim(implode('', array_map('strval', $row))) === '') {
303:                     continue;
304:                 }
305:                 if (count($rows) >= 2000) {
306:                     throw new BusinessException('الحد الأقصى للاستيراد المتزامن 2000 صف؛ قسّم الملف إلى أجزاء أصغر.');
307:                 }
308:                 $get = fn (string $key) => isset($index[$key]) ? trim((string) ($row[$index[$key]] ?? '')) : '';
309:                 $rows[] = ['line' => $line, 'variant_id' => $get('variant_id'), 'sku' => $get('sku'),
310:                     'price' => $get('price'), 'min_qty' => $get('min_qty') === '' ? '1' : $get('min_qty'),
311:                     'starts_at' => $get('starts_at') === '' ? null : $get('starts_at'),
312:                     'ends_at' => $get('ends_at') === '' ? null : $get('ends_at')];
313:             }
314:         } finally {
315:             fclose($handle);
316:         }
317: 
318:         $ids = array_values(array_filter(array_map(fn ($row) => filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]), $rows)));
319:         $skus = [];
320:         foreach ($rows as $row) {
321:             // الكتالوج يخزن SKU بأحرف كبيرة؛ مطابقة الاستيراد لا يجب أن تفشل على
322:             // اختلاف الحالة (L-5)، فنجمع كل الصور المحتملة للبحث.
323:             $skus[] = $row['sku'];
324:             $skus[] = $this->unescapeCsvText($row['sku']);
325:             $skus[] = strtoupper($row['sku']);
326:             $skus[] = strtoupper($this->unescapeCsvText($row['sku']));
327:         }
328:         $variants = ProductVariant::query()->where('is_active', true)
329:             ->where(fn ($q) => $q->whereIn('id', $ids)->orWhereIn('sku', array_unique($skus)))->get();
330:         $byId = $variants->keyBy('id');
331:         $bySku = $variants->keyBy('sku');
332:         $report = ['created' => 0, 'updated' => 0, 'skipped' => 0, 'errors' => []];
333:         $valid = [];
334:         foreach ($rows as $row) {
335:             try {
336:                 $variant = $row['variant_id'] !== ''
337:                     ? $byId->get(filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0)
338:                     : ($bySku->get($row['sku']) ?? $bySku->get($this->unescapeCsvText($row['sku']))
339:                         ?? $bySku->get(strtoupper($row['sku'])) ?? $bySku->get(strtoupper($this->unescapeCsvText($row['sku']))));
340:                 if ($variant === null || ($row['sku'] !== '' && $row['sku'] !== $variant->sku && strtoupper($row['sku']) !== $variant->sku && $row['sku'] !== $this->csvText($variant->sku) && strtoupper($row['sku']) !== $this->csvText($variant->sku))) {
341:                     throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
342:                 }
343:                 $validator = Validator::make($row, [
344:                     'price' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
345:                     'min_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
346:                     'starts_at' => ['nullable', 'date'], 'ends_at' => ['nullable', 'date'],
347:                 ]);
348:                 if ($validator->fails()) {
349:                     throw new BusinessException($validator->errors()->first());
350:                 }
351:                 $row['starts_at'] = $this->parseDate($row['starts_at'] ?? '');
352:                 $row['ends_at'] = $this->parseDate($row['ends_at'] ?? '');
353:                 $this->validateDates($row);
354:                 $valid[] = [...$row, 'product_variant_id' => $variant->id];
355:             } catch (BusinessException $exception) {
356:                 $report['skipped']++;
357:                 $report['errors'][] = ['line' => $row['line'], 'message' => $exception->getMessage()];
358:             }
359:         }
360:         // تكرار نفس (متغير، min_qty) داخل الملف: الصف الأخير يكسب، والعدّ مرة واحدة
361:         $deduped = [];
362:         foreach ($valid as $row) {
363:             $deduped[$row['product_variant_id'].':'.number_format((float) $row['min_qty'], 4, '.', '')] = $row;
364:         }
365:         $valid = array_values($deduped);
366: 
367:         DB::transaction(function () use ($valid, $priceList, $user, &$report): void {
368:             $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
369:             $this->assertListAccess($user, $locked); // إعادة فحص بعد القفل (L-1)
370: 
371:             // كتابة مجمّعة بدل updateOrCreate لكل صف: استعلام وجود واحد + upsert
372:             // على دفعات، بدل آلاف الاستعلامات والقائمة مقفولة (M-6).
373:             $existing = PriceListItem::query()
374:                 ->where('price_list_id', $priceList->id)
375:                 ->whereIn('product_variant_id', array_column($valid, 'product_variant_id'))
376:                 ->get(['product_variant_id', 'min_qty'])
377:                 ->map(fn ($item) => $item->product_variant_id.':'.number_format((float) $item->min_qty, 4, '.', ''))
378:                 ->flip();
379: 
380:             $rows = [];
381:             $now = now();
382:             foreach ($valid as $row) {
383:                 $key = $row['product_variant_id'].':'.number_format((float) $row['min_qty'], 4, '.', '');
384:                 $existing->has($key) ? $report['updated']++ : $report['created']++;
385:                 $rows[] = [
386:                     'price_list_id' => $priceList->id,
387:                     'product_variant_id' => $row['product_variant_id'],
388:                     'min_qty' => $row['min_qty'],
389:                     'price' => $row['price'],
390:                     'starts_at' => $row['starts_at'],
391:                     'ends_at' => $row['ends_at'],
392:                     'created_at' => $now,
393:                     'updated_at' => $now,
394:                 ];
395:             }
396: 
397:             foreach (array_chunk($rows, 500) as $chunk) {
398:                 PriceListItem::query()->upsert($chunk, ['price_list_id', 'product_variant_id', 'min_qty'], ['price', 'starts_at', 'ends_at', 'updated_at']);
399:             }
400:         });
401: 
402:         return $report;
403:     }
404: 
405:     private function unescapeCsvText(string $value): string
406:     {
407:         return str_starts_with($value, "'") && $this->csvText(substr($value, 1)) === $value ? substr($value, 1) : $value;
408:     }
409: 
410:     /**
411:      * تحليل صارم للتواريخ: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة فقط.
412:      * القيم بلا إزاحة تُفسَّر بمنطقة عمل (business_timezone) وتُخزَّن UTC —
413:      * لا strtotime: لا "next monday" ولا خلط بين التنسيقين الأمريكي والأوروبي.
414:      */
415:     private function parseDate(string $value): ?string
416:     {
417:         $value = trim($value);
418:         if ($value === '') {
419:             return null;
420:         }
421: 
422:         $businessTz = (string) config('app.business_timezone', 'Africa/Cairo');
423:         $value = preg_replace('/Z$/', '+00:00', $value);
424:         $value = preg_replace_callback('/\.(\d{1,6})([+-]\d{2}:\d{2})$/', fn ($matches) => '.'.str_pad($matches[1], 6, '0').$matches[2], $value);
425:         foreach (['Y-m-d\TH:i:s.uP', 'Y-m-d\TH:i:sP', 'Y-m-d H:i:s', 'Y-m-d'] as $format) {
426:             try {
427:                 $parsed = Carbon::rawCreateFromFormat('!'.$format, $value, $businessTz);
428:             } catch (\Throwable) {
429:                 $parsed = null;
430:             }
431:             if ($parsed !== null && $parsed->format($format) === $value) {
432:                 return $parsed->utc()->format('Y-m-d H:i:s');
433:             }
434:         }
435: 
436:         throw new BusinessException("تاريخ غير صالح: {$value} — الصيغ المقبولة: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة.");
437:     }
438: 
439:     /** تطبيع starts_at/ends_at القادمة من الـ API لنفس قواعد parseDate قبل الحفظ. */
440:     private function normalizeDates(array $data): array
441:     {
442:         foreach (['starts_at', 'ends_at'] as $field) {
443:             if (! array_key_exists($field, $data) || $data[$field] === null) {
444:                 continue;
445:             }
446:             $data[$field] = $data[$field] instanceof DateTimeInterface
447:                 ? Carbon::instance($data[$field])->utc()->format('Y-m-d H:i:s')
448:                 : $this->parseDate((string) $data[$field]);
449:         }
450: 
451:         return $data;
452:     }
453: 
454:     // ----- نطاق الفرع (M4): الموظف المقيد لا يرى/يعدّل إلا قوائم فرعه -----
455:     // مجموعات العملاء كيان مركزي بلا فرع بالتصميم، فلا ينطبق عليها هذا التقييد.
456: 
457:     private function restrictedBranch(?User $user): ?int
458:     {
459:         return $user === null ? null : app(BranchAccess::class)->restrictedBranch($user);
460:     }
461: 
462:     public function assertListAccess(?User $user, PriceList $priceList): void
463:     {
464:         $restricted = $this->restrictedBranch($user);
465:         if ($restricted !== null && $priceList->branch_id !== $restricted) {
466:             // 404 لا 403: كشف الوجود غير متسق مع find() الذي يرجع 404 أصلًا،
467:             // وإخفاء الوجود هو السلوك الموحد لقوائم خارج النطاق (L-6).
468:             throw new ModelNotFoundException('قائمة الأسعار غير موجودة.');
469:         }
470:     }
471: 
472:     private function validateDates(array $data, PriceList|PriceListItem|null $model = null): void
473:     {
474:         $start = array_key_exists('starts_at', $data) ? $data['starts_at'] : $model?->starts_at;
475:         $end = array_key_exists('ends_at', $data) ? $data['ends_at'] : $model?->ends_at;
476:         if ($start !== null && $end !== null && Carbon::parse($end)->lt(Carbon::parse($start))) {
477:             throw new BusinessException('نهاية صلاحية السعر يجب ألا تسبق بدايتها.');
478:         }
479:     }
480: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\TreasuryTransactionType;
  9: use App\Enums\TreasuryType;
 10: use App\Enums\WholesalePaymentNoticeStatus;
 11: use App\Exceptions\BusinessException;
 12: use App\Models\Customer;
 13: use App\Models\Order;
 14: use App\Models\ReturnRequest;
 15: use App\Models\Treasury;
 16: use App\Models\WholesalePaymentNotice;
 17: use Carbon\Carbon;
 18: use Illuminate\Http\UploadedFile;
 19: use Illuminate\Support\Facades\DB;
 20: 
 21: /**
 22:  * إشعارات سداد الجملة (المرحلة 12.1): يرفع التاجر إشعار تحويل/شيك/إيداع،
 23:  * وعند اعتماد الإدارة يُخصم المبلغ من مديونيته الآجلة وتُسجَّل حركة قبض
 24:  * في الخزينة عبر TreasuryService.
 25:  *
 26:  * المديونية الآجلة معرّفة حسابيًا بلا عمود رصيد منفصل:
 27:  *   مجموع طلبات الآجل (credit) غير المسددة وغير الملغاة
 28:  *   − مجموع الإشعارات المعتمدة (الحرّة، أو المرتبطة بطلب ما زال غير مسدد).
 29:  * فإذا غطّت الإشعارات المعتمدة طلبًا مرتبطًا بالكامل تحوّل إلى «paid»
 30:  * وخرج هو وإشعاراته من المعادلة معًا حتى لا تُخصم مرتين.
 31:  */
 32: class WholesalePaymentNoticeService
 33: {
 34:     public function __construct(
 35:         private readonly SettingService $settings,
 36:         private readonly TreasuryService $treasury,
 37:     ) {}
 38: 
 39:     public function create(Customer $customer, array $data, UploadedFile $receipt): WholesalePaymentNotice
 40:     {
 41:         return PrivateAttachments::transaction(function (PrivateAttachments $files) use ($customer, $data, $receipt): WholesalePaymentNotice {
 42:             $order = null;
 43: 
 44:             if (! empty($data['order_id'])) {
 45:                 $order = $this->assertCreditableOrder($customer, (int) $data['order_id']);
 46:                 $this->assertOrderCapacity($order, (float) $data['amount']);
 47:             }
 48: 
 49:             $path = $files->store($receipt, "wholesale_payment_notices/{$customer->id}");
 50: 
 51:             return WholesalePaymentNotice::create([
 52:                 'notice_number' => $this->settings->generateNextNumber('payment_notice'),
 53:                 'customer_id' => $customer->id,
 54:                 'order_id' => $order?->id,
 55:                 'amount' => $data['amount'],
 56:                 'payment_method' => $data['payment_method'],
 57:                 'bank_name' => $data['bank_name'],
 58:                 'reference_number' => $data['reference_number'],
 59:                 'transfer_date' => $data['transfer_date'],
 60:                 'receipt_file_path' => $path,
 61:                 'status' => WholesalePaymentNoticeStatus::PendingReview,
 62:             ]);
 63:         });
 64:     }
 65: 
 66:     /** المديونية الآجلة الحالية للتاجر (انظر تعريف المعادلة في رأس الكلاس). */
 67:     public function outstandingBalance(Customer $customer): float
 68:     {
 69:         $openOrders = Order::query()
 70:             ->where('customer_id', $customer->id)
 71:             ->where('payment_method', 'credit')
 72:             ->where('payment_status', 'unpaid')
 73:             ->where('status', '!=', OrderStatus::Cancelled->value);
 74: 
 75:         $debt = (float) (clone $openOrders)->sum('grand_total');
 76:         $openOrderIds = (clone $openOrders)->pluck('id');
 77: 
 78:         $credits = (float) WholesalePaymentNotice::query()
 79:             ->where('customer_id', $customer->id)
 80:             ->where('status', WholesalePaymentNoticeStatus::Approved->value)
 81:             ->where(function ($query) use ($openOrderIds): void {
 82:                 $query->whereNull('order_id')->orWhereIn('order_id', $openOrderIds);
 83:             })
 84:             ->sum('amount');
 85: 
 86:         return round(max(0.0, $debt - $credits), 2);
 87:     }
 88: 
 89:     /**
 90:      * كشف حساب التاجر (المرحلة 12.2): المشتريات الآجلة مدينة (Debit)،
 91:      * والسدادات المعتمدة ومرتجعاته المستردة دائنة (Credit)، برصيد تراكمي
 92:      * يبدأ من رصيد افتتاحي محسوب من كل ما قبل الفترة المطلوبة.
 93:      *
 94:      * @return array{opening_balance: float, closing_balance: float, entries: list<array<string, mixed>>}
 95:      */
 96:     public function statement(Customer $customer, ?string $from = null, ?string $to = null): array
 97:     {
 98:         $entries = collect();
 99: 
100:         Order::query()
101:             ->where('customer_id', $customer->id)
102:             ->where('payment_method', 'credit')
103:             ->where('status', '!=', OrderStatus::Cancelled->value)
104:             ->get(['id', 'order_number', 'grand_total', 'created_at'])
105:             ->each(fn (Order $order) => $entries->push([
106:                 'date' => $order->created_at->copy(),
107:                 'type' => 'debit',
108:                 'description' => "طلب آجل {$order->order_number}",
109:                 'reference' => $order->order_number,
110:                 'amount' => (float) $order->grand_total,
111:             ]));
112: 
113:         WholesalePaymentNotice::query()
114:             ->where('customer_id', $customer->id)
115:             ->where('status', WholesalePaymentNoticeStatus::Approved->value)
116:             ->get(['id', 'notice_number', 'payment_method', 'amount', 'updated_at'])
117:             ->each(fn (WholesalePaymentNotice $notice) => $entries->push([
118:                 'date' => $notice->updated_at->copy(),
119:                 'type' => 'credit',
120:                 'description' => "سداد {$notice->notice_number} ({$notice->payment_method->value})",
121:                 'reference' => $notice->notice_number,
122:                 'amount' => (float) $notice->amount,
123:             ]));
124: 
125:         ReturnRequest::query()
126:             ->where('customer_id', $customer->id)
127:             ->where('status', 'refunded')
128:             ->whereNotNull('refunded_at')
129:             ->get(['id', 'return_number', 'total_refund_amount', 'refunded_at'])
130:             ->each(fn (ReturnRequest $return) => $entries->push([
131:                 'date' => $return->refunded_at->copy(),
132:                 'type' => 'credit',
133:                 'description' => "مرتجع مسترد {$return->return_number}",
134:                 'reference' => $return->return_number,
135:                 'amount' => (float) $return->total_refund_amount,
136:             ]));
137: 
138:         // المدين قبل الدائن في اليوم نفسه (اصطلاح كشف حساب المورد)
139:         $sorted = $entries->sortBy([
140:             fn (array $a, array $b): int => $a['date']->startOfDay() <=> $b['date']->startOfDay(),
141:             fn (array $a, array $b): int => ($a['type'] === 'debit' ? 0 : 1) <=> ($b['type'] === 'debit' ? 0 : 1),
142:         ])->values();
143: 
144:         $fromDate = $from !== null ? Carbon::parse($from)->startOfDay() : null;
145:         $toDate = $to !== null ? Carbon::parse($to)->endOfDay() : null;
146: 
147:         $opening = 0.0;
148:         $running = 0.0;
149:         $result = [];
150:         foreach ($sorted as $entry) {
151:             $delta = $entry['type'] === 'debit' ? $entry['amount'] : -$entry['amount'];
152: 
153:             if ($fromDate !== null && $entry['date']->lt($fromDate)) {
154:                 $opening += $delta;
155:                 $running = $opening;
156: 
157:                 continue;
158:             }
159:             if ($toDate !== null && $entry['date']->gt($toDate)) {
160:                 continue;
161:             }
162: 
163:             $running += $delta;
164:             $result[] = [
165:                 'date' => $entry['date']->toDateString(),
166:                 'type' => $entry['type'],
167:                 'description' => $entry['description'],
168:                 'reference' => $entry['reference'],
169:                 'amount' => number_format($entry['amount'], 2, '.', ''),
170:                 'running_balance' => number_format($running, 2, '.', ''),
171:             ];
172:         }
173: 
174:         return [
175:             'opening_balance' => round($opening, 2),
176:             'closing_balance' => round($running, 2),
177:             'entries' => $result,
178:         ];
179:     }
180: 
181:     public function approve(WholesalePaymentNotice $notice, int $adminId, ?int $treasuryId = null, ?string $adminNotes = null): WholesalePaymentNotice
182:     {
183:         return DB::transaction(function () use ($notice, $adminId, $treasuryId, $adminNotes): WholesalePaymentNotice {
184:             $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
185:             $customer = Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);
186: 
187:             if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
188:                 throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
189:             }
190: 
191:             if ((float) $notice->amount > $this->outstandingBalance($customer)) {
192:                 throw new BusinessException('مبلغ الإشعار أكبر من المديونية الآجلة الحالية للتاجر.');
193:             }
194: 
195:             $treasury = $this->resolveTreasury($treasuryId);
196: 
197:             $transaction = $this->treasury->record([
198:                 'treasury_id' => $treasury->id,
199:                 'type' => TreasuryTransactionType::CustomerReceipt,
200:                 'amount' => (float) $notice->amount,
201:                 'reference_type' => 'wholesale_payment_notice',
202:                 'reference_id' => $notice->id,
203:                 'created_by' => $adminId,
204:                 'notes' => "اعتماد إشعار سداد جملة {$notice->notice_number}",
205:             ]);
206: 
207:             $notice->update([
208:                 'status' => WholesalePaymentNoticeStatus::Approved,
209:                 'reviewed_by' => $adminId,
210:                 'admin_notes' => $adminNotes ?? $notice->admin_notes,
211:                 'treasury_id' => $treasury->id,
212:                 'treasury_transaction_id' => $transaction->id,
213:             ]);
214: 
215:             if ($notice->order_id !== null) {
216:                 $this->settleOrderIfCovered((int) $notice->order_id);
217:             }
218: 
219:             return $notice->load(['customer', 'order', 'treasury', 'treasuryTransaction']);
220:         });
221:     }
222: 
223:     public function reject(WholesalePaymentNotice $notice, int $adminId, ?string $adminNotes = null): WholesalePaymentNotice
224:     {
225:         return DB::transaction(function () use ($notice, $adminId, $adminNotes): WholesalePaymentNotice {
226:             $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
227: 
228:             if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
229:                 throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
230:             }
231: 
232:             $notice->update([
233:                 'status' => WholesalePaymentNoticeStatus::Rejected,
234:                 'reviewed_by' => $adminId,
235:                 'admin_notes' => $adminNotes ?? $notice->admin_notes,
236:             ]);
237: 
238:             return $notice->load(['customer', 'order']);
239:         });
240:     }
241: 
242:     private function assertCreditableOrder(Customer $customer, int $orderId): Order
243:     {
244:         $order = Order::query()->where('customer_id', $customer->id)->find($orderId);
245: 
246:         if ($order === null) {
247:             throw new BusinessException('الطلب المرتبط غير موجود أو لا يخص هذا التاجر.', [], 404);
248:         }
249: 
250:         if ($order->payment_method !== 'credit' || $order->payment_status !== 'unpaid'
251:             || $order->status === OrderStatus::Cancelled) {
252:             throw new BusinessException('الطلب المرتبط ليس طلب آجل غير مسدد.');
253:         }
254: 
255:         return $order;
256:     }
257: 
258:     /** مجموع المعتمد + قيد المراجعة على الطلب نفسه لا يتجاوز إجماليه. */
259:     private function assertOrderCapacity(Order $order, float $newAmount): void
260:     {
261:         $committed = (float) WholesalePaymentNotice::query()
262:             ->where('order_id', $order->id)
263:             ->whereIn('status', [
264:                 WholesalePaymentNoticeStatus::PendingReview->value,
265:                 WholesalePaymentNoticeStatus::Approved->value,
266:             ])
267:             ->sum('amount');
268: 
269:         if ($committed + $newAmount > (float) $order->grand_total) {
270:             throw new BusinessException('مبلغ الإشعار يتجاوز المتبقي غير المسدد من هذا الطلب.');
271:         }
272:     }
273: 
274:     private function settleOrderIfCovered(int $orderId): void
275:     {
276:         $order = Order::query()->lockForUpdate()->find($orderId);
277: 
278:         if ($order === null || $order->payment_status !== 'unpaid') {
279:             return;
280:         }
281: 
282:         $approved = (float) WholesalePaymentNotice::query()
283:             ->where('order_id', $order->id)
284:             ->where('status', WholesalePaymentNoticeStatus::Approved->value)
285:             ->sum('amount');
286: 
287:         if ($approved >= (float) $order->grand_total) {
288:             $order->update(['payment_status' => 'paid']);
289:         }
290:     }
291: 
292:     private function resolveTreasury(?int $treasuryId): Treasury
293:     {
294:         if ($treasuryId !== null) {
295:             return Treasury::query()->findOrFail($treasuryId);
296:         }
297: 
298:         $treasury = Treasury::query()->where('is_active', true)
299:             ->where('type', TreasuryType::BankAccount->value)
300:             ->orderBy('id')
301:             ->first()
302:             ?? Treasury::query()->where('is_active', true)
303:                 ->where('type', TreasuryType::MainSafe->value)
304:                 ->orderBy('id')
305:                 ->first();
306: 
307:         if ($treasury === null) {
308:             throw new BusinessException('لا توجد خزينة بنكية أو رئيسية نشطة لتسجيل القبض.');
309:         }
310: 
311:         return $treasury;
312:     }
313: }

 1: // توحيد أخطاء axios الحقيقية — نفس منطق parseApiError اللي في الـ mock بس على response فعلي.
 2: export interface ApiError {
 3:   status: number;                       // 0 = مشكلة شبكة
 4:   message: string;
 5:   fields: Record<string, string[]>;     // كل المفاتيح ما عدا 'status'
 6:   summary: string[];                    // errors.status (أسباب رفض النشر)
 7: }
 8: 
 9: interface RawErrorBody {
10:   message?: unknown;
11:   errors?: Record<string, unknown>;
12: }
13: 
14: function toStringList(v: unknown): string[] {
15:   if (Array.isArray(v)) return v.map(x => String(x));
16:   return [String(v)];
17: }
18: 
19: // Backend error contract (verified in code, do not assume otherwise):
20: // - BusinessException (app/Exceptions/BusinessException.php) renders 422 by default
21: //   as { message, errors, code? }. Business-rule failures (insufficient stock,
22: //   disabled variant/location and stale stocktake) come back this way.
23: //   Production's missing key also returns 422 via abort(), with { message }.
24: //   `errors` doubles as the extra-data channel: the stale
25: //   stocktake rejection carries { recount_item_ids, recount_variant_ids } there.
26: // - BusinessException can explicitly override its default to 409; those errors
27: //   retain { message, errors, code? }. HandlesIdempotentCreation rejects changed
28: //   transfer/stocktake payloads with the same key using this override.
29: // - 409 means "conflict, reload then retry with a fresh read":
30: //   version conflict ('تم تعديل التحويل؛ أعد تحميله…'), lock timeout/deadlock
31: //   ('المخزون مشغول بعملية أخرى…', retry with the SAME Idempotency-Key),
32: //   delete-blocked branch/location ('لا يمكن حذف الفرع/الموقع لارتباطه…'),
33: //   unique-constraint races. The only 409 that must NOT auto-retry is
34: //   'مفتاح عدم التكرار … مستخدم (مسبقًا) مع بيانات مختلفة' — the payload changed.
35: // - 404 with { message: 'العنصر المطلوب غير موجود' } (ModelNotFound via
36: //   bootstrap/app.php). 401 is handled by the axios interceptor — screens do
37: //   nothing. Server messages are Arabic: render them verbatim, never translate
38: //   or replace with a generic string.
39: export function normalizeError(e: unknown): ApiError {
40:   const err = e as { response?: { status?: unknown; data?: unknown }; message?: unknown } | null | undefined;
41:   const status = typeof err?.response?.status === 'number' ? err.response.status : 0;
42:   const data = (err?.response?.data ?? {}) as RawErrorBody;
43:   const raw: Record<string, unknown> = data.errors && typeof data.errors === 'object' ? data.errors : {};
44: 
45:   const fields: Record<string, string[]> = {};
46:   Object.entries(raw).forEach(([k, v]) => {
47:     if (k === 'status') return;
48:     fields[k] = toStringList(v);
49:   });
50: 
51:   const summary = raw.status === undefined ? [] : toStringList(raw.status);
52:   const message = typeof data.message === 'string' && data.message !== ''
53:     ? data.message
54:     : e instanceof Error && !err?.response && !('request' in e)
55:       ? e.message
56:       : status === 0
