  4: // Save each successful identity immediately, so a retry cannot create duplicate rows/files.
  5: export async function persistProduct(state: any, original: any, canViewCost: boolean, onState: (state: any) => void, onUpload: () => void = () => {}) {
  6:   const removeIfPresent = async (operation: () => Promise<unknown>) => {
  7:     try { await operation(); } catch (e: any) { if (e?.response?.status !== 404) throw e; }
  8:   };
  9:   let next = { ...state, rows: state.rows.map((r: any) => ({ ...r })), media: { ...state.media, general: [...state.media.general], byVariant: Object.fromEntries(Object.entries(state.media.byVariant).map(([k,v]) => [k,[...(v as any[])]])) } };
