 11:   const variantRequest = async (row: any, operation: () => Promise<any>) => {
 12:     try { return await operation(); } catch (error: any) {
 13:       error.catalogRowKey = row._id;
 14:       error.catalogProductId = next.id;
 15:       throw error;
 16:     }
 17:   };
 18:   if (!next.id) {
 19:     next.createKey ??= crypto.randomUUID();
 20:     onState(next);
 21:     let created;
 22:     try {
 23:       created = await productsApi.create({ ...productToPayload(next.basic), create_key: next.createKey, variants: next.rows.map((r: any,i: number) => payload(r,i,true)) });
 24:     } catch (error: any) {
 25:       const existingId = Number(error?.response?.data?.errors?.product_id?.[0]);
 26:       if (error?.response?.status === 409 && Number.isSafeInteger(existingId) && existingId > 0) {
 27:         error.catalogProductId = existingId;
 28:         history.replaceState(null, '', '#/products/' + existingId);
 29:       }
 30:       throw error;
 31:     }
 32:     next = { ...next, id: created.id, code: created.code, status: created.status, lock_version: created.lock_version, updated_at: created.updated_at, rows: next.rows.map((r: any,i: number) => ({ ...r, serverId: created.variants?.[i]?.id, sku: created.variants?.[i]?.sku, barcode: created.variants?.[i]?.barcode, lock_version: created.variants?.[i]?.lock_version })) };
 33:     history.replaceState(null, '', '#/products/' + created.id);
