 38:     const expectedTime = next.updated_at ?? original?.updated_at;
 39:     if (expectedVersion === undefined && expectedTime) {
 40:       throw Object.assign(new Error('أعد تحميل المنتج للحصول على رقم الإصدار قبل الحفظ.'), { catalogProductId: next.id });
 41:     }
 42:     let updated;
 43:     try {
 44:       updated = await productsApi.update(next.id, { ...productToPayload(next.basic),
 45:         ...(expectedVersion !== undefined ? { expected_version: expectedVersion } : {}) });
 46:     } catch (error: any) {
 47:       if (error?.response?.status === 409) error.catalogProductId = next.id;
 48:       throw error;
 49:     }
 50:     if (updated) Object.assign(next, { lock_version: updated.lock_version, updated_at: updated.updated_at });
 51:     onState({ ...next });
 52:     const updateRow = async (row: any, changes: any) => {
 53:       const old = original.rows?.find((item: any) => item.serverId === row.serverId);
 54:       const version = row.lock_version ?? old?.lock_version;
 55:       const saved = await variantRequest(row, () => variantsApi.update(next.id, row.serverId, {
 56:         ...changes, ...(version !== undefined ? { expected_version: version } : {}),
 57:       }));
 58:       if (saved) Object.assign(row, { lock_version: saved.lock_version });
 59:       onState({ ...next });
 60:     };
 61:     const removed = (original.rows || []).filter((r: any) => r.serverId && !next.rows.some((n: any) => n.serverId === r.serverId));
 62:     const key = (r: any) => [r.color?.en,r.size,r.capacity].map(v => (v || '').trim().toLowerCase()).join('|');
 63:     const conflicting = removed.filter((r: any) => next.rows.some((n: any) => n.serverId !== r.serverId && key(n) === key(r)));
 64:     if (conflicting.length && next.status === 'published' && original.rows.filter((r: any) => r.status === 'active').length <= conflicting.filter((r: any) => r.status === 'active').length) throw new Error('انقل المنتج لمسودة أولاً قبل استبدال آخر متغير نشط.');
 65:     for (const row of conflicting) await variantRequest(row, () => removeIfPresent(() => variantsApi.remove(next.id,row.serverId)));
 66:     for (const [i,row] of next.rows.entries()) {
 67:       if (row.serverId) continue;
 68:       const saved = await variantRequest(row, () => variantsApi.create(next.id,payload(row,i,true)));
 69:       createdThisRun.add(saved.id);
 70:       Object.assign(row,{ serverId:saved.id,sku:saved.sku,barcode:saved.barcode,lock_version:saved.lock_version }); onState({ ...next });
 71:     }
 72:     for (const [i,row] of next.rows.entries()) {
 73:       if (createdThisRun.has(row.serverId)) continue;
 74:       const old = original.rows?.find((r: any) => r.serverId === row.serverId);
 75:       if (!old) { await updateRow(row,payload(row,i,false)); continue; }
 76:       const before = payload(old,original.rows.indexOf(old),false), after = payload(row,i,false);
 77:       const diff = Object.fromEntries(Object.entries(after).filter(([k,v]) => JSON.stringify(v) !== JSON.stringify((before as any)[k])));
 78:       if (Object.keys(diff).length) await updateRow(row,diff);
 79:     }
 80:     for (const row of removed.filter((r: any) => !conflicting.includes(r))) await variantRequest(row, () => removeIfPresent(() => variantsApi.remove(next.id,row.serverId)));
 81:   }
 82:   onUpload();
 83:   // Resolve color attachments against the saved variants, not a possibly stale UI row.
 84:   // The product/variant write can succeed even when the local gallery still lacks its ID.
 85:   const colorKey = (value: string | null | undefined) => (value || '').trim().toLowerCase();
 86:   const colorGroups = Object.entries(next.media.byVariant) as [string, any[]][];
 87:   const pendingColorGroups = colorGroups.filter(([, files]) => files.some(file => !file.serverId));
 88:   const savedColorIds = new Map<string, number>();
 89:   if (pendingColorGroups.length) {
 90:     const savedVariants = await variantsApi.list(next.id);
 91:     for (const row of next.rows) {
 92:       if (row.serverId) continue;
 93:       const saved = savedVariants.find((variant: any) =>
 94:         colorKey(variant.color?.name_en ?? variant.color_name_en) === colorKey(row.color?.en)
 95:         && colorKey(variant.size) === colorKey(row.size)
 96:         && colorKey(variant.capacity) === colorKey(row.capacity));
 97:       if (saved) Object.assign(row, { serverId: saved.id, sku: saved.sku, barcode: saved.barcode });
 98:     }
 99:     onState({ ...next });
100:     const byId = new Map(savedVariants.map((variant: any) => [variant.id, variant]));
101:     // Preserve display order when multiple sizes share a color.
102:     const ordered = [
103:       ...next.rows.map((row: any) => byId.get(row.serverId)).filter(Boolean),
104:       ...savedVariants,
105:     ];
106:     for (const variant of ordered as any[]) {
107:       const color = colorKey(variant.color?.name_en ?? variant.color_name_en);
108:       if (color && !savedColorIds.has(color)) savedColorIds.set(color, variant.id);
109:     }
110:     for (const [color, files] of pendingColorGroups) {
111:       if (!savedColorIds.has(colorKey(color))) {
112:         const message = `تعذّر ربط صور اللون «${color}»: لا توجد نسخة محفوظة بهذا اللون. الصور المختارة محفوظة في الصفحة؛ راجع لون النسخة في تبويب المتغيرات والأسعار.`;
113:         for (const file of files.filter(file => !file.serverId)) {
114:           file.status = 'failed'; file.message = message;
115:         }
116:         onState({ ...next });
117:         throw Object.assign(new Error(message), { catalogTab: 'media' });
118:       }
119:     }
120:   }
121:   const all = (media: any) => [...media.general,...Object.values(media.byVariant).flat(),...(media.video ? [media.video] : [])];
122:   // F10: collect deletions now but run them after uploads (see the
123:   // runPendingRemovals call below) — deleting first rejects replacing the
124:   // last image of a published product and forces an unnecessary unpublish.
125:   const pendingRemovals = (all(original.media || { general:[],byVariant:{} }) as any[]).filter((old: any) => old.serverId && !all(next.media).some((f: any) => f.serverId === old.serverId));
126:   const runPendingRemovals = async () => { for (const old of pendingRemovals) {
127:       try { await removeIfPresent(() => productMediaApi.remove(next.id,old.serverId)); }
128:       catch (e) {
129:         // Roll back only the rejected removal; retain successful uploads for retry.
130:         if (old === original.media.video) next.media.video = old;
131:         else if (original.media.general.includes(old)) next.media.general.splice(original.media.general.indexOf(old),0,old);
132:         else for (const [color,items] of Object.entries(original.media.byVariant) as [string,any[]][]) if (items.includes(old)) next.media.byVariant[color] = [...(next.media.byVariant[color] || []),old];
133:         onState({ ...next }); throw e;
134:       }
135:     } };
136:   const groups: [string,any[]][] = [['',next.media.general],...Object.entries(next.media.byVariant) as [string,any[]][]];
137:   for (const [color,files] of groups) {
138:     // Color images belong to the first saved variant of that color, by display order.
139:     const variantId = color ? savedColorIds.get(colorKey(color)) : null;
140:     const pending = files.filter(file => !file.serverId);
141:     let uploadError: unknown;
142:     const worker = async () => { while (pending.length) {
143:       const file = pending.shift();
144:       try {
145:         file.clientUploadId ??= crypto.randomUUID();
146:         file.status='uploading'; onState({ ...next });
147:         const saved = await productMediaApi.uploadImages(next.id,[file.file],variantId,pct => { file.progress=pct; onState({ ...next }); },[file.clientUploadId]);
148:         Object.assign(file,{ serverId:saved[0].id,variantId:variantId || undefined,status:'done',url:saved[0].url }); onState({ ...next });
149:       } catch(e: any) { file.status='failed'; file.message=e?.response?.data?.message || 'تعذّر رفع الملف، أعد المحاولة'; onState({ ...next }); uploadError ??= e; }
150:     } };
151:     await Promise.all([worker(),worker()]);
152:     if (uploadError) throw uploadError;
153:   }
154:   if (next.media.video && !next.media.video.serverId) {
155:     try {
156:       next.media.video.status='uploading';onState({ ...next });
157:       const saved = await productMediaApi.uploadVideo(next.id,next.media.video.file,pct => { next.media.video.progress=pct;onState({ ...next }); });
158:       Object.assign(next.media.video,{serverId:saved[0].id,status:'done',url:saved[0].url}); onState({ ...next });
159:     } catch(e: any){next.media.video.status='failed';next.media.video.message=e?.response?.data?.message || 'تعذّر رفع الفيديو';onState({ ...next });throw e;}
160:   }
161:   // F10: uploads first, deletions second, reorder last.
162:   await runPendingRemovals();
163:   if (next.media.general.length) await productMediaApi.reorder(next.id,next.media.general.map((f: any) => f.serverId));
164:   return next;
165: }

  1: @tailwind base;
  2: @tailwind components;
  3: @tailwind utilities;
  4: :host, .theme-light {
  5:   --bg-canvas: #f2eff3;
  6:   --bg-card: #ffffff;
  7:   --bg-subcard: #f5f2f6;
  8:   --bg-subcard-hover: #ebe6ed;
  9:   --seg-active-bg: #ffffff;
