 20:   --accent-light: #fde8e1;
 21:   --accent-soft: #fff9f7;
 22:   --badge-green-bg: #dcfce7;
 23:   --badge-green-text: #15803d;
 24:   --badge-red-bg: #ffe4e6;
 25:   --badge-red-text: #e11d48;
 26:   --badge-amber-bg: #fef3c7;
 27:   --badge-amber-text: #b45309;
 28:   --badge-blue-bg: #e0e7ff;
 29:   --badge-blue-text: #4338ca;
 30:   --icon-well-bg: rgba(24, 21, 28, 0.05);
 31:   --toggle-off-bg: rgba(24, 21, 28, 0.12);
 32:   --overlay: rgba(24, 21, 28, 0.32);
 33:   --shadow-pop: 0 18px 50px -12px rgba(24, 21, 28, 0.22), 0 2px 6px rgba(24,21,28,.05);
 34:   --hatched-track: repeating-linear-gradient(-60deg, rgba(24,21,28,.14) 0, rgba(24,21,28,.14) 1.5px, transparent 1.5px, transparent 5px);
 35: }
 36: :host([data-theme="dark"]), .theme-dark {
 37:   --bg-canvas: #100d13;
 38:   --bg-card: #17141a;
 39:   --bg-subcard: #1c1920;
 40:   --bg-subcard-hover: #25212a;
 41:   --seg-active-bg: #26222c;
 42:   --text-primary: #f5f3f7;
 43:   --text-secondary: #96919d;
 44:   --text-muted: #6e6975;
 45:   --border-subtle: rgba(255,255,255,.07);
 46:   --border-field: rgba(255,255,255,.10);
 47:   --divider-color: rgba(255,255,255,.06);
 48:   --pill-active-bg: #f5f3f7;
 49:   --pill-active-text: #141117;
 50:   --accent-light: rgba(230, 83, 40, 0.18);
 51:   --accent-soft: #1e1618;
 52:   --badge-green-bg: rgba(6,78,59,.45);
 53:   --badge-green-text: #34d399;
 54:   --badge-red-bg: rgba(136,19,55,.45);
 55:   --badge-red-text: #fb7185;
 56:   --badge-amber-bg: rgba(120,53,15,.45);
 57:   --badge-amber-text: #fbbf24;
 58:   --badge-blue-bg: rgba(49,46,129,.5);
 59:   --badge-blue-text: #a5b4fc;
