 64:   --hatched-track: repeating-linear-gradient(-60deg, rgba(255,255,255,.16) 0, rgba(255,255,255,.16) 1.5px, transparent 1.5px, transparent 5px);
 65: }
 66: 
 67: * { box-sizing: border-box; -webkit-font-smoothing: antialiased; }
 68: html, body { margin: 0; padding: 0; }
 69: body {
 70:   font-family: 'Plus Jakarta Sans', 'IBM Plex Sans Arabic', sans-serif;
 71:   background: var(--bg-canvas);
 72:   color: var(--text-primary);
 73: }
 74: .font-display { font-family: 'Plus Jakarta Sans', 'Readex Pro', 'IBM Plex Sans Arabic', sans-serif; }
 75: #root { min-height: 100vh; background: var(--bg-canvas); color: var(--text-primary); transition: background-color .3s; }
 76: 
 77: .v-card { background: var(--bg-card); border-radius: 22px; border: 1px solid var(--border-subtle); }
 78: .v-subcard { background: var(--bg-subcard); border-radius: 16px; }
 79: .v-pill { background: var(--bg-card); border: 1px solid var(--border-subtle); }
 80: .v-divide > * + * { border-top: 1px solid var(--divider-color); }
 81: .v-border-b { border-bottom: 1px solid var(--divider-color); }
 82: .v-border-t { border-top: 1px solid var(--divider-color); }
 83: .v-well { background: var(--icon-well-bg); color: var(--text-secondary); }
 84: .t-1 { color: var(--text-primary); } .t-2 { color: var(--text-secondary); } .t-3 { color: var(--text-muted); }
 85: .t-acc { color: var(--accent); }
 86: .bg-acc { background: var(--accent); color: #fff; }
 87: .bg-ink { background: var(--pill-active-bg); color: var(--pill-active-text); }
 88: 
 89: .v-orange { background: radial-gradient(circle at 22% 18%, #f4886b 0%, #e6542b 55%, #db4218 100%); color: #fff; }
 90: .hatched-acc { background: repeating-linear-gradient(-45deg, var(--accent) 0, var(--accent) 2.5px, var(--accent-2) 2.5px, var(--accent-2) 5px); }
 91: .hatched-track { background: var(--hatched-track); }
 92: 
 93: .b-green { background: var(--badge-green-bg); color: var(--badge-green-text); }
 94: .b-red { background: var(--badge-red-bg); color: var(--badge-red-text); }
 95: .b-amber { background: var(--badge-amber-bg); color: var(--badge-amber-text); }
 96: .b-blue { background: var(--badge-blue-bg); color: var(--badge-blue-text); }
 97: .b-gray { background: var(--icon-well-bg); color: var(--text-secondary); }
 98: .b-acc { background: var(--accent-light); color: var(--accent); }
 99: 
100: /* Fields */
101: .v-input {
102:   width: 100%; height: 42px; border-radius: 13px; padding: 0 14px;
103:   background: var(--bg-subcard); color: var(--text-primary);
104:   border: 1px solid transparent; font-size: 13.5px; outline: none;
105:   transition: border-color .15s, box-shadow .15s, background-color .15s;
106:   font-family: inherit;
107: }
108: textarea.v-input { height: auto; padding: 11px 14px; line-height: 1.6; resize: vertical; }
109: .v-input::placeholder { color: var(--text-muted); }
110: .v-input:hover { background: var(--bg-subcard-hover); }
111: .v-input:focus, .v-input.is-focus { background: var(--bg-card); border-color: var(--accent); box-shadow: 0 0 0 4px var(--accent-light); }
112: .v-input.is-error { border-color: var(--badge-red-text); background: var(--bg-card); box-shadow: 0 0 0 4px var(--badge-red-bg); }
113: .v-input:disabled, .v-input.is-disabled { opacity: .5; cursor: not-allowed; }
114: .v-input[readonly], .v-input.is-readonly { background: transparent; border: 1px dashed var(--border-field); color: var(--text-secondary); }
115: .ltr { direction: ltr; text-align: left; font-family: 'Plus Jakarta Sans', ui-monospace, sans-serif; letter-spacing: .01em; }
116: .num { font-variant-numeric: tabular-nums; }
117: 
118: /* Cell inputs (variants grid) */
119: .cell-in {
120:   width: 100%; height: 34px; border-radius: 10px; padding: 0 10px; font-size: 12.5px;
121:   background: transparent; border: 1px solid transparent; color: var(--text-primary); outline: none; font-family: inherit;
122: }
123: .cell-in:hover { background: var(--bg-subcard); }
124: .cell-in:focus { background: var(--bg-card); border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-light); }
125: .cell-in.is-error { border-color: var(--badge-red-text); background: var(--badge-red-bg); }
126: .cell-in::placeholder { color: var(--text-muted); }
127: 
128: /* Buttons */
129: .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 18px; border-radius: 999px; font-size: 13px; font-weight: 600; transition: opacity .15s, transform .1s, background-color .15s; white-space: nowrap; cursor: pointer; border: 1px solid transparent; }
130: .btn:active { transform: scale(.98); }
131: .btn:disabled { opacity: .45; cursor: not-allowed; transform: none; }
132: .btn-sm { height: 32px; padding: 0 13px; font-size: 12px; gap: 6px; }
133: .btn-lg { height: 48px; padding: 0 24px; font-size: 14px; }
134: .btn-ink { background: var(--pill-active-bg); color: var(--pill-active-text); }
135: .btn-ink:hover { opacity: .9; }
136: .btn-acc { background: var(--accent); color: #fff; box-shadow: 0 6px 16px -6px rgba(224,73,31,.55); }
137: .btn-acc:hover { opacity: .92; }
138: .btn-soft { background: var(--bg-subcard); color: var(--text-primary); }
139: .btn-soft:hover { background: var(--bg-subcard-hover); }
140: .btn-ghost { background: transparent; color: var(--text-secondary); }
141: .btn-ghost:hover { background: var(--bg-subcard); color: var(--text-primary); }
142: .btn-danger { background: var(--badge-red-bg); color: var(--badge-red-text); }
143: .btn-outline { background: var(--bg-card); border-color: var(--border-field); color: var(--text-primary); }
144: .btn-outline:hover { background: var(--bg-subcard); }
145: .icon-btn { width: 34px; height: 34px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; color: var(--text-secondary); transition: background .15s, color .15s; }
146: .icon-btn:hover { background: var(--bg-subcard); color: var(--text-primary); }
147: 
148: /* Segmented */
149: .seg { display: inline-flex; padding: 4px; border-radius: 999px; background: var(--bg-subcard); gap: 2px; }
150: .seg > button { padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 500; color: var(--text-secondary); transition: all .15s; white-space: nowrap; }
151: .seg > button.on { background: var(--seg-active-bg); color: var(--text-primary); font-weight: 600; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
152: 
153: /* Toggle */
154: .tgl { width: 42px; height: 24px; border-radius: 999px; padding: 2px; display: flex; align-items: center; background: var(--toggle-off-bg); transition: background .2s; flex-shrink: 0; }
155: .tgl > span { width: 20px; height: 20px; border-radius: 999px; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.2); transition: transform .22s cubic-bezier(.34,1.56,.64,1); }
156: .tgl.on { background: var(--accent); }
157: [dir="rtl"] .tgl.on > span { transform: translateX(-18px); }
158: [dir="ltr"] .tgl.on > span { transform: translateX(18px); }
159: .tgl.dis { opacity: .45; cursor: not-allowed; }
160: 
161: /* Checkbox */
162: .chk { width: 18px; height: 18px; border-radius: 6px; border: 1.5px solid var(--border-field); background: var(--bg-card); display: inline-flex; align-items: center; justify-content: center; color: #fff; flex-shrink: 0; transition: all .15s; }
163: .chk.on { background: var(--accent); border-color: var(--accent); }
164: .chk.mixed { background: var(--accent); border-color: var(--accent); }
165: 
166: /* Table */
167: .v-table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 13px; }
168: .v-table th { font-size: 11.5px; font-weight: 600; color: var(--text-muted); text-align: start; padding: 12px 14px; white-space: nowrap; border-bottom: 1px solid var(--divider-color); }
169: .v-table td { padding: 12px 14px; border-bottom: 1px solid var(--divider-color); vertical-align: middle; }
170: .v-table tbody tr { transition: background .12s; }
171: .v-table tbody tr:hover td { background: var(--bg-subcard); }
172: .v-table tbody tr:last-child td { border-bottom: 0; }
173: 
174: /* Skeleton */
175: @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
176: .skel { border-radius: 8px; background: linear-gradient(90deg, var(--bg-subcard) 0%, var(--bg-subcard-hover) 50%, var(--bg-subcard) 100%); background-size: 200% 100%; animation: shimmer 1.4s infinite linear; }
177: 
178: /* Motion */
179: @keyframes blurFadeIn { 0% { opacity: 0; filter: blur(10px); transform: translateY(8px); } 100% { opacity: 1; filter: blur(0); transform: none; } }
180: .stagger { animation: blurFadeIn .48s cubic-bezier(.22,1,.36,1) both; }
181: .s1 { animation-delay: .03s; } .s2 { animation-delay: .09s; } .s3 { animation-delay: .15s; } .s4 { animation-delay: .21s; } .s5 { animation-delay: .27s; }
182: @keyframes popIn { from { opacity: 0; transform: translateY(6px) scale(.98); } to { opacity: 1; transform: none; } }
183: .pop { animation: popIn .22s cubic-bezier(.22,1,.36,1) both; }
184: @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
185: .fade { animation: fadeIn .2s ease both; }
186: @keyframes spin { to { transform: rotate(360deg); } }
187: .spin { animation: spin .8s linear infinite; }
188: @keyframes stripe { to { background-position: 20px 0; } }
189: .progress-live { background: repeating-linear-gradient(-45deg, var(--accent) 0, var(--accent) 5px, var(--accent-2) 5px, var(--accent-2) 10px); background-size: 20px 100%; animation: stripe .6s linear infinite; }
190: 
191: @keyframes drawerIn { from { transform: translateX(-100%); } to { transform: none; } }
192: .drawer { animation: drawerIn .32s cubic-bezier(.22,1,.36,1) both; }
193: 
194: ::-webkit-scrollbar { width: 6px; height: 6px; }
195: ::-webkit-scrollbar-track { background: transparent; }
196: ::-webkit-scrollbar-thumb { background: rgba(150,145,160,.3); border-radius: 999px; }
197: 
198: .dropzone { border: 1.5px dashed var(--border-field); border-radius: 18px; transition: all .15s; }
