41:     };
42:     window.addEventListener('vortix:theme-change', handleCustom);
43: 
44:     const checkParent = () => {
45:       const rootNode = host.current?.getRootNode();
46:       const parentViewport = host.current?.closest('#app-viewport');
47:       const target = parentViewport || (rootNode?.host?.querySelector?.('#app-viewport') || rootNode?.host) || document.querySelector('#app-viewport') || document.querySelector('[data-vortix-host]');
