 1: 'use client';
 2: import { create } from 'zustand';
 3: import { persist } from 'zustand/middleware';
 4: import { setAuthToken, setUnauthorizedHandler } from '@alfarid/api-client';
 5: import type { ActorType, Destination } from '@/types/auth';
 6: 
 7: interface WebSession {
 8:   token: string | null;
 9:   actorType: Exclude<ActorType, 'staff'> | null;
10:   destination: Destination | null;
11:   home: string | null;
12:   user: Record<string, unknown> | null;
13:   setSession: (s: { token: string; actorType: 'customer' | 'supplier'; destination: Destination; home: string; user: Record<string, unknown> }) => void;
14:   clear: () => void;
15: }
16: 
17: export const useAuthStore = create<WebSession>()(
18:   persist(
19:     (set) => ({
20:       token: null, actorType: null, destination: null, home: null, user: null,
21:       setSession: (s) => { setAuthToken(s.token); set({ ...s }); },
22:       clear: () => { setAuthToken(null); set({ token: null, actorType: null, destination: null, home: null, user: null }); },
23:     }),
24:     {
25:       name: 'alfarid_web_auth',
26:       onRehydrateStorage: () => (state) => { if (state?.token) setAuthToken(state.token); },
27:     },
28:   ),
29: );
30: 
31: if (typeof window !== 'undefined') {
32:   window.addEventListener('storage', (event) => {
33:     if (event.storageArea !== localStorage || (event.key !== 'alfarid_web_auth' && event.key !== null)) return;
34:     let nextToken: string | null = null;
35:     try {
36:       nextToken = JSON.parse(localStorage.getItem('alfarid_web_auth') ?? 'null')?.state?.token ?? null;
37:     } catch { /* Invalid persisted sessions are discarded on reload. */ }
38:     if (nextToken !== useAuthStore.getState().token) window.location.reload();
39:   });
40:   setUnauthorizedHandler(() => {
41:     useAuthStore.getState().clear();
42:     if (window.location.pathname.startsWith('/auth/') || window.location.pathname === '/wholesale/register') return;
43:     window.location.href = `/auth/login?redirect=${encodeURIComponent(window.location.pathname)}`;
44:   });
45: }

