 1: export interface FormatCurrencyOptions {
 2:   locale?: string;
 3:   currency?: string;
 4:   minimumFractionDigits?: number;
 5:   maximumFractionDigits?: number;
 6: }
 7: 
 8: const formatterCache = new Map<string, Intl.NumberFormat>();
 9: 
10: function getFormatter(locale: string, currency: string, minDigits: number, maxDigits: number): Intl.NumberFormat {
11:   const key = `${locale}_${currency}_${minDigits}_${maxDigits}`;
12:   let formatter = formatterCache.get(key);
13:   if (!formatter) {
14:     formatter = new Intl.NumberFormat(locale, {
15:       style: 'currency',
16:       currency,
17:       minimumFractionDigits: minDigits,
18:       maximumFractionDigits: maxDigits,
19:     });
20:     formatterCache.set(key, formatter);
21:   }
22:   return formatter;
23: }
24: 
25: export function formatCurrency(
26:   amount: number | string | null | undefined,
27:   options: FormatCurrencyOptions = {}
28: ): string {
29:   const {
30:     locale = 'ar-EG',
31:     currency = 'EGP',
32:     minimumFractionDigits = 2,
33:     maximumFractionDigits = 2,
34:   } = options;
35: 
36:   const raw = typeof amount === 'string' ? parseFloat(amount) : (amount ?? 0);
37:   const numericAmount = isNaN(raw) ? 0 : raw;
38: 
39:   try {
40:     return getFormatter(locale, currency, minimumFractionDigits, maximumFractionDigits).format(numericAmount);
41:   } catch {
42:     return `${numericAmount.toFixed(minimumFractionDigits)} ${currency}`;
43:   }
44: }

 1: export interface FormatDateOptions {
 2:   locale?: string;
 3:   includeTime?: boolean;
 4:   dateStyle?: 'full' | 'long' | 'medium' | 'short';
 5:   timeStyle?: 'full' | 'long' | 'medium' | 'short';
 6: }
 7: 
 8: const dateTimeFormatterCache = new Map<string, Intl.DateTimeFormat>();
 9: 
10: function getDateTimeFormatter(locale: string, dateStyle: string, timeStyle?: string): Intl.DateTimeFormat {
11:   const key = `${locale}_${dateStyle}_${timeStyle ?? 'none'}`;
12:   let formatter = dateTimeFormatterCache.get(key);
13:   if (!formatter) {
14:     const opts: Intl.DateTimeFormatOptions = {
15:       dateStyle: dateStyle as Intl.DateTimeFormatOptions['dateStyle'],
16:     };
17:     if (timeStyle) {
18:       opts.timeStyle = timeStyle as Intl.DateTimeFormatOptions['timeStyle'];
19:     }
20:     formatter = new Intl.DateTimeFormat(locale, opts);
21:     dateTimeFormatterCache.set(key, formatter);
22:   }
23:   return formatter;
24: }
25: 
26: export function formatDate(
27:   dateInput: string | number | Date | null | undefined,
28:   options: FormatDateOptions = {}
29: ): string {
30:   if (!dateInput) return '-';
31: 
32:   const date = typeof dateInput === 'object' && dateInput instanceof Date ? dateInput : new Date(dateInput);
33:   if (isNaN(date.getTime())) return '-';
34: 
35:   const {
36:     locale = 'ar-EG',
37:     includeTime = false,
38:     dateStyle = 'medium',
39:     timeStyle = 'short',
40:   } = options;
41: 
42:   try {
43:     return getDateTimeFormatter(locale, dateStyle, includeTime ? timeStyle : undefined).format(date);
44:   } catch {
45:     return date.toISOString().split('T')[0];
46:   }
47: }

