 4: 
 5: namespace App\Console\Commands;
 6: 
 7: use App\Models\Customer;
 8: use Illuminate\Console\Command;
 9: use Illuminate\Support\Facades\DB;
10: use Illuminate\Support\Facades\Storage;
11: 
12: class PruneCustomerArtifacts extends Command
13: {
14:     protected $signature = 'customers:prune-artifacts';
15: 
16:     protected $description = 'Remove abandoned private staging files, expired phone challenges and old message counters';
17: 
18:     public function handle(): int
19:     {
20:         $disk = Storage::disk('r2');
21:         foreach ($disk->directories('customer_documents/pending') as $directory) {
22:             if (! preg_match('~^customer_documents/pending/[a-f0-9-]{36}$~D', $directory)) {
23:                 continue;
24:             }
25:             $newest = 0;
26:             foreach ($disk->allFiles($directory) as $file) {
27:                 $newest = max($newest, $disk->lastModified($file));
28:             }
29:             if ($newest < now()->subHour()->timestamp) {
30:                 $disk->deleteDirectory($directory);
31:             }
32:         }
33:         foreach ($disk->directories('customer_documents') as $directory) {
34:             if (! preg_match('~^customer_documents/([0-9]+)$~D', $directory, $matches)
35:                 || Customer::withTrashed()->whereKey($matches[1])->exists()) {
36:                 continue;
37:             }
38:             $newest = 0;
39:             foreach ($disk->allFiles($directory) as $file) {
40:                 $newest = max($newest, $disk->lastModified($file));
41:             }
42:             if ($newest < now()->subHour()->timestamp) {
43:                 $disk->deleteDirectory($directory);
44:             }
45:         }
46:         DB::table('customer_phone_verifications')->where('expires_at', '<', now()->subHour())->delete();
47:         DB::table('customer_message_budgets')->where('date', '<', now()->subDays(30)->toDateString())->delete();
48:         DB::table('customer_audit_logs')->whereIn('action', ['login_failed', 'login_succeeded', 'token_issued'])
49:             ->where('created_at', '<', now()->subDays(90))->delete();
50:         $this->info('Expired customer artifacts pruned.');
51: 
52:         return self::SUCCESS;
53:     }
54: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\Promotion\CouponRequest;
10: use App\Http\Resources\Admin\CouponResource;
11: use App\Models\Cart;
12: use App\Models\Coupon;
13: use Illuminate\Http\JsonResponse;
14: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
15: use Illuminate\Routing\Controllers\HasMiddleware;
16: use Illuminate\Routing\Controllers\Middleware;
17: use Illuminate\Support\Facades\DB;
18: 
19: /** إدارة كوبونات الخصم. */
20: class CouponController extends Controller implements HasMiddleware
21: {
22:     public static function middleware(): array
23:     {
24:         return [
25:             new Middleware('can:coupons.view', only: ['index', 'show']),
26:             new Middleware('can:coupons.create', only: ['store']),
27:             new Middleware('can:coupons.update', only: ['update']),
28:             new Middleware('can:coupons.delete', only: ['destroy']),
29:         ];
30:     }
31: 
32:     public function index(): AnonymousResourceCollection
33:     {
34:         return CouponResource::collection(Coupon::query()->latest('id')->paginate(20));
35:     }
36: 
37:     public function store(CouponRequest $request): JsonResponse
38:     {
39:         $data = $this->withoutNulls($request->validated());
40:         $data['value'] ??= 0;
41:         $data['usage_limit_per_customer'] ??= 1;
42:         $coupon = Coupon::create($data);
43: 
44:         return CouponResource::make($coupon)->response()->setStatusCode(201);
45:     }
46: 
47:     public function show(Coupon $coupon): CouponResource
48:     {
49:         return CouponResource::make($coupon);
50:     }
51: 
52:     public function update(CouponRequest $request, Coupon $coupon): CouponResource
53:     {
54:         $coupon->update($this->withoutNulls($request->validated()));
55: 
56:         return CouponResource::make($coupon);
57:     }
58: 
59:     public function destroy(Coupon $coupon): JsonResponse
60:     {
61:         // سجل الاستخدام تاريخ مالي: كوبون مُستخدَم لا يُحذف، يُعطَّل (M9)
62:         if ($coupon->usages()->exists()) {
63:             throw new BusinessException('لا يمكن حذف كوبون له استخدامات مسجلة؛ عطّله بدلًا من حذفه.');
64:         }
65: 
66:         DB::transaction(function () use ($coupon): void {
67:             // فكّ ارتباط السلال المعلقة حتى لا يتعطل إتمام شرائها (M9)
68:             Cart::query()->where('coupon_id', $coupon->id)->update(['coupon_id' => null]);
69:             $coupon->delete();
70:         });
71: 
72:         return response()->json(['message' => 'تم حذف الكوبون']);
73:     }
74: 
75:     /**
76:      * ‏null صريح لحقول NOT NULL يُحذف من الحمولة بدل ما يكسر الحفظ بـ 500 (M8).
77:      *
78:      * @param  array<string, mixed>  $data
79:      * @return array<string, mixed>
80:      */
81:     private function withoutNulls(array $data): array
82:     {
83:         foreach (['value', 'usage_limit_per_customer', 'is_active'] as $key) {
84:             if (array_key_exists($key, $data) && $data[$key] === null) {
85:                 unset($data[$key]);
86:             }
87:         }
88: 
89:         return $data;
90:     }
91: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Enums\SalesChannel;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Admin\Product\StoreProductRequest;
 11: use App\Http\Requests\Admin\Product\UpdateProductRequest;
 12: use App\Http\Resources\Admin\ProductResource;
 13: use App\Models\Category;
 14: use App\Models\Product;
 15: use App\Models\ProductVariant;
 16: use App\Services\Catalog\ProductService;
 17: use App\Services\SearchTerm;
 18: use Illuminate\Http\JsonResponse;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Routing\Controllers\HasMiddleware;
 22: use Illuminate\Routing\Controllers\Middleware;
 23: use Illuminate\Validation\Rule;
 24: 
 25: class ProductController extends Controller implements HasMiddleware
 26: {
 27:     public function __construct(private ProductService $service) {}
 28: 
 29:     public static function middleware(): array
 30:     {
 31:         return [
 32:             new Middleware('can:products.view', only: ['index', 'show']),
 33:             new Middleware('can:products.create', only: ['store']),
 34:             new Middleware('can:products.update', only: ['update']),
 35:             new Middleware('can:products.delete', only: ['destroy']),
 36:         ];
 37:     }
 38: 
 39:     public function index(Request $request): AnonymousResourceCollection
 40:     {
 41:         // فلاتر القائمة بتتفحص الأول: أي قيمة غلط تبقى 422 بدل 500 من Postgres
 42:         $filters = $request->validate([
 43:             'search' => ['nullable', 'string', 'max:100'],
 44:             'category_id' => ['nullable', 'integer', Rule::exists('categories', 'id')->whereNull('deleted_at')],
 45:             'brand_id' => ['prohibited'],
 46:             'status' => ['nullable', Rule::enum(ProductStatus::class)],
 47:             'sales_channel' => ['nullable', Rule::enum(SalesChannel::class)],
 48:             'is_featured' => ['nullable', 'boolean'],
 49:             'include_children' => ['nullable', 'boolean'],
 50:             'sort' => ['nullable', Rule::in(['latest', 'oldest', 'name'])],
 51:             'per_page' => ['nullable', 'integer', 'min:1'],
 52:         ]);
 53: 
 54:         $perPage = min((int) ($filters['per_page'] ?? 15), 100);
 55: 
 56:         $q = Product::query()
 57:             ->with(['category.media', 'media' => fn ($media) => $media->where('collection_name', 'images')->orderBy('order_column')->orderBy('id')->limit(1)])
 58:             ->withCount('variants')
 59:             ->withMin(['variants as min_retail_price' => fn ($v) => $v->where('is_active', true)], 'retail_price')
 60:             ->withMax(['variants as max_retail_price' => fn ($v) => $v->where('is_active', true)], 'retail_price');
 61: 
 62:         if (isset($filters['search']) && $filters['search'] !== '') {
 63:             $s = $filters['search'];
 64:             $pattern = SearchTerm::pattern($s);
 65:             // F15: SKUs/barcodes/codes are stored uppercased — match
 66:             // case-insensitively so a lowercase search still finds them.
 67:             // LOWER() comparisons stay index-backed via the lower(sku) /
 68:             // lower(barcode) functional unique indexes.
 69:             $u = strtoupper($s);
 70:             $q->where(fn ($w) => $w->whereLike('name_ar', $pattern, caseSensitive: false)
 71:                 ->orWhereLike('name_en', $pattern, caseSensitive: false)
 72:                 ->orWhere('code', $u)
 73:                 ->orWhereIn('products.id', ProductVariant::query()->select('product_id')
 74:                     ->where(fn ($v) => $v->whereRaw('LOWER(sku) = LOWER(?)', [$s])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$s]))));
 75:         }
 76:         if (! empty($filters['category_id'])) {
 77:             $cat = Category::findOrFail($filters['category_id']);
 78:             $ids = ! empty($filters['include_children']) ? [$cat->id, ...$cat->descendantIds()] : [$cat->id];
 79:             $q->whereIn('category_id', $ids);
 80:         }
 81:         $q->when($filters['status'] ?? null, fn ($x, $v) => $x->where('status', $v))
 82:             ->when($filters['sales_channel'] ?? null, fn ($x, $v) => $x->where('sales_channel', $v))
 83:             ->when(isset($filters['is_featured']), fn ($x) => $x->where('is_featured', filter_var($filters['is_featured'], FILTER_VALIDATE_BOOLEAN)));
 84: 
 85:         // ترتيب ثابت: id مفتاح كاسر للتعادل عشان الصفحات متتكررش ولا تختفي منها عناصر
 86:         match ($filters['sort'] ?? 'latest') {
 87:             'oldest' => $q->oldest()->orderBy('id'),
 88:             'name' => $q->orderBy('name_en')->orderBy('id'),
 89:             default => $q->latest()->orderByDesc('id'),
 90:         };
 91: 
 92:         $paginator = $q->paginate($perPage)->withQueryString();
 93: 
 94:         return ProductResource::collection($paginator);
 95:     }
 96: 
 97:     public function show(Product $product): ProductResource
 98:     {
 99:         return $this->productResource($product);
100:     }
101: 
102:     public function store(StoreProductRequest $request): JsonResponse
103:     {
104:         $data = $this->filterCostPrices($request->validated(), $request);
105:         $product = $this->service->create($data, $request->user());
106: 
107:         return $this->productResource($product)->response()->setStatusCode(201);
108:     }
109: 
110:     public function update(UpdateProductRequest $request, Product $product): ProductResource
111:     {
112:         $product = $this->service->update($product, $request->validated(), $request->user());
113: 
114:         return $this->productResource($product);
115:     }
116: 
117:     public function destroy(Request $request, Product $product): JsonResponse
118:     {
119:         $this->service->delete($product, $request->user());
120: 
121:         return response()->json(['message' => 'تم الحذف']);
122:     }
123: 
124:     private function productResource(Product $product): ProductResource
125:     {
126:         $product->loadMissing(['category.media', 'variants.media', 'media']);
127: 
128:         return ProductResource::make($product);
129:     }
130: 
131:     /**
132:      * @param  array<string, mixed>  $data
133:      * @return array<string, mixed>
134:      */
135:     private function filterCostPrices(array $data, Request $request): array
136:     {
137:         if (! $request->user()->can('products.view_cost')) {
138:             foreach ($data['variants'] ?? [] as $index => $variant) {
139:                 unset($data['variants'][$index]['cost_price']);
140:             }
141:         }
142: 
143:         return $data;
144:     }
145: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\Shipping\ShippingCompanyRequest;
10: use App\Http\Resources\Admin\ShippingCompanyResource;
11: use App\Models\ShippingCompany;
12: use Illuminate\Http\JsonResponse;
13: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
14: use Illuminate\Routing\Controllers\HasMiddleware;
15: use Illuminate\Routing\Controllers\Middleware;
16: 
17: /** إدارة شركات الشحن. */
18: class ShippingCompanyController extends Controller implements HasMiddleware
19: {
20:     public static function middleware(): array
21:     {
22:         return [
23:             new Middleware('can:shipping.view', only: ['index', 'show']),
24:             new Middleware('can:shipping.create', only: ['store']),
25:             new Middleware('can:shipping.update', only: ['update']),
26:             new Middleware('can:shipping.delete', only: ['destroy']),
27:         ];
28:     }
29: 
30:     public function index(): AnonymousResourceCollection
31:     {
32:         return ShippingCompanyResource::collection(ShippingCompany::query()->latest('id')->paginate(20));
33:     }
34: 
35:     public function store(ShippingCompanyRequest $request): JsonResponse
36:     {
37:         $company = ShippingCompany::create($request->validated());
38: 
39:         return ShippingCompanyResource::make($company)->response()->setStatusCode(201);
40:     }
41: 
42:     public function show(ShippingCompany $shippingCompany): ShippingCompanyResource
43:     {
44:         return ShippingCompanyResource::make($shippingCompany);
45:     }
46: 
47:     public function update(ShippingCompanyRequest $request, ShippingCompany $shippingCompany): ShippingCompanyResource
48:     {
49:         $data = $request->validated();
50:         // الأسرار لا تُرجع في الردود (has_api_credentials فقط)، فشاشة التعديل
51:         // ترسل null — تُتجاهل ولا تمحو الأسرار المحفوظة (M10)
52:         if (array_key_exists('api_credentials', $data)) {
53:             if ($data['api_credentials'] === null) {
54:                 unset($data['api_credentials']);
55:             } else {
56:                 // دمج لا استبدال (F21): تحديث مفتاح واحد لا يمحو بقية أسرار
57:                 // الشركة (مفتاح API، سر الوب هوك...) المعروضة كـ null في الشاشة
58:                 $data['api_credentials'] = array_merge(
59:                     $shippingCompany->api_credentials ?? [],
60:                     $data['api_credentials'],
61:                 );
62:             }
63:         }
64:         $shippingCompany->update($data);
65: 
66:         return ShippingCompanyResource::make($shippingCompany);
67:     }
68: 
69:     public function destroy(ShippingCompany $shippingCompany): JsonResponse
70:     {
71:         // شركة لها بوليصات: الحذف يكسر FK — يُمنع ويُعطَّل بدلًا منه (M9)
72:         if ($shippingCompany->shipments()->exists()) {
73:             throw new BusinessException('لا يمكن حذف شركة شحن لها بوليصات مسجلة؛ عطّلها بدلًا من حذفها.');
74:         }
75:         $shippingCompany->delete();
76: 
77:         return response()->json(['message' => 'تم حذف شركة الشحن']);
78:     }
79: }

