 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Store;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Resources\Store\StoreBannerResource;
 9: use App\Http\Resources\Store\StoreProductCardResource;
10: use App\Models\Banner;
11: use App\Services\StoreCatalogService;
12: use Illuminate\Contracts\Cache\LockTimeoutException;
13: use Illuminate\Http\JsonResponse;
14: use Illuminate\Http\Request;
15: use Illuminate\Support\Collection;
16: use Illuminate\Support\Facades\Cache;
17: 
18: /**
19:  * الصفحة الرئيسية للمتجر: رد مجمّع واحد (بانرات + أحدث + أكثر مبيعًا + مخفضات).
20:  * الكاش يخزن معرّفات الأقسام فقط (5 دقائق) — الأسعار تُحسب لكل طلب على حدة
21:  * لأنها شخصية (خصم مجموعة/سعر خاص)، فلا تتسرب أسعار عميل لزائر آخر أبدًا.
22:  */
23: class HomeController extends Controller
24: {
25:     public function __construct(private readonly StoreCatalogService $catalog) {}
26: 
27:     public function index(Request $request): JsonResponse
28:     {
29:         try {
30:             $load = fn () => Cache::flexible('store_home_data', [300, 1800],
31:                 fn () => $this->catalog->homeSectionIds(), ['seconds' => 120]);
32:             $ids = Cache::has('store_home_data') ? $load() : Cache::lock('store_home_data:build', 120)->block(3, $load);
33:         } catch (LockTimeoutException) {
34:             return response()->json(['message' => 'الصفحة قيد التحديث؛ أعد المحاولة بعد لحظات.'], 503, ['Retry-After' => '2']);
35:         }
36:         $allIds = array_unique([...$ids['latest_ids'], ...$ids['best_seller_ids'], ...$ids['discounted_ids']]);
37:         $cards = StoreProductCardResource::collection($this->catalog->publishedQuery()
38:             ->whereIn('products.id', $allIds)->get())->resolve($request);
39:         $cards = collect($cards)->keyBy('id');
40:         $section = fn (array $sectionIds) => collect($sectionIds)->map(fn ($id) => $cards->get($id))->filter()->values();
41: 
42:         return response()->json([
43:             'data' => [
44:                 'banners' => StoreBannerResource::collection($this->inOrder(Banner::query()
45:                     ->where('is_active', true)
46:                     ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', now()))
47:                     ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', now())), $ids['banner_ids']))->resolve($request),
48:                 'latest_products' => $section($ids['latest_ids']),
49:                 'best_sellers' => $section($ids['best_seller_ids']),
50:                 'discounted_products' => $section($ids['discounted_ids'])->filter(fn ($card) => $card['price'] !== null && $card['discount_percentage'] !== null)->values(),
51:             ],
52:         ]);
53:     }
54: 
55:     /** @param list<int> $ids */
56:     private function inOrder($query, array $ids): Collection
57:     {
58:         if ($ids === []) {
59:             return collect();
60:         }
61:         $positions = array_flip($ids);
62: 
63:         return $query->whereIn('id', $ids)->get()->sortBy(fn ($m) => $positions[$m->id] ?? PHP_INT_MAX)->values();
64:     }
65: }

