 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Models\Customer;
 9: use App\Models\ReturnRequestItem;
10: use App\Models\SupplierDelivery;
11: use App\Models\SupplierInvoice;
12: use App\Models\SupplierUser;
13: use App\Models\User;
14: use App\Models\WholesalePaymentNotice;
15: use Illuminate\Http\Request;
16: use Illuminate\Support\Facades\Storage;
17: use Symfony\Component\HttpFoundation\StreamedResponse;
18: 
19: class AttachmentController extends Controller
20: {
21:     public function returnFile(Request $request, int $returnItem, int $attachment): StreamedResponse
22:     {
23:         $actor = $request->user();
24:         $query = ReturnRequestItem::query();
25:         if ($actor instanceof Customer) {
26:             $query->whereHas('returnRequest', fn ($q) => $q->where('customer_id', $actor->id));
27:         } else {
28:             abort_unless($actor instanceof User && $actor->can('returns.view'), 403);
29:         }
30:         $item = $query->findOrFail($returnItem);
31: 
32:         return $this->download(($item->attachments ?? [])[$attachment] ?? null);
33:     }
34: 
35:     public function invoice(Request $request, int $invoice): StreamedResponse
36:     {
37:         $actor = $request->user();
38:         $query = SupplierInvoice::query();
39:         if ($actor instanceof SupplierUser) {
40:             $query->where('supplier_id', $actor->supplier_id)->where('status', '!=', 'draft');
41:         } else {
42:             abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
43:         }
44: 
45:         return $this->download($query->findOrFail($invoice)->attachment_path);
46:     }
47: 
48:     public function delivery(Request $request, int $delivery): StreamedResponse
49:     {
50:         $actor = $request->user();
51:         $query = SupplierDelivery::query();
52:         if ($actor instanceof SupplierUser) {
53:             $query->where('supplier_id', $actor->supplier_id);
54:         } else {
55:             abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
56:         }
57: 
58:         return $this->download($query->findOrFail($delivery)->invoice_file_path);
59:     }
60: 
61:     public function paymentNotice(Request $request, int $notice): StreamedResponse
62:     {
63:         $actor = $request->user();
64:         $query = WholesalePaymentNotice::query();
65:         if ($actor instanceof Customer) {
66:             $query->where('customer_id', $actor->id);
67:         } else {
68:             abort_unless($actor instanceof User && $actor->can('payment_notices.view'), 403);
69:         }
70: 
71:         return $this->download($query->findOrFail($notice)->receipt_file_path);
72:     }
73: 
74:     private function download(?string $path): StreamedResponse
75:     {
76:         abort_if($path === null || ! Storage::disk('r2')->exists($path), 404);
77: 
78:         return Storage::disk('r2')->download($path, basename($path), ['X-Content-Type-Options' => 'nosniff', 'Cache-Control' => 'private, no-store']);
79:     }
80: }

