 5: namespace App\Http\Requests\Admin\Promotion;
 6: 
 7: use Illuminate\Foundation\Http\FormRequest;
 8: use Illuminate\Validation\Rule;
 9: use Illuminate\Validation\Validator;
10: 
11: class CouponRequest extends FormRequest
12: {
13:     public function authorize(): bool
14:     {
15:         return true;
16:     }
17: 
18:     /** @return array<string, mixed> */
19:     public function rules(): array
20:     {
21:         $coupon = $this->route('coupon');
22: 
23:         return [
24:             'code' => ['required', 'string', 'max:50', Rule::unique('coupons', 'code')->ignore($coupon)],
25:             'type' => ['required', Rule::in(['percentage', 'fixed', 'free_shipping'])],
26:             // كوبون نسبي فوق 100% يعني خصمًا كاملًا وأكثر — ممنوع (M18)
27:             'value' => ['nullable', 'numeric', 'min:0', Rule::when($this->input('type') === 'percentage', ['max:100'])],
28:             'max_discount_amount' => ['nullable', 'numeric', 'min:0'],
29:             'min_order_amount' => ['nullable', 'numeric', 'min:0'],
30:             'usage_limit' => ['nullable', 'integer', 'min:1'],
31:             'usage_limit_per_customer' => ['nullable', 'integer', 'min:0'],
32:             'starts_at' => ['nullable', 'date'],
33:             'ends_at' => ['nullable', 'date', 'after_or_equal:starts_at'],
34:             'is_active' => ['nullable', 'boolean'],
35:         ];
36:     }
37: 
38:     /**
39:      * (M1) فحص القيمة «الفعّالة» بعد الدمج مع الكوبون الحالي: قاعدة max:100
40:      * أعلاه تعتمد على النوع المُرسل، فطلب تعديل يغيّر النوع إلى percentage
41:      * دون إرسال value كان يترك قيمة قديمة (>100) تمرّ دون فحص.
42:      *
43:      * @return list<callable(Validator): void>
44:      */
45:     public function after(): array
46:     {
47:         return [function (Validator $validator): void {
48:             if ($validator->errors()->isNotEmpty()) {
49:                 return;
50:             }
51: 
52:             $coupon = $this->route('coupon');
53:             $type = $this->input('type');
54:             // قيمة غير رقمية (بما فيها null الصريح) تعني «أبقِ الحالية» في
55:             // مسار التعديل — فالفحص على القيمة الفعلية لا المُرسلة
56:             $submitted = $this->input('value');
57:             $effective = is_numeric($submitted) ? (float) $submitted : (float) ($coupon?->value ?? 0);
58: 
59:             if ($type === 'percentage' && $effective > 100) {
60:                 $validator->errors()->add('value', 'نسبة الكوبون لا تتجاوز 100%.');
61:             }
62:         }];
63:     }
64: 
65:     protected function prepareForValidation(): void
66:     {
67:         if (is_string($this->input('code'))) {
68:             $this->merge(['code' => strtoupper(trim($this->input('code')))]);
69:         }
70:     }
71: }

