 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Models;
 6: 
 7: use App\Enums\ProductStatus;
 8: use App\Enums\SalesChannel;
 9: use App\Models\Concerns\TracksEditVersion;
10: use Database\Factories\ProductFactory;
11: use Illuminate\Database\Eloquent\Factories\HasFactory;
12: use Illuminate\Database\Eloquent\Model;
13: use Illuminate\Database\Eloquent\Relations\BelongsTo;
14: use Illuminate\Database\Eloquent\Relations\HasMany;
15: use Illuminate\Database\Eloquent\SoftDeletes;
16: use Illuminate\Support\Collection;
17: use Spatie\Image\Enums\Fit;
18: use Spatie\MediaLibrary\HasMedia;
19: use Spatie\MediaLibrary\InteractsWithMedia;
20: use Spatie\MediaLibrary\MediaCollections\Models\Media;
21: 
22: class Product extends Model implements HasMedia
23: {
24:     /** @use HasFactory<ProductFactory> */
25:     use HasFactory, InteractsWithMedia, SoftDeletes, TracksEditVersion;
26: 
27:     protected $fillable = [
28:         'code', 'category_id', 'brand_id', 'supplier_id', 'name_ar', 'name_en', 'slug',
29:         'description_ar', 'description_en', 'material_ar', 'material_en',
30:         'length_cm', 'width_cm', 'height_cm', 'weight_kg', 'warranty_months', 'warranty_details',
31:         'country_of_origin', 'status', 'sales_channel', 'is_featured', 'sales_count', 'published_at', 'created_by', 'create_key', 'create_request_hash',
32:     ];
33: 
34:     protected $casts = [
35:         'status' => ProductStatus::class,
36:         'sales_channel' => SalesChannel::class,
37:         'is_featured' => 'boolean',
38:         'is_active' => 'boolean',
39:         'sales_count' => 'integer',
40:         'published_at' => 'datetime',
41:         'length_cm' => 'decimal:2', 'width_cm' => 'decimal:2', 'height_cm' => 'decimal:2',
42:         'weight_kg' => 'decimal:3',
43:     ];
44: 
45:     public function category(): BelongsTo
46:     {
47:         return $this->belongsTo(Category::class);
48:     }
49: 
50:     public function brand(): BelongsTo
51:     {
52:         return $this->belongsTo(Brand::class);
53:     }
54: 
55:     public function variants(): HasMany
56:     {
57:         // chaperone: كل variant متحمل من العلاقة دي بيبقى عارف منتجه من غير lazy load (N+1)
58:         return $this->hasMany(ProductVariant::class)->orderBy('sort_order')->chaperone();
59:     }
60: 
61:     public function registerMediaCollections(): void
62:     {
63:         $this->addMediaCollection('images')->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
64:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
65:         $this->addMediaCollection('video')->singleFile()->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
66:             ->acceptsMimeTypes(['video/mp4', 'video/webm', 'video/quicktime']);
67:     }
68: 
69:     public function catalogImages(): Collection
70:     {
71:         $variants = $this->relationLoaded('variants')
72:             ? $this->variants
73:             : $this->variants()->where('is_active', true)->with('media')->get();
74: 
75:         return $this->getMedia('images')->concat($variants
76:             ->filter(fn ($variant) => $variant->is_active && ! $variant->trashed())
77:             ->flatMap(fn ($variant) => $variant->getMedia('images')))->values();
78:     }
79: 
80:     public function registerMediaConversions(?Media $media = null): void
81:     {
82:         // H2 keeps conversions synchronous but lock-free: each upload runs in its
83:         // own short transaction with no product lock held while R2 I/O renders.
84:         // Queuing them would break per-file atomicity (a failed conversion must
85:         // roll back its own file) that the media pipeline and tests rely on.
86:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
87:             ->performOnCollections('images')->nonQueued();
88:         $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
89:             ->performOnCollections('images')->nonQueued();
90:     }
91: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services\Catalog;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Category;
 10: use App\Models\Product;
 11: use App\Models\ProductVariant;
 12: use App\Models\StockLevel;
 13: use App\Models\User;
 14: use App\Services\IdempotencyFingerprint;
 15: use App\Services\SlugService;
 16: use Illuminate\Database\UniqueConstraintViolationException;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: class ProductService
 20: {
 21:     public function __construct(private ProductPublishabilityChecker $publishability) {}
 22: 
 23:     public function create(array $data, User $user): Product
 24:     {
 25:         // F9: the backoffice keeps the form alive across a lost response, so a
 26:         // retried save with the same create_key replays the existing row
 27:         // instead of creating a slug ...-2 duplicate.
 28:         $createKey = is_string($data['create_key'] ?? null) && $data['create_key'] !== '' ? $data['create_key'] : null;
 29:         unset($data['create_key']);
 30:         $requestHash = IdempotencyFingerprint::hash($data);
 31:         if ($createKey !== null) {
 32:             $existing = Product::withTrashed()->where('created_by', $user->id)->where('create_key', $createKey)->first();
 33:             if ($existing) {
 34:                 return $this->replayCreation($existing, $requestHash);
 35:             }
 36:         }
 37: 
 38:         // M1: concurrent creates can generate the same auto slug; retry once with
 39:         // a fresh slug, and surface explicit-slug conflicts as 409 not 500.
 40:         $autoSlug = empty($data['slug'] ?? null);
 41:         for ($attempt = 0; ; $attempt++) {
 42:             try {
 43:                 return DB::transaction(function () use ($data, $user, $createKey, $requestHash) {
 44:                     CatalogLock::tree(shared: true);
 45:                     $data['brand_id'] = null;
 46:                     $data['supplier_id'] = null;
 47:                     $variants = $data['variants'] ?? [];
 48:                     unset($data['variants']);
 49:                     $data = array_filter($data, fn ($value) => $value !== null);
 50: 
 51:                     if (($data['status'] ?? 'draft') !== ProductStatus::Draft->value) {
 52:                         throw new BusinessException('يجب إنشاء المنتج كمسودة ثم رفع صوره ونشره', ['status' => ['الحالة المسموحة عند الإنشاء هي draft']]);
 53:                     }
 54: 
 55:                     $data['slug'] = $data['slug'] ?? SlugService::make(Product::class, $data['name_en']);
 56:                     $data['created_by'] = $user->id;
 57:                     $data['create_key'] = $createKey;
 58:                     $data['create_request_hash'] = $createKey !== null ? $requestHash : null;
 59:                     $data['status'] = ProductStatus::Draft->value; // دايمًا يتعمل draft الأول
 60: 
 61:                     // قفل القسم يمنع حذفه أثناء إنشاء المنتج
 62:                     $this->lockReference(Category::class, (int) $data['category_id'], 'category_id');
 63: 
 64:                     $product = Product::create($data);
 65:                     $product->update(['code' => 'P'.str_pad((string) $product->id, 5, '0', STR_PAD_LEFT)]);
 66: 
 67:                     foreach ($variants as $v) {
 68:                         app(VariantService::class)->create($product, $v);
 69:                     }
 70: 
 71:                     return $product->fresh(['category.media', 'variants.media', 'media']);
 72:                 });
 73:             } catch (UniqueConstraintViolationException $e) {
 74:                 // A concurrent retry with the same key may have won the race.
 75:                 if ($createKey !== null) {
 76:                     $winner = Product::withTrashed()->where('created_by', $user->id)->where('create_key', $createKey)->first();
 77:                     if ($winner) {
 78:                         return $this->replayCreation($winner, $requestHash);
 79:                     }
 80:                 }
 81:                 if ($autoSlug && $attempt === 0) {
 82:                     $data['slug'] = SlugService::make(Product::class, $data['name_en']);
 83: 
 84:                     continue;
 85:                 }
 86:                 throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 87:             }
 88:         }
 89:     }
 90: 
 91:     public function update(Product $product, array $data, User $user): Product
 92:     {
 93:         $expectedVersion = $data['expected_version'] ?? null;
 94:         unset($data['expected_version']);
 95:         if (! empty($data['expected_updated_at']) && $expectedVersion === null) {
 96:             throw new BusinessException('أعد تحميل المنتج لإرسال رقم الإصدار قبل الحفظ.', ['expected_version' => ['رقم الإصدار مطلوب.']]);
 97:         }
 98:         unset($data['expected_updated_at']);
 99: 
100:         // F8: a concurrent update can win the slug between validation and the
101:         // write — surface it as 409, not 500.
102:         try {
103:             return DB::transaction(function () use ($product, $data, $user, $expectedVersion) {
104:                 CatalogLock::tree(shared: true);
105:                 // قفل صف المنتج طول التعديل عشان فحص النشر ميعديش مع تعديل متزامن
106:                 $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
107: 
108:                 if ($expectedVersion !== null && (int) $expectedVersion !== (int) $product->lock_version) {
109:                     throw new BusinessException('المنتج تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
110:                 }
111: 
112:                 unset($data['brand_id'], $data['supplier_id']);
113:                 $newStatus = isset($data['status']) ? ProductStatus::from($data['status']) : null;
114:                 unset($data['status']);
115: 
116:                 if (array_key_exists('slug', $data) && empty($data['slug'])) {
117:                     $data['slug'] = SlugService::make(Product::class, $data['name_en'] ?? $product->name_en, $product->id);
118:                 }
119:                 $this->lockReference(Category::class, (int) ($data['category_id'] ?? $product->category_id), 'category_id');
120: 
121:                 if (array_key_exists('is_featured', $data) && $data['is_featured'] === null) {
122:                     unset($data['is_featured']);
123:                 }
124: 
125:                 $product->update($data);
126: 
127:                 if ($newStatus && $newStatus !== $product->status) {
128:                     $this->changeStatus($product, $newStatus, $user);
129:                 } elseif ($product->status === ProductStatus::Published) {
130:                     // تعديل من غير تغيير حالة على منتج منشور: القواعد بتتفحص من جديد
131:                     $this->assertPublishable($product);
132:                 }
133: 
134:                 return $product->fresh(['category.media', 'variants.media', 'media']);
135:             });
136:         } catch (UniqueConstraintViolationException $e) {
137:             throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
138:         }
139:     }
140: 
141:     private function replayCreation(Product $product, string $requestHash): Product
142:     {
143:         if ($product->trashed()) {
144:             throw new BusinessException('المنتج الخاص بطلب الإنشاء محذوف بالفعل.', [], 409);
145:         }
146:         if ($product->create_request_hash !== null && ! hash_equals($product->create_request_hash, $requestHash)) {
147:             throw new BusinessException('تم إنشاء المنتج من الطلب السابق ببيانات مختلفة؛ أعد تحميله قبل التعديل.', ['product_id' => [$product->id]], 409);
148:         }
149: 
150:         return $product->fresh(['category.media', 'variants.media', 'media']);
151:     }
152: 
153:     public function changeStatus(Product $product, ProductStatus $status, User $user): void
154:     {
155:         DB::transaction(function () use ($product, $status, $user): void {
156:             CatalogLock::tree(shared: true);
157:             // قفل صف المنتج وقسمه قبل الفحص والنشر، عشان مفيش تعديل متزامن يعدي بين الفحص والحفظ
158:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
159:             if ($product->category_id) {
160:                 $this->lockReference(Category::class, (int) $product->category_id, 'category_id');
161:             }
162:             $product->refresh();
163: 
164:             if ($product->status !== $status && ($product->status === ProductStatus::Published || $status === ProductStatus::Published) && ! $user->can('products.publish')) {
165:                 throw new BusinessException('ليس لديك صلاحية تغيير نشر المنتجات', [], 403);
166:             }
167: 
168:             if ($status === ProductStatus::Published) {
169:                 $this->assertPublishable($product);
170:                 $product->published_at ??= now();
171:             }
172:             $product->status = $status;
173:             $product->save();
174:         });
175:         $product->refresh();
176:     }
177: 
178:     public function assertPublishable(Product $product): void
179:     {
180:         $this->publishability->assertPublishable($product);
181:     }
182: 
183:     private function lockReference(string $model, int $id, string $field): void
184:     {
185:         if (! $model::whereKey($id)->sharedLock()->first()) {
186:             throw new BusinessException('أحد المراجع المطلوبة لم يعد متاحًا', [$field => ['القيمة المحددة غير موجودة أو محذوفة']]);
187:         }
188:     }
189: 
190:     public function delete(Product $product, ?User $user = null): void
191:     {
192:         DB::transaction(function () use ($product, $user): void {
193:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
194:             if ($user && $product->status === ProductStatus::Published && ! $user->can('products.publish')) {
195:                 throw new BusinessException('حذف منتج منشور يتطلب صلاحية النشر.', [], 403);
196:             }
197:             // H3: lock every variant row (id-ordered) before the balance check so
198:             // concurrent receipts serialize here instead of slipping underneath it.
199:             $lockedIds = ProductVariant::where('product_id', $product->id)->orderBy('id')->lockForUpdate()->pluck('id');
200:             // حذف المنتج يحذف متغيراته ناعمًا: أي رصيد على أي منها يُحبس (M-9)
201:             if (StockLevel::query()->whereIn('product_variant_id', $lockedIds)->hasNonZeroBalance()->exists()) {
202:                 throw new BusinessException('لا يمكن حذف منتج له متغيرات برصيد مخزون؛ صفِّ الأرصدة أولًا.');
203:             }
204:             $product->variants()->delete();  // soft
205:             $product->delete();              // soft
206:         });
207:         // TODO مرحلة الطلبات: منع الحذف لو المنتج عليه طلبات، وبدل كده يتعمل archived
208:     }
209: 
210:     /**
211:      * F14: permanent removal also removes the media rows AND their R2 files —
212:      * soft-delete intentionally keeps them (old links/caches keep working),
213:      * but a force-delete must not leave publicly reachable files behind.
214:      */
215:     public function forceDelete(Product $product): void
216:     {
217:         DB::transaction(function () use ($product): void {
218:             $product = Product::withTrashed()->whereKey($product->id)->lockForUpdate()->firstOrFail();
219:             $variants = $product->variants()->withTrashed()->reorder('id')->lockForUpdate()->get();
220:             if (StockLevel::query()->whereIn('product_variant_id', $variants->pluck('id'))->hasNonZeroBalance()->exists()) {
221:                 throw new BusinessException('لا يمكن الحذف النهائي لمنتج له متغيرات برصيد مخزون؛ صفِّ الأرصدة أولًا.');
222:             }
223:             foreach ($variants as $variant) {
224:                 $variant->clearMediaCollection('images');
225:                 $variant->forceDelete();
226:             }
227:             $product->clearMediaCollection('images');
228:             $product->clearMediaCollection('video');
229:             $product->forceDelete();
230:         });
231:     }
232: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: /**
 8:  * بصمة حمولات عدم التكرار: ترتيب حتمي لمفاتيح المصفوفات وتطبيع للأرقام،
 9:  * بحيث تنتج الاختلافات الشكلية في تسلسل العميل ("5" مقابل 5 مقابل 5.0)
10:  * نفس البصمة، فلا تتحول إعادة إرسال مطابقة إلى 409 زائف (L-2).
11:  */
12: final class IdempotencyFingerprint
13: {
14:     public static function hash(array $payload): string
15:     {
16:         return hash('sha256', json_encode(self::canonicalize($payload), JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
17:     }
18: 
19:     private static function canonicalize(mixed $value, ?string $field = null): mixed
20:     {
21:         if (is_numeric($value) && in_array($field, [
22:             'amount', 'subtotal', 'tax_amount', 'unit_cost', 'unit_price', 'line_total',
23:             'grand_total', 'discount_amount', 'total', 'total_amount', 'paid_amount',
24:             'expected_total',
25:         ], true)) {
26:             return (int) round(((float) $value) * 100);
27:         }
28: 
29:         if (is_string($value) && is_numeric($value)
30:             && ($field === 'id' || str_ends_with($field ?? '', '_id')
31:                 || in_array($field, ['qty', 'amount', 'received_good_qty', 'received_damaged_qty', 'quantity', 'requested_qty', 'counted_qty', 'approved_qty', 'shipped_qty', 'received_qty'], true))) {
32:             $value = $value + 0;
33:         }
34: 
35:         if (is_float($value) && floor($value) === $value && abs($value) <= 9007199254740991) {
36:             return (int) $value;
37:         }
38: 
39:         if (! is_array($value)) {
40:             return $value;
41:         }
42: 
43:         $isList = array_is_list($value);
44:         $mapped = [];
45:         foreach ($value as $key => $item) {
46:             $mapped[$key] = self::canonicalize($item, is_string($key) ? $key : null);
47:         }
48: 
49:         if ($isList && $mapped !== [] && self::isItemList($mapped)) {
50:             usort($mapped, self::itemSort(...));
51:         }
52: 
53:         if (! $isList) {
54:             ksort($mapped);
55:         }
56: 
57:         return $mapped;
58:     }
59: 
60:     /** @param list<mixed> $items */
61:     private static function isItemList(array $items): bool
62:     {
63:         foreach ($items as $item) {
64:             if (! is_array($item) || (! isset($item['id']) && ! isset($item['order_item_id']) && ! isset($item['purchase_order_item_id']) && ! isset($item['product_variant_id']))) {
65:                 return false;
66:             }
67:         }
68: 
69:         return true;
70:     }
71: 
72:     /** @param array<string, mixed> $left */
73:     private static function itemSort(array $left, array $right): int
74:     {
75:         foreach (['order_item_id', 'purchase_order_item_id', 'id', 'product_variant_id'] as $key) {
76:             if (isset($left[$key], $right[$key])) {
77:                 return $left[$key] <=> $right[$key];
78:             }
79:         }
80: 
81:         return 0;
82:     }
83: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\PriceListType;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\PriceListItem;
 13: use App\Models\ProductVariant;
 14: use Brick\Math\BigDecimal;
 15: use Brick\Math\RoundingMode;
 16: use Carbon\Carbon;
 17: use Illuminate\Database\Eloquent\Builder;
 18: 
 19: /**
 20:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 21:  *
 22:  * شجرة الأولويات:
 23:  * 1. سعر خاص بالعميل (customer_specific)
 24:  * 2. سعر مجموعة العميل (customer_group)
 25:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)؛ وقناة
 26:  *    جملة/موزع بلا عنصر مطابق ترجع لقوائم retail النشطة قبل السعر الأساسي.
 27:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 28:  *
 29:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 30:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 31:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 32:  *
 33:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 34:  * ثم أولوية القائمة، ثم السعر الأقل.
 35:  */
 36: class PricingService
 37: {
 38:     /**
 39:      * F17: preload the per-customer pricing context once per listing and pass
 40:      * it down — resolve()/tiersFor() otherwise re-query the customer group on
 41:      * every variant (15 products x variants x calls per page).
 42:      *
 43:      * @return array{channel: PriceListType, eligible: bool, group: object|null}
 44:      */
 45:     public function contextFor(?Customer $customer, ?array $variantIds = null): array
 46:     {
 47:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 48:         $group = $eligible ? $customer->customerGroup()->where('is_active', true)->first() : null;
 49: 
 50:         $channel = $this->channelFor($customer);
 51:         $context = ['channel' => $channel, 'eligible' => $eligible, 'group' => $group];
 52:         if ($variantIds !== null) {
 53:             $context['items'] = $this->eligibleItems(null, PHP_FLOAT_MAX, null, Carbon::now(), $variantIds)
 54:                 ->where(function ($q) use ($channel, $eligible, $customer, $group): void {
 55:                     $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 56:                     if ($eligible) {
 57:                         $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerSpecific)
 58:                             ->where('price_lists.customer_id', $customer->id));
 59:                     }
 60:                     if ($group !== null) {
 61:                         $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerGroup)
 62:                             ->where('price_lists.customer_group_id', $group->id));
 63:                     }
 64:                 })
 65:                 ->addSelect('price_lists.type as pricing_type', 'price_lists.branch_id as pricing_branch_id', 'price_lists.priority as pricing_priority')
 66:                 ->get()->groupBy('product_variant_id');
 67:         }
 68: 
 69:         return $context;
 70:     }
 71: 
 72:     /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
 73:     public function withStorePrice(Builder $variants, ?Customer $customer): Builder
 74:     {
 75:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 76:         $channel = $this->channelFor($customer);
 77:         $group = $eligible ? $customer->customerGroup : null;
 78:         $group = $group?->is_active ? $group : null;
 79:         $factor = $this->discountFactor($group?->discount_percentage ?? '0');
 80:         $items = $this->eligibleItems(null, 1, null, Carbon::now())
 81:             ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
 82:                 $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 83:                 if ($eligible) {
 84:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
 85:                         ->where('price_lists.customer_id', $customer->id));
 86:                 }
 87:                 if ($group !== null) {
 88:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
 89:                         ->where('price_lists.customer_group_id', $group->id));
 90:                 }
 91:             })
 92:             ->select([])
 93:             ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
 94:             ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
 95:         $items = $this->ordered($items)->limit(1);
 96: 
 97:         return $variants->select('product_variants.*')
 98:             ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), product_variants.retail_price * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor]);
 99:     }
100: 
101:     /**
102:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
103:      */
104:     public function resolve(
105:         ProductVariant $variant,
106:         ?Customer $customer = null,
107:         float $qty = 1,
108:         ?int $branchId = null,
109:         ?array $ctx = null,
110:     ): array {
111:         if (! is_finite($qty) || $qty <= 0) {
112:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
113:         }
114:         $now = Carbon::now();
115: 
116:         // F17: reuse the preloaded per-customer context when the caller passes
117:         // it (wholesale listing); otherwise load it for this single call.
118:         $ctx ??= $this->contextFor($customer);
119:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
120:         $channel = $ctx['channel'];
121:         $eligibleCustomer = $ctx['eligible'];
122:         $pick = function (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null) use ($ctx, $variant, $qty, $baseQuery, $branchId): ?PriceListItem {
123:             if (isset($ctx['items']) && $branchId === null) {
124:                 return ($ctx['items'][$variant->id] ?? collect())
125:                     ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
126:                     ->sort(function ($a, $b): int {
127:                         return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
128:                             ?: ((float) $b->min_qty <=> (float) $a->min_qty)
129:                             ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
130:                             ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
131:                             ?: ((int) $a->id <=> (int) $b->id);
132:                     })->first();
133:             }
134: 
135:             return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
136:                 ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
137:         };
138: 
139:         // الأولوية 1: سعر خاص بالعميل
140:         if ($eligibleCustomer) {
141:             $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);
142: 
143:             if ($item !== null) {
144:                 return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
145:             }
146:         }
147: 
148:         // الأولوية 2: سعر مجموعة العميل
149:         $group = $ctx['group'];
150:         if ($group !== null) {
151:             $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);
152: 
153:             if ($item !== null) {
154:                 return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
155:             }
156:         }
157: 
158:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
159:         $item = $pick($channel);
160: 
161:         // قناة جملة/موزع بلا عنصر في قائمتها ترجع لقوائم القطاعي النشطة قبل
162:         // السعر الأساسي — وإلا دفع عميل الجملة أكثر من عميل التجزئة (M-1).
163:         if ($item === null && $channel !== PriceListType::Retail) {
164:             $item = $pick(PriceListType::Retail);
165: 
166:             if ($item !== null) {
167:                 $channel = PriceListType::Retail;
168:             }
169:         }
170: 
171:         if ($item !== null) {
172:             $channelPrice = (string) $item->price;
173:             $channelListId = (int) $item->price_list_id;
174:             $channelSource = $channel->value;
175:         } elseif ($variant->retail_price === null) {
176:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
177:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
178:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
179:         } else {
180:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
181:             $channelPrice = $this->basePrice($variant, $channel);
182:             $channelListId = null;
183:             $channelSource = 'base_price';
184:         }
185: 
186:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
187:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
188:         if ($group !== null && (float) $group->discount_percentage > 0) {
189:             return $this->formatResponse(
190:                 (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
191:                 'customer_group_discount',
192:                 $channelListId,
193:                 $variant,
194:                 $channel,
195:             );
196:         }
197: 
198:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
199:     }
200: 
201:     /**
202:      * سلم شرائح الكميات الساري لهذا العميل على المتغير: نقاط التحول هي كل
203:      * قيم min_qty في القوائم المؤهلة له (خاصة/مجموعة/قناة/قطاعي احتياطي)،
204:      * وسعر كل شريحة هو ناتج resolve نفسه عند حدّها الأدنى — فالسلم مطابق
205:      * دائمًا لما سيُحصَّل فعليًا عند تلك الكمية.
206:      *
207:      * @return list<array{min_qty: float, unit_price: float}>
208:      */
209:     public function tiersFor(ProductVariant $variant, Customer $customer, ?array $ctx = null): array
210:     {
211:         $now = Carbon::now();
212:         // F17: reuse the preloaded per-customer context when available.
213:         $ctx ??= $this->contextFor($customer);
214:         $channel = $ctx['channel'];
215:         $eligible = $ctx['eligible'];
216:         $groupId = $ctx['group']?->id;
217: 
218:         $breakpoints = isset($ctx['items'])
219:             ? ($ctx['items'][$variant->id] ?? collect())->pluck('min_qty')->map(fn ($v) => (float) $v)
220:             : $this->eligibleItems($variant, PHP_FLOAT_MAX, null, $now)
221:                 ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
222:                     $q->where('price_lists.type', $channel->value)
223:                         ->orWhere('price_lists.type', PriceListType::Retail->value);
224:                     if ($eligible) {
225:                         $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
226:                             ->where('price_lists.customer_id', $customer->id));
227:                     }
228:                     if ($groupId !== null) {
229:                         $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
230:                             ->where('price_lists.customer_group_id', $groupId));
231:                     }
232:                 })
233:                 ->pluck('price_list_items.min_qty')
234:                 ->map(fn ($v) => (float) $v)
235:                 ->unique()
236:                 ->sort()
237:                 ->values();
238: 
239:         $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();
240: 
241:         return $points
242:             ->map(fn (float $minQty) => [
243:                 'min_qty' => $minQty,
244:                 'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty), null, $ctx)['unit_price'],
245:             ])
246:             ->values()
247:             ->all();
248:     }
249: 
250:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
251:     private function channelFor(?Customer $customer): PriceListType
252:     {
253:         if ($customer !== null
254:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
255:             && $customer->status === CustomerStatus::Approved) {
256:             return PriceListType::from($customer->type->value);
257:         }
258: 
259:         return PriceListType::Retail;
260:     }
261: 
262:     private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
263:     {
264:         return $variant->retail_price === null ? null : $variant->base_price;
265:     }
266: 
267:     private function discountFactor(string $percentage): string
268:     {
269:         return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
270:     }
271: 
272:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
273:     private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now, ?array $variantIds = null): Builder
274:     {
275:         return PriceListItem::query()
276:             ->select('price_list_items.*')
277:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
278:             ->where('price_lists.is_active', true)
279:             ->when($variant !== null,
280:                 fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
281:                 fn ($q) => $variantIds !== null
282:                     ? $q->whereIn('price_list_items.product_variant_id', $variantIds)
283:                     : $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
284:             ->where('price_list_items.min_qty', '<=', $qty)
285:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
286:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
287:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
288:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
289:             ->where(function ($q) use ($branchId): void {
290:                 $q->whereNull('price_lists.branch_id');
291:                 if ($branchId !== null) {
292:                     $q->orWhere('price_lists.branch_id', $branchId);
293:                 }
294:             });
295:     }
296: 
297:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
298:     private function ordered(Builder $query): Builder
299:     {
300:         return $query
301:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
302:             ->orderByDesc('price_list_items.min_qty')
303:             ->orderByDesc('price_lists.priority')
304:             ->orderBy('price_list_items.price')->orderBy('price_list_items.id');
305:     }
306: 
307:     /**
308:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
309:      */
310:     private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
311:     {
312:         return [
313:             'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
314:             'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
315:             'source' => $source,
316:             'price_list_id' => $priceListId,
317:         ];
318:     }
319: }

