 1: import { useEffect, useRef } from 'react';
 2: import { authEndpoints, resolveServiceUrl } from '@alfarid/api-client';
 3: import { useAuthStore } from '../../stores/auth.store';
 4: import { toStaffUser } from '../../stores/mappers';
 5: 
 6: const WEB_URL = resolveServiceUrl((import.meta.env.VITE_WEB_URL as string | undefined) ?? 'http://localhost:3000');
 7: 
 8: export default function AuthCallbackPage() {
 9:   const login = useAuthStore((s) => s.login);
10:   const ran = useRef(false); // React StrictMode بيشغّل الـ effect مرتين، والكود بيُستخدم مرة واحدة بس
11: 
12:   useEffect(() => {
13:     if (ran.current) return;
14:     ran.current = true;
15:     // M7: الكود يصل في الـ fragment (لا يُرسل للخادم ولا في الـ Referer) —
16:     // يُمسح فورًا من الشريط؛ روابط الـ query القديمة لم تعد مقبولة.
17:     const fromHash = new URLSearchParams(window.location.hash.replace(/^#/, '')).get('code');
18:     const code = fromHash;
19:     window.history.replaceState(null, '', window.location.pathname);
20:     if (!code) {
21:       window.location.replace(`${WEB_URL}/auth/login?error=handoff`);
22:       return;
23:     }
24:     authEndpoints
25:       .exchangeHandoff(code)
26:       .then(async (res) => {
27:         // H1: أبطل التوكن السابق قبل تفعيل الجديد، وبعميل خام بلا interceptors
28:         // حتى لا يستبدل الـ interceptor الـ Authorization الصريح بالتوكن الجديد
29:         // فيحذف الخادم التوكن الجديد بدل القديم.
30:         const prev = localStorage.getItem('backoffice_token');
31:         if (prev && prev !== res.token) {
32:           const baseURL =
33:             resolveServiceUrl((import.meta.env.VITE_API_URL as string | undefined) ?? 'http://localhost:8000');
34:           const ctrl = new AbortController();
35:           const timer = setTimeout(() => ctrl.abort(), 10000);
36:           try {
37:             await fetch(`${baseURL}/api/v1/admin/auth/logout`, {
38:               method: 'POST',
39:               headers: { Authorization: `Bearer ${prev}`, 'Content-Type': 'application/json' },
40:               signal: ctrl.signal,
41:             });
42:           } catch {
43:             // best-effort: التوكن القديم قد يكون منتهيًا أصلًا
44:           } finally {
45:             clearTimeout(timer);
46:           }
47:         }
48:         login(res.token, toStaffUser(res.data));
49:         window.location.replace(res.redirect.path);
50:       })
51:       .catch(() => window.location.replace(`${WEB_URL}/auth/login?error=handoff`));
52:   }, []);
53: 
54:   return <div style={{ padding: 40, textAlign: 'center' }}>جارٍ تسجيل الدخول…</div>;
55: }

 1: import { create } from 'zustand';
 2: import { authEndpoints, setAuthToken, setUnauthorizedHandler, resolveServiceUrl } from '@alfarid/api-client';
 3: import { toStaffUser } from './mappers';
 4: 
 5: export interface StaffUser {
 6:   id: number;
 7:   name: string;
 8:   email: string;
 9:   roles: string[];
10:   permissions: string[];
11:   branch_id?: number | null;
12: }
13: 
14: interface AuthState {
15:   user: StaffUser | null;
16:   token: string | null;
17:   isAuthenticated: boolean;
18:   login: (token: string, user: StaffUser) => void;
19:   setUser: (user: StaffUser) => void;
20:   logout: () => void;
21:   logoutRemote: () => Promise<void>;
22:   bootstrap: () => Promise<void>;
23: }
24: 
25: const WEB_URL = resolveServiceUrl((import.meta.env.VITE_WEB_URL as string | undefined) ?? 'http://localhost:3000');
26: 
27: export const useAuthStore = create<AuthState>((set, get) => {
28:   const initialToken = typeof localStorage !== 'undefined' ? localStorage.getItem('backoffice_token') : null;
29:   if (initialToken) {
30:     setAuthToken(initialToken);
31:   }
32: 
33:   // Register 401 handler to redirect to the unified web login
34:   setUnauthorizedHandler(() => {
35:     if (typeof localStorage !== 'undefined') {
36:       localStorage.removeItem('backoffice_token');
37:     }
38:     setAuthToken(null);
39:     set({ user: null, token: null, isAuthenticated: false });
40:     if (typeof window !== 'undefined' && !window.location.pathname.includes('/login')) {
41:       window.location.href = `${WEB_URL}/auth/login`;
42:     }
43:   });
44: 
45:   return {
46:     user: null,
47:     token: initialToken,
48:     isAuthenticated: !!initialToken,
49:     login: (token, user) => {
50:       localStorage.setItem('backoffice_token', token);
51:       setAuthToken(token);
52:       set({ token, user, isAuthenticated: true });
53:     },
54:     setUser: (user) => set({ user }),
55:     logout: () => {
56:       localStorage.removeItem('backoffice_token');
57:       setAuthToken(null);
58:       set({ user: null, token: null, isAuthenticated: false });
59:     },
60:     logoutRemote: async () => {
61:       try {
62:         await authEndpoints.staffLogout();
63:       } catch {
64:         // التوكن منتهي أو ملغي — نكمل تسجيل الخروج المحلي على أي حال
65:       }
66:       get().logout();
67:       window.location.href = `${WEB_URL}/auth/login`;
68:     },
69:     bootstrap: async () => {
70:       if (!get().token) return;
71:       const token = get().token;
72:       const u = await authEndpoints.staffMe(); // لو رجع 401 الـ handler هيحوّل لوحده
73:       if (get().token !== token) return;
74:       get().setUser(toStaffUser(u));
75:     },
76:   };
77: });
78: 
79: // Reload into the latest account instead of keeping stale identity/permissions in memory.
80: if (typeof window !== 'undefined') {
81:   window.addEventListener('storage', (event) => {
82:     if (window.location.pathname === '/auth/session') return;
83:     if (event.storageArea === localStorage && (event.key === 'backoffice_token' || event.key === null)
84:       && localStorage.getItem('backoffice_token') !== useAuthStore.getState().token) {
85:       window.location.reload();
86:     }
87:   });
88: }

  1: import { authEndpoints, createApiClient, defaultApiClient, resolveServiceUrl } from '@alfarid/api-client';
  2: import { useAuthStore } from '@/store/auth.store';
  3: 
  4: const CART_KEY = 'cart_session';
  5: 
  6: async function revokePreviousSession(nextToken?: string | null) {
  7:   const previous = useAuthStore.getState().token;
  8:   if (!previous || previous === nextToken) return;
  9:   try {
 10:     await createApiClient({ getToken: () => previous, onUnauthorized: () => {} })
 11:       .post('/api/v1/auth/logout', {}, { timeout: 10000 });
 12:   } catch { /* The previous session may already have expired. */ }
 13: }
 14: 
 15: export async function loginUnified(login: string, password: string, redirect?: string | null) {
 16:   const res = await authEndpoints.login({ login, password, redirect: redirect ?? undefined },
 17:     typeof window !== 'undefined' ? localStorage.getItem(CART_KEY) : null);
 18:   await revokePreviousSession(res.token);
 19: 
 20:   if (res.redirect.app === 'backoffice') {
 21:     // M9: جلسة عميل/مورد قائمة توكنها يبقى صالحًا 24 ساعة بعد clear المحلي —
 22:     // أبطلها في الخادم أولًا (best-effort) قبل مسح الجلسة المحلية.
 23:     useAuthStore.getState().clear();
 24:     // M7: الكود في الـ fragment لا في الـ query — الـ fragment لا يُرسل
 25:     // للخادم ولا يظهر في الـ Referer أو سجلات nginx.
 26:     const url = `${resolveServiceUrl(process.env.NEXT_PUBLIC_BACKOFFICE_URL ?? 'http://localhost:5173')}/auth/callback#code=${encodeURIComponent(res.handoff_code!)}`;
 27:     window.location.assign(url);
 28:     return null;
 29:   }
 30: 
 31:   useAuthStore.getState().setSession({
 32:     token: res.token!, actorType: res.actor.type as 'customer' | 'supplier',
 33:     destination: res.actor.subtype, home: res.redirect.path, user: res.data,
 34:   });
 35:   // M10: الدمج قد يفشل في الخادم (cart_merged=false) — أبقِ cart_session
 36:   // ليُعاد دمجه لاحقًا بدل حذفه مع توكن يتيم جديد.
 37:   if (res.actor.type === 'customer' && res.cart_merged !== false) localStorage.removeItem(CART_KEY);
 38:   return res.redirect.path;
 39: }
 40: 
 41: export async function logoutWeb() {
 42:   try { await authEndpoints.logout(); } finally { useAuthStore.getState().clear(); window.location.href = '/auth/login'; }
 43: }
 44: 
 45: export interface RegistrationInput {
 46:   name: string;
 47:   phone: string;
 48:   email?: string;
 49:   password: string;
 50:   phone_verification_token?: string;
 51:   company_name?: string;
 52:   tax_number?: string;
 53:   commercial_register?: string;
 54: }
 55: 
 56: interface RegistrationResponse {
 57:   token: string;
 58:   data: Record<string, unknown>;
 59: }
 60: 
 61: export async function registerWeb(input: RegistrationInput, wholesale: boolean, documents: File[] = []) {
 62:   let body: RegistrationInput | FormData = input;
 63:   if (wholesale) {
 64:     body = new FormData();
 65:     Object.entries(input).forEach(([key, value]) => {
 66:       if (value !== undefined && value !== '') (body as FormData).append(key, value);
 67:     });
 68:     documents.forEach((file) => (body as FormData).append('documents[]', file));
 69:   }
 70:   const session = localStorage.getItem(CART_KEY);
 71:   const response = await defaultApiClient.post<RegistrationResponse>(
 72:     wholesale ? '/api/v1/wholesale/auth/register' : '/api/v1/store/auth/register', body,
 73:     { headers: {
 74:       ...(wholesale ? { 'Content-Type': 'multipart/form-data' } : {}),
 75:       ...(!wholesale && session ? { 'X-Cart-Session': session } : {}),
 76:     } },
 77:   );
 78:   const home = wholesale ? '/wholesale/application-status' : '/';
 79:   await revokePreviousSession(response.data.token);
 80:   useAuthStore.getState().setSession({
 81:     token: response.data.token, actorType: 'customer',
 82:     destination: wholesale ? 'wholesale_pending' : 'retail', home, user: response.data.data,
 83:   });
 84:   if (!wholesale) localStorage.removeItem(CART_KEY);
 85:   return home;
 86: }
 87: 
 88: function recoveryIdentifier(login: string) {
 89:   const value = login.trim();
 90:   return value.includes('@') ? { email: value } : { phone: value };
 91: }
 92: 
 93: export async function requestPasswordReset(login: string) {
 94:   const response = await defaultApiClient.post<{ message: string }>(
 95:     '/api/v1/store/auth/forgot-password', recoveryIdentifier(login),
 96:   );
 97:   return response.data;
 98: }
 99: 
100: export async function resetWebPassword(login: string, token: string, password: string, confirmation: string) {
101:   await defaultApiClient.post('/api/v1/store/auth/reset-password', {
102:     ...recoveryIdentifier(login), token: token.trim(), password, password_confirmation: confirmation,
103:   });
104: }
105: 
106: export async function sendPhoneVerification(phone: string) {
107:   const response = await defaultApiClient.post<{ message: string }>('/api/v1/store/auth/phone-verification/send', { phone });
108:   return response.data;
109: }
110: 
111: export async function verifyPhone(phone: string, code: string) {
112:   const response = await defaultApiClient.post<{ phone_verification_token: string }>(
113:     '/api/v1/store/auth/phone-verification/verify', { phone, code },
114:   );
115:   return response.data.phone_verification_token;
116: }

