 5: namespace App\Http\Requests\Store\Checkout;
 6: 
 7: use App\Enums\CustomerStatus;
 8: use App\Enums\CustomerType;
 9: use App\Models\Customer;
10: use Illuminate\Foundation\Http\FormRequest;
11: use Illuminate\Validation\Rule;
12: 
13: class CheckoutRequest extends FormRequest
14: {
15:     public function authorize(): bool
16:     {
17:         return true;
18:     }
19: 
20:     /** @return array<string, mixed> */
21:     public function rules(): array
22:     {
23:         return [
24:             'recipient_name' => ['nullable', 'string', 'max:255'],
25:             // صيغة هاتف تحمل أرقامًا (M3): مدخل بلا أرقام كان يوحّد إلى هوية
26:             // مشتركة 'guest:' فيفسح نطاق idempotency عامًا وتتبعًا خاطئًا
27:             'recipient_phone' => ['nullable', 'string', 'max:50', 'regex:/^[0-9+][0-9\s().\-]{6,}$/'],
28:             'recipient_email' => ['nullable', 'email', 'max:255'],
29:             'city_id' => ['required', 'integer', 'exists:cities,id'],
30:             'shipping_address_line' => ['required', 'string', 'max:500'],
31:             'shipping_notes' => ['nullable', 'string', 'max:500'],
32:             // الإجمالي الذي رآه العميل — يُقارن بالمحسوب لمنع تغيّر السعر الصامت (M6)
33:             'expected_total' => ['nullable', 'numeric', 'min:0'],
34:             // طرق الدفع من الإعدادات فقط — طريقة بلا بوابة مربوطة لا تُقبل (H9)
35:             'payment_method' => ['required', Rule::in($this->allowedPaymentMethods())],
36:         ];
37:     }
38: 
39:     /** @return array<int, string> */
40:     private function allowedPaymentMethods(): array
41:     {
42:         $configured = array_values(array_filter((array) config('store.payment_methods', ['cod'])));
43:         $walletEnabled = in_array('wallet', $configured, true);
44:         $methods = array_values(array_filter($configured, fn ($method) => $method !== 'wallet'));
45: 
46:         // المحفظة من الإعدادات فقط، ولعملاء معتمدين. إيقافها يتم بحذفها من STORE_PAYMENT_METHODS.
47:         $user = auth('sanctum')->user();
48:         if ($walletEnabled && $user instanceof Customer && $user->status === CustomerStatus::Approved) {
49:             $methods[] = 'wallet';
50:         }
51:         if ($user instanceof Customer
52:             && $user->status === CustomerStatus::Approved
53:             && in_array($user->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
54:             $methods[] = 'credit';
55:         }
56: 
57:         return array_values(array_unique($methods));
58:     }
59: }

