  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Jobs\SendCustomerPasswordReset;
 11: use App\Models\Customer;
 12: use App\Models\CustomerAuditLog;
 13: use App\Notifications\Channels\CustomerSmsChannel;
 14: use App\Notifications\CustomerPasswordReset;
 15: use Illuminate\Support\Facades\DB;
 16: use Illuminate\Support\Facades\Hash;
 17: use Illuminate\Support\Str;
 18: 
 19: /**
 20:  * دورة مصادقة العملاء (متجر قطاعي + جملة): التسجيل، الدخول، واستعادة كلمة المرور.
 21:  * القيم الحساسة (type/status) تُفرض هنا برمجيًا ولا تأتي من الطلب أبدًا.
 22:  */
 23: class CustomerAuthService
 24: {
 25:     public static function dummyHash(): string
 26:     {
 27:         if (config('hashing.driver', 'bcrypt') === 'bcrypt') {
 28:             return sprintf('$2y$%02d$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.', (int) config('hashing.bcrypt.rounds', 12));
 29:         }
 30:         static $hashes = [];
 31:         $key = json_encode(config('hashing'));
 32: 
 33:         return $hashes[$key] ??= Hash::make('not-a-customer-password');
 34:     }
 35: 
 36:     private function identifierKey(string $identifier): string
 37:     {
 38:         return hash_hmac('sha256', $identifier, (string) config('app.key'));
 39:     }
 40: 
 41:     /** تسجيل متجر قطاعي: نوع retail وحالة approved دائمًا. */
 42:     public function registerRetail(array $data): Customer
 43:     {
 44:         $verified = app(CustomerPhoneVerificationService::class)->consume($data);
 45: 
 46:         $customer = Customer::query()->create([
 47:             'name' => $data['name'],
 48:             'email' => $data['email'] ?? null,
 49:             'phone' => $data['phone'],
 50:             'password' => $data['password'],
 51:             'type' => CustomerType::Retail,
 52:             'status' => CustomerStatus::Approved,
 53:             'phone_verified_at' => $verified ? now() : null,
 54:             'approved_at' => now(),
 55:         ]);
 56:         CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'store']);
 57: 
 58:         return $customer;
 59:     }
 60: 
 61:     /**
 62:      * دخول بالهاتف أو البريد. الحساب الموقوف يُرفض 403 بسبب الإيقاف؛
 63:      * أي حالة أخرى (بما فيها pending/rejected للجملة) تستطيع الدخول —
 64:      * بوابات النوع والحالة (wholesale.approved) تحكم ما بعد الدخول.
 65:      */
 66:     public function login(string $identifier, string $password): Customer
 67:     {
 68:         $emailLogin = str_contains($identifier, '@');
 69:         $identifier = $emailLogin ? mb_strtolower(trim($identifier)) : Customer::normalizePhone($identifier);
 70:         $dummyHash = self::dummyHash();
 71:         $customer = Customer::query()
 72:             ->when($emailLogin, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [$identifier]), fn ($q) => $q->where('phone', $identifier))
 73:             ->first();
 74: 
 75:         $validPassword = Hash::check($password, $customer?->password ?? $dummyHash);
 76:         if ($customer === null || ! $validPassword) {
 77:             // M11: لا تكتب صف audit لمعرّف غير موجود (هجمات stuffing تتحول لكتابات
 78:             // غير محدودة)، واكتفِ بسجل info مع sampling. المعرّف يُحمى بـ HMAC
 79:             // بمفتاح التطبيق لأن sha256 وحده قابل للعكس على مساحة الهواتف.
 80:             if ($customer === null) {
 81:                 if (random_int(1, 10) === 1) {
 82:                     logger()->info('customer.login_failed', ['identifier_key' => $this->identifierKey($identifier)]);
 83:                 }
 84:             } else {
 85:                 defer(fn () => CustomerAuditLog::record($customer, 'login_failed', null, ['identifier_key' => $this->identifierKey($identifier)]))->always();
 86:             }
 87:             throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 88:         }
 89: 
 90:         if ($customer->status === CustomerStatus::Suspended) {
 91:             CustomerAuditLog::record($customer, 'login_failed', null, ['reason' => 'suspended']);
 92:             throw new BusinessException(
 93:                 'هذا الحساب موقوف.'.($customer->suspension_reason ? ' السبب: '.$customer->suspension_reason : ''),
 94:                 ['suspension_reason' => $customer->suspension_reason],
 95:                 403,
 96:             );
 97:         }
 98: 
 99:         if (Hash::needsRehash($customer->password)) {
100:             $customer->forceFill(['password' => $password])->save();
101:         }
102:         CustomerAuditLog::record($customer, 'login_succeeded', null);
103: 
104:         return $customer;
105:     }
106: 
107:     /**
108:      * استعادة كلمة المرور: رمز في password_reset_tokens + إشعار للعميل.
109:      * الرد واحد دائمًا (نجاح ظاهري) حتى لا يُستدل على وجود الحساب.
110:      */
111:     public function forgotPassword(?string $email, ?string $phone): void
112:     {
113:         if (! $email && ! $phone) {
114:             return;
115:         }
116: 
117:         SendCustomerPasswordReset::dispatch($email, $phone)
118:             ->onConnection(config('auth.customer_password_reset.connection', 'database'));
119:     }
120: 
121:     public function sendPasswordReset(?string $email, ?string $phone): void
122:     {
123:         if (! $email && ! $phone) {
124:             return;
125:         }
126: 
127:         $customer = Customer::query()
128:             ->when($email, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($email))]),
129:                 fn ($q) => $q->where('phone', Customer::normalizePhone($phone)))
130:             ->first();
131: 
132:         if ($customer === null || $customer->status === CustomerStatus::Suspended) {
133:             return;
134:         }
135: 
136:         $plainToken = Str::random(64);
137:         $key = $customer->getEmailForPasswordReset();
138: 
139:         $stored = DB::transaction(function () use ($customer, $key, $plainToken, $email): bool {
140:             $current = Customer::query()->lockForUpdate()->find($customer->id);
141:             if ($current === null || $current->status === CustomerStatus::Suspended) {
142:                 return false;
143:             }
144:             if ($email && ($current->email_verified_at === null || $current->email !== mb_strtolower(trim($email)))) {
145:                 return false;
146:             }
147:             $existing = DB::table('password_reset_tokens')->where('email', $key)->first();
148:             if ($existing && now()->subSeconds(60)->lt($existing->created_at)) {
149:                 return false;
150:             }
151:             if (! app(CustomerMessageBudget::class)->claim('reset:customer:'.$customer->id, sms: ! $email)) {
152:                 return false;
153:             }
154:             DB::table('password_reset_tokens')->updateOrInsert(
155:                 ['email' => $key], ['token' => hash('sha256', $plainToken), 'created_at' => now()],
156:             );
157: 
158:             return true;
159:         });
160:         if (! $stored) {
161:             return;
162:         }
163: 
164:         try {
165:             $customer->notify(new CustomerPasswordReset($plainToken, $email ? 'mail' : CustomerSmsChannel::class));
166:         } catch (\Throwable $exception) {
167:             report($exception);
168:         }
169:     }
170: 
171:     public function resetPassword(array $data): void
172:     {
173:         $dummyHash = self::dummyHash();
174:         DB::transaction(function () use ($data, $dummyHash): void {
175:             $customer = Customer::query()
176:                 ->when(! empty($data['email']), fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))]),
177:                     fn ($q) => $q->where('phone', $data['phone']))
178:                 ->lockForUpdate()->first();
179:             $key = $customer?->getEmailForPasswordReset();
180:             $row = DB::table('password_reset_tokens')->where('email', $key)->lockForUpdate()->first();
181:             $storedToken = $row?->token ?? '';
182:             $validToken = strlen($storedToken) === 64 ? hash_equals($storedToken, hash('sha256', $data['token']))
183:                 : Hash::check($data['token'], $storedToken ?: $dummyHash);
184:             if ($customer === null || $customer->status === CustomerStatus::Suspended || $row === null
185:                 || $row->created_at === null || now()->subMinutes(60)->gte($row->created_at)
186:                 || now()->lt($row->created_at) || ! $validToken) {
187:                 throw new BusinessException('رمز الاستعادة غير صالح أو انتهت صلاحيته.');
188:             }
189:             $customer->forceFill(['password' => $data['password'], 'remember_token' => Str::random(60)])->save();
190:             $customer->tokens()->delete();
191:             DB::table('password_reset_tokens')->where('email', $key)->delete();
192:             CustomerAuditLog::record($customer, 'password_reset', null);
193:         });
194:     }
195: 
196:     /** إصدار توكن Sanctum باسم القناة (store-token / wholesale-token). */
197:     public function issueToken(Customer $customer, string $name): string
198:     {
199:         return DB::transaction(function () use ($customer, $name): string {
200:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
201:             if ($customer->status === CustomerStatus::Suspended) {
202:                 throw new BusinessException('هذا الحساب موقوف.', [], 403);
203:             }
204: 
205:             $expiry = config('sanctum.expiration');
206:             $customer->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
207:                 ->when($expiry, fn ($q) => $q->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
208:             $limit = max(1, (int) config('auth.customer_max_tokens', 10));
209:             $old = $customer->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
210:             if ($old->isNotEmpty()) {
211:                 $customer->tokens()->whereIn('id', $old)->delete();
212:             }
213: 
214:             $token = $customer->createToken($name);
215:             CustomerAuditLog::record($customer, 'token_issued', null, ['token_id' => $token->accessToken->id, 'channel' => $name]);
216: 
217:             return $token->plainTextToken;
218:         });
219:     }
220: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\ProductStatus;
  9: use App\Enums\SalesChannel;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Banner;
 12: use App\Models\Category;
 13: use App\Models\Customer;
 14: use App\Models\Product;
 15: use App\Models\ProductVariant;
 16: use App\Models\StockLevel;
 17: use Illuminate\Database\Eloquent\Builder;
 18: use Illuminate\Database\Eloquent\Collection;
 19: use Illuminate\Support\Facades\DB;
 20: 
 21: /**
 22:  * كتالوج المتجر للقراءة: استعلامات التصفح والفلترة وحساب المتاح أونلاين.
 23:  * المتاح أونلاين = مجموع available (on_hand − reserved − damaged) في الفروع
 24:  * النشطة فقط، بحساب SQL مجمّع (بلا تحميل صفوف في الذاكرة).
 25:  * «منتج نشط» في المتجر = منشور (published).
 26:  */
 27: class StoreCatalogService
 28: {
 29:     public function __construct(private readonly PricingService $pricing) {}
 30: 
 31:     // ------------------------------------------------------------------ متاح
 32: 
 33:     /** إرفاق store_available بأي استعلام منتجات: مجموع متاح كل متغيراته في الفروع النشطة. */
 34:     public function withStoreAvailability(Builder $query): Builder
 35:     {
 36:         $sub = DB::table('stock_levels')
 37:             ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 38:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 39:             ->where('branches.is_active', true)
 40:             ->where('product_variants.is_active', true)
 41:             ->whereNull('product_variants.deleted_at')
 42:             ->whereColumn('product_variants.product_id', 'products.id')
 43:             ->selectRaw('COALESCE(SUM(stock_levels.available), 0)');
 44: 
 45:         return $query->select('products.*')->selectSub($sub, 'store_available');
 46:     }
 47: 
 48:     /**
 49:      * خريطة متاح لمتغيرات بعينها في استعلام واحد مجمّع.
 50:      *
 51:      * @param  list<int>  $variantIds
 52:      * @return array<int, float>
 53:      */
 54:     public function availabilityMap(array $variantIds): array
 55:     {
 56:         if ($variantIds === []) {
 57:             return [];
 58:         }
 59: 
 60:         return StockLevel::query()
 61:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 62:             ->where('branches.is_active', true)
 63:             ->whereIn('stock_levels.product_variant_id', $variantIds)
 64:             ->groupBy('stock_levels.product_variant_id')
 65:             ->selectRaw('stock_levels.product_variant_id, COALESCE(SUM(stock_levels.available), 0) as total')
 66:             ->pluck('total', 'product_variant_id')
 67:             ->map(fn ($v) => (float) $v)
 68:             ->all();
 69:     }
 70: 
 71:     // ------------------------------------------------------------------ أساس
 72: 
 73:     /** استعلام المنتجات المنشورة بعلاقات البطاقة والمتاح المجمّع. */
 74:     public function publishedQuery(): Builder
 75:     {
 76:         $query = Product::query()
 77:             ->where('status', ProductStatus::Published)
 78:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
 79:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
 80:                 ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
 81:                     ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
 82:             ->with([
 83:                 'category', 'media',
 84:                 'variants' => fn ($q) => $this->pricing->withStorePrice($q->getQuery(), $this->customer())
 85:                     ->where('is_active', true)->with('media')->orderBy('sort_order')->orderBy('id'),
 86:             ]);
 87: 
 88:         return $this->withStoreAvailability($query);
 89:     }
 90: 
 91:     // ------------------------------------------------------------------ فلاتر
 92: 
 93:     /**
 94:      * تطبيق فلاتر قائمة المنتجات (ProductFilterRequest) على الاستعلام.
 95:      *
 96:      * @param  array<string, mixed>  $filters
 97:      */
 98:     public function applyFilters(Builder $query, array $filters): Builder
 99:     {
100:         if (! empty($filters['category'])) {
101:             $category = $this->resolveCategory($filters['category']);
102:             if ($category !== null) {
103:                 $query->whereIn('products.category_id', [$category->id, ...$category->descendantIds()]);
104:             } else {
105:                 $query->whereRaw('1 = 0'); // قسم غير موجود = نتيجة فارغة لا خطأ
106:             }
107:         }
108: 
109:         if (! empty($filters['color'])) {
110:             $color = $filters['color'];
111:             $query->whereHas('variants', fn ($q) => $q->where('is_active', true)
112:                 ->where(fn ($inner) => $inner
113:                     ->whereRaw('LOWER(color_name_en) = LOWER(?)', [$color])
114:                     ->orWhere('color_name_ar', $color)));
115:         }
116: 
117:         if (isset($filters['price_min']) || isset($filters['price_max']) || in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)) {
118:             $query->leftJoinLateral($this->minimumPriceQuery(), 'catalog_price');
119:             if (isset($filters['price_min'])) {
120:                 $query->where('catalog_price.minimum_price', '>=', $filters['price_min']);
121:             }
122:             if (isset($filters['price_max'])) {
123:                 $query->where('catalog_price.minimum_price', '<=', $filters['price_max']);
124:             }
125:         }
126: 
127:         // stock_levels_valid_balances enforces available >= 0 in PostgreSQL,
128:         // so a positive row is equivalent to a positive sum on the card.
129:         if (! empty($filters['in_stock'])) {
130:             $query->whereExists(fn ($sub) => $sub
131:                 ->select(DB::raw(1))
132:                 ->from('stock_levels')
133:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
134:                 ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
135:                 ->where('branches.is_active', true)
136:                 ->where('product_variants.is_active', true)
137:                 ->whereNull('product_variants.deleted_at')
138:                 ->whereColumn('product_variants.product_id', 'products.id')
139:                 ->where('stock_levels.available', '>', 0));
140:         }
141: 
142:         return $this->applySort($query, $filters['sort'] ?? 'newest');
143:     }
144: 
145:     private function applySort(Builder $query, string $sort): Builder
146:     {
147:         if (in_array($sort, ['price_asc', 'price_desc'], true)) {
148:             return $query->orderByRaw('catalog_price.minimum_price '.($sort === 'price_asc' ? 'ASC' : 'DESC').' NULLS LAST')
149:                 ->orderBy('products.id');
150:         }
151: 
152:         return match ($sort) {
153:             'best_selling' => $query->orderByDesc('products.sales_count')->orderByDesc('products.id'),
154:             default => $query->orderByDesc('products.created_at')->orderByDesc('products.id'),
155:         };
156:     }
157: 
158:     private function resolveCategory(int|string $value): ?Category
159:     {
160:         $category = Category::query()->where('is_active', true)->where('slug', $value)->first();
161: 
162:         return $category ?? (ctype_digit((string) $value) && strlen((string) $value) <= 18
163:             ? Category::query()->where('is_active', true)->find((int) $value) : null);
164:     }
165: 
166:     // ------------------------------------------------------------------ أسعار العرض
167: 
168:     /**
169:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
170:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
171:      *
172:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
173:      */
174:     public function displayPrice(Product $product, ?Customer $customer): ?array
175:     {
176:         $variants = $product->relationLoaded('variants')
177:             ? $product->variants
178:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
179: 
180:         $best = null;
181:         foreach ($variants as $variant) {
182:             try {
183:                 $resolved = $this->variantPrice($variant, $customer);
184:             } catch (BusinessException) {
185:                 continue;
186:             }
187: 
188:             $price = (float) $resolved['unit_price'];
189:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
190:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
191: 
192:             $display = [
193:                 'price' => $price,
194:                 'base_price' => (float) $resolved['base_price'],
195:                 'compare_at' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1 ? $basis : null,
196:                 'discount_percentage' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1
197:                     ? (int) round((1 - $price / $basis) * 100) : null,
198:                 'variant_id' => $variant->id,
199:             ];
200:             if ($best === null || $price < $best['price']) {
201:                 $best = $display;
202:             }
203:         }
204: 
205:         return $best;
206:     }
207: 
208:     public function customer(): ?Customer
209:     {
210:         $user = auth('sanctum')->user();
211: 
212:         return $user instanceof Customer && $user->status === CustomerStatus::Approved ? $user : null;
213:     }
214: 
215:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
216:     {
217:         if (! array_key_exists('store_price', $variant->getAttributes())) {
218:             return $this->pricing->resolve($variant, $customer, 1);
219:         }
220:         if ($variant->store_price === null) {
221:             throw new BusinessException('الصنف غير مُسعَّر.');
222:         }
223: 
224:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) ($variant->retail_price === null ? $variant->store_price : $variant->base_price)];
225:     }
226: 
227:     private function minimumPriceQuery(): \Illuminate\Database\Query\Builder
228:     {
229:         $variants = $this->pricing->withStorePrice(ProductVariant::query(), $this->customer())
230:             ->where('is_active', true);
231: 
232:         return DB::query()->fromSub($variants, 'priced_variants')
233:             ->selectRaw('MIN(priced_variants.store_price) AS minimum_price')
234:             ->whereColumn('priced_variants.product_id', 'products.id');
235:     }
236: 
237:     // ------------------------------------------------------------------ الرئيسية والتشابه
238: 
239:     /** معرّفات أقسام الصفحة الرئيسية (تُخزَّن مؤقتًا في المتحكم — الأسعار لا تُخزَّن أبدًا). */
240:     public function homeSectionIds(): array
241:     {
242:         $bannerIds = Banner::query()
243:             ->where('is_active', true)
244:             ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', now()))
245:             ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', now()))
246:             ->orderBy('sort_order')->orderBy('id')
247:             ->pluck('id')->all();
248: 
249:         $latest = $this->publishedQuery()->reorder()->orderByDesc('products.created_at')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
250:         $best = $this->publishedQuery()->reorder()->orderByDesc('products.sales_count')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
251: 
252:         $discounted = $this->publishedQuery()->reorder()
253:             ->where(fn ($q) => $q
254:                 ->whereHas('variants', fn ($v) => $v->where('is_active', true)
255:                     ->whereNotNull('retail_price')
256:                     ->whereNotNull('compare_at_price')
257:                     ->whereColumn('compare_at_price', '>', 'base_price'))
258:                 ->orWhereHas('variants', fn ($v) => $v->where('is_active', true)
259:                     ->whereExists(fn ($sub) => $sub->select(DB::raw(1))
260:                         ->from('price_list_items')
261:                         ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
262:                         ->whereColumn('price_list_items.product_variant_id', 'product_variants.id')
263:                         ->where('price_lists.is_active', true)
264:                         ->where('price_lists.type', 'retail')
265:                         ->whereNull('price_lists.branch_id')
266:                         ->where('price_list_items.min_qty', '<=', 1)
267:                         ->where(fn ($w) => $w->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', now()))
268:                         ->where(fn ($w) => $w->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', now()))
269:                         ->where(fn ($w) => $w->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', now()))
270:                         ->where(fn ($w) => $w->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', now()))
271:                         ->whereColumn('price_list_items.price', '<', 'product_variants.base_price'))))
272:             ->orderByDesc('products.sales_count')->orderByDesc('products.id')
273:             ->limit(12)->pluck('products.id')->all();
274: 
275:         return [
276:             'banner_ids' => $bannerIds,
277:             'latest_ids' => $latest,
278:             'best_seller_ids' => $best,
279:             'discounted_ids' => $discounted,
280:         ];
281:     }
282: 
283:     /**
284:      * منتجات مشابهة: نفس القسم الفرعي، والمتوفر أولًا.
285:      *
286:      * @return Collection<int, Product>
287:      */
288:     public function similar(Product $product): Collection
289:     {
290:         return $this->publishedQuery()
291:             ->where('products.id', '!=', $product->id)
292:             ->where(function ($q) use ($product): void {
293:                 $q->where('products.category_id', $product->category_id);
294:             })
295:             ->reorder()
296:             ->orderByRaw('CASE WHEN products.category_id = ? THEN 0 ELSE 1 END', [$product->category_id])
297:             ->withExists(['variants as has_store_stock' => fn ($q) => $q->where('is_active', true)
298:                 ->whereHas('stockLevels', fn ($stock) => $stock->where('available', '>', 0)
299:                     ->whereHas('branch', fn ($branch) => $branch->where('is_active', true)))])
300:             ->orderByDesc('has_store_stock')
301:             ->orderByDesc('products.sales_count')
302:             ->orderByDesc('products.id')
303:             ->limit(8)
304:             ->get();
305:     }
306: }

