 27:  */
 28: export function FinancialDashboard({ onLogout, categoriesPage, categoriesActive = false, onOpenCategories, onCloseCategories, catalogPage, catalogActive = null, catalogNav = [], onCloseCatalog } = {}) {
 29:   const hostRef = useRef(null);
