405:                     }}></div>{" "}<div className="h-full flex-1 rounded-r-full spending-hatched-track"></div>{" "}</div>{" "}<div className="flex items-center justify-between mt-3 text-[12px]">{" "}<div>{" "}<span className="font-bold" id="overview-spent-counter" style={{
