447:                       "color": "var(--text-secondary)"
448:                     }} onClick={() => showToast('Starting priority voice call...')}>{" "}<svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">{" "}<path strokeLinecap="round" strokeLinejoin="round" d="M3 5a2 2 0 012-2h2.6a1 1 0 01.95.68l1.1 3.3a1 1 0 01-.27 1.02l-1.5 1.5a12 12 0 005.6 5.6l1.5-1.5a1 1 0 011.02-.27l3.3 1.1a1 1 0 01.68.95V19a2 2 0 01-2 2h-1C9.82 21 3 14.18 3 6V5z" />{" "}</svg>{" "}</button>{" "}<button type="button" id="chat-more-btn" className="w-8 h-8 rounded-full v-subcard flex items-center justify-center hover:opacity-80 transition" style={{
449:                       "color": "var(--text-secondary)"
450:                     }} onClick={() => showToast('Conversation transcript saved')}>{" "}<svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">{" "}<circle cx="12" cy="5" r="1" /><circle cx="12" cy="12" r="1" /><circle cx="12" cy="19" r="1" />{" "}</svg>{" "}</button>{" "}</div>{" "}</div>{" "}<div className="py-4 flex-1 flex flex-col justify-start space-y-3 overflow-y-auto max-h-[320px]">{" "}<div className="self-center v-subcard px-3 py-1 rounded-full text-[10.5px] font-medium" style={{
451:                     "color": "var(--text-muted)"
452:                   }}>Today</div>{" "}<div id="chat-messages-feed" className="space-y-3">{renderActiveChat()}</div>{" "}</div>{" "}<form id="chat-send-form" className="v-subcard rounded-full px-4 py-2 flex items-center gap-3 mt-2" onSubmit={sendMessage}>{" "}<button type="button" id="chat-attach-btn" className="hover:opacity-75 transition" style={{
453:                     "color": "var(--text-muted)"
454:                   }} onClick={() => showToast('Select an invoice or receipt to attach')}>{" "}<svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">{" "}<path strokeLinecap="round" strokeLinejoin="round" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />{" "}</svg>{" "}</button>{" "}<input id="chat-composer-input" type="text" className="bg-transparent text-[12.5px] outline-none flex-1" style={{
455:                     "color": "var(--text-primary)"
456:                   }} value={composer} onChange={event => setComposer(event.target.value)} placeholder={`Message ${chat.name}...`} />{" "}<button type="button" id="chat-emoji-btn" className="hover:opacity-75 transition" style={{
457:                     "color": "var(--text-muted)"
458:                   }} onClick={() => {
459:                     setComposer(value => value + ' 👋');
460:                     shadowRoot?.getElementById('chat-composer-input')?.focus();
461:                   }}>{" "}<svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">{" "}<circle cx="12" cy="12" r="9" /><path strokeLinecap="round" d="M8.5 14.5s1.5 2 3.5 2 3.5-2 3.5-2M9 9.5h.01M15 9.5h.01" />{" "}</svg>{" "}</button>{" "}<button type="submit" className="w-8 h-8 rounded-full bg-[#e0491f] text-white flex items-center justify-center hover:opacity-90 transition shrink-0">{" "}<svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2.2" viewBox="0 0 24 24">{" "}<path strokeLinecap="round" strokeLinejoin="round" d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z" />{" "}</svg>{" "}</button>{" "}</form>{" "}</div>{" "}</div>{" "}</section></main>{" "}</div>{" "}</div>{" "}</div>{" "}<div id="v-modal-backdrop" className={'fixed inset-0 bg-black/40 backdrop-blur-xs z-50 items-center justify-center p-4 ' + (modal ? 'flex' : 'hidden')} onClick={event => {
462:     if (event.target === event.currentTarget) setModal(null);
463:   }}>{" "}<div className="v-card max-w-md w-full p-6 shadow-2xl">{" "}<div className="flex items-center justify-between mb-4">{" "}<h3 id="v-modal-title" className="font-display text-[18px] font-semibold" style={{
464:           "color": "var(--text-primary)"
465:         }}>{modalTitle}</h3>{" "}<button type="button" id="v-modal-close" className="w-8 h-8 rounded-full v-subcard flex items-center justify-center text-sm" style={{
466:           "color": "var(--text-secondary)"
467:         }} onClick={() => setModal(null)}>✕</button>{" "}</div>{" "}<div id="v-modal-body" className="space-y-3 text-[13px]">{renderModal()}</div>{" "}</div>{" "}</div>{" "}</></>, shadowRoot)}
468:   </div>;
469: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\CustomerDocumentStatus;
  8: use App\Enums\CustomerStatus;
  9: use App\Enums\CustomerType;
 10: use App\Http\Controllers\Controller;
 11: use App\Http\Requests\Admin\Customer\ApproveCustomerRequest;
 12: use App\Http\Requests\Admin\Customer\RejectCustomerRequest;
 13: use App\Http\Requests\Admin\Customer\StoreCustomerRequest;
 14: use App\Http\Requests\Admin\Customer\SuspendCustomerRequest;
 15: use App\Http\Requests\Admin\Customer\UpdateCustomerRequest;
 16: use App\Http\Resources\Admin\CustomerResource;
 17: use App\Models\Customer;
 18: use App\Models\CustomerAuditLog;
 19: use App\Models\CustomerDocument;
 20: use App\Services\CustomerManagementService;
 21: use Illuminate\Http\JsonResponse;
 22: use Illuminate\Http\Request;
 23: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 24: use Illuminate\Routing\Controllers\HasMiddleware;
 25: use Illuminate\Routing\Controllers\Middleware;
 26: use Illuminate\Support\Facades\Storage;
 27: use Illuminate\Validation\Rule;
 28: use Symfony\Component\HttpFoundation\StreamedResponse;
 29: 
 30: /** إدارة العملاء واعتماد حسابات الجملة في لوحة الإدارة. */
 31: class CustomerController extends Controller implements HasMiddleware
 32: {
 33:     public function __construct(private readonly CustomerManagementService $customers) {}
 34: 
 35:     public static function middleware(): array
 36:     {
 37:         return [
 38:             new Middleware('can:customers.view', only: ['index', 'show']),
 39:             new Middleware('can:customers.documents.view', only: ['downloadDocument', 'reviewDocument', 'storeDocument']),
 40:             new Middleware('can:customers.update', only: ['storeDocument']),
 41:             new Middleware('can:customers.create', only: ['store']),
 42:             new Middleware('can:customers.update', only: ['update']),
 43:             new Middleware('can:customers.delete', only: ['destroy', 'restore']),
 44:             new Middleware('can:customers.approve', only: ['approve', 'reject', 'suspend', 'reviewDocument']),
 45:         ];
 46:     }
 47: 
 48:     public function index(Request $request): AnonymousResourceCollection
 49:     {
 50:         $filters = $request->validate([
 51:             'type' => ['nullable', Rule::in(array_column(CustomerType::cases(), 'value'))],
 52:             'business_only' => ['nullable', 'boolean'],
 53:             'status' => ['nullable', Rule::in(array_column(CustomerStatus::cases(), 'value'))],
 54:             'customer_group_id' => ['nullable', 'integer', 'min:1'],
 55:             'search' => ['nullable', 'string', 'max:255'],
 56:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 57:             'trashed' => ['nullable', Rule::in(['only'])],
 58:         ]);
 59: 
 60:         return CustomerResource::collection($this->customers->paginate($filters));
 61:     }
 62: 
 63:     public function store(StoreCustomerRequest $request): JsonResponse
 64:     {
 65:         $customer = $this->customers->create($request->validated(), $request->user()->id);
 66: 
 67:         return CustomerResource::make($customer)
 68:             ->additional(['message' => 'تم إنشاء العميل بنجاح'])
 69:             ->response()
 70:             ->setStatusCode(201);
 71:     }
 72: 
 73:     public function show(Customer $customer): CustomerResource
 74:     {
 75:         return new CustomerResource($this->customers->find($customer->id));
 76:     }
 77: 
 78:     public function update(UpdateCustomerRequest $request, Customer $customer): CustomerResource
 79:     {
 80:         return new CustomerResource($this->customers->update($customer, $request->validated(), $request->user()->id));
 81:     }
 82: 
 83:     public function destroy(Request $request, Customer $customer): JsonResponse
 84:     {
 85:         $this->customers->delete($customer, $request->user()->id);
 86: 
 87:         return response()->json(['message' => 'تم حذف العميل بنجاح']);
 88:     }
 89: 
 90:     public function approve(ApproveCustomerRequest $request, Customer $customer): CustomerResource
 91:     {
 92:         $customer = $this->customers->approve($customer, $request->validated(), $request->user()->id);
 93: 
 94:         return (new CustomerResource($customer))->additional(['message' => 'تم اعتماد الحساب بنجاح']);
 95:     }
 96: 
 97:     public function reject(RejectCustomerRequest $request, Customer $customer): CustomerResource
 98:     {
 99:         $customer = $this->customers->reject($customer, $request->validated()['reason'], $request->user()->id);
100: 
101:         return (new CustomerResource($customer))->additional(['message' => 'تم رفض الحساب']);
102:     }
103: 
104:     public function suspend(SuspendCustomerRequest $request, Customer $customer): CustomerResource
105:     {
106:         $customer = $this->customers->suspend($customer, $request->validated()['reason'], $request->user()->id);
107: 
108:         return (new CustomerResource($customer))->additional(['message' => 'تم إيقاف الحساب وإنهاء جلساته']);
109:     }
110: 
111:     /** تنزيل مستند تحقق من التخزين الخاص (scoped: المستند تابع لهذا العميل حصرًا). */
112:     public function downloadDocument(Customer $customer, CustomerDocument $document): StreamedResponse
113:     {
114:         abort_unless(Storage::disk('r2')->exists($document->file_path), 404, 'المستند غير موجود.');
115:         CustomerAuditLog::record($customer, 'document_downloaded', request()->user()->id, ['document_id' => $document->id]);
116: 
117:         return Storage::disk('r2')->download($document->file_path, CustomerDocument::safeName($document->original_name));
118:     }
119: 
120:     public function restore(Request $request, Customer $customer): CustomerResource
121:     {
122:         return new CustomerResource($this->customers->restore($customer, $request->user()->id));
123:     }
124: 
125:     public function reviewDocument(Request $request, Customer $customer, CustomerDocument $document): JsonResponse
126:     {
127:         $data = $request->validate([
128:             'status' => ['required', Rule::enum(CustomerDocumentStatus::class)],
129:         ]);
130:         $document = $this->customers->reviewDocument($customer, $document, $data['status'], $request->user()->id);
131: 
132:         return response()->json(['data' => ['id' => $document->id, 'status' => $document->status]]);
133:     }
134: 
135:     public function storeDocument(Request $request, Customer $customer): JsonResponse
136:     {
137:         $request->validate(['document' => ['required', 'file', 'mimes:pdf,jpg,jpeg,png', 'max:5120']]);
138:         $document = $this->customers->uploadDocument($customer, $request->file('document'), (int) $request->user()->id);
139: 
140:         return response()->json(['data' => ['id' => $document->id, 'status' => $document->status]], 201);
141:     }
142: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Store;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Store\Checkout\CheckoutRequest;
 11: use App\Http\Requests\Store\Checkout\ShippingOptionsRequest;
 12: use App\Http\Resources\Store\OrderResource;
 13: use App\Models\Cart;
 14: use App\Models\City;
 15: use App\Models\Coupon;
 16: use App\Models\Customer;
 17: use App\Services\CartService;
 18: use App\Services\OrderService;
 19: use App\Services\ShippingQuoteService;
 20: use Illuminate\Http\JsonResponse;
 21: use Illuminate\Http\Request;
 22: 
 23: /** إتمام الشراء (زائر/مسجل) وخيارات الشحن. */
 24: class CheckoutController extends Controller
 25: {
 26:     public function __construct(
 27:         private readonly CartService $carts,
 28:         private readonly OrderService $orders,
 29:         private readonly ShippingQuoteService $shippingQuote,
 30:     ) {}
 31: 
 32:     public function shippingOptions(ShippingOptionsRequest $request): JsonResponse
 33:     {
 34:         $validated = $request->validated();
 35:         $city = City::query()->where('is_active', true)->findOrFail((int) $validated['city_id']);
 36:         [$customer, $cart] = $this->currentCart($request, create: false);
 37:         $totals = $this->carts->totals($cart, $customer);
 38: 
 39:         // نفس المدخلات التي سيحاسب عليها إتمام الشراء (M12 + F-29): البضاعة
 40:         // بعد خصم الكوبون، ورسوم COD حسب طريقة الدفع الفعلية لا cod دائمًا
 41:         $merchandise = max($totals['items_total'] - $totals['coupon_discount'], 0.0);
 42:         $cod = ($validated['payment_method'] ?? 'cod') === 'cod';
 43:         $quote = $this->shippingQuote->quoteForCity($city->id, $merchandise, $cod);
 44:         $rate = $quote['rate'];
 45: 
 46:         // كوبون الشحن المجاني يعفي تكلفة الشحن (لا رسوم COD) كما عند الشراء
 47:         $cost = $quote['cost'];
 48:         if ($totals['coupon_code'] !== null && $cart->coupon_id !== null
 49:             && Coupon::query()->whereKey($cart->coupon_id)->value('type') === 'free_shipping') {
 50:             $cost = 0.0;
 51:         }
 52: 
 53:         $days = $rate !== null ? "من {$rate->estimated_days_min} إلى {$rate->estimated_days_max} أيام عمل" : null;
 54: 
 55:         return response()->json(['data' => [
 56:             'city' => ['id' => $city->id, 'name_ar' => $city->name_ar, 'name_en' => $city->name_en],
 57:             'cart_total' => $totals['total'],
 58:             'options' => [[
 59:                 'key' => 'standard',
 60:                 'label' => 'شحن قياسي',
 61:                 'cost' => $cost,
 62:                 'cod_fee' => $quote['cod_fee'],
 63:                 'currency' => 'EGP',
 64:                 'estimated_days' => $days ?? 'من 2 إلى 4 أيام عمل',
 65:             ]],
 66:         ]]);
 67:     }
 68: 
 69:     public function store(CheckoutRequest $request): JsonResponse
 70:     {
 71:         [$customer, $cart] = $this->currentCart($request);
 72:         $data = $request->validated();
 73:         // هيدر اختياري: إعادة الإرسال بنفس المفتاح ترجع الطلب نفسه (F-13)
 74:         $idempotencyKey = $request->header('Idempotency-Key');
 75:         if (is_string($idempotencyKey) && $idempotencyKey !== '') {
 76:             $data['idempotency_key'] = $idempotencyKey;
 77:         }
 78: 
 79:         if ($customer === null && (empty($data['recipient_name']) || empty($data['recipient_phone']))) {
 80:             throw new BusinessException('بيانات المستلم (الاسم ورقم الهاتف) مطلوبة لإتمام الشراء كزائر.');
 81:         }
 82: 
 83:         $order = $this->orders->createFromCart($cart, $data, $customer);
 84: 
 85:         return response()->json([
 86:             'data' => OrderResource::make($order)->resolve($request),
 87:             // لا بوابة دفع مدمجة بعد: الدفع الإلكتروني يرجع رابطًا فارغًا حتى ربط البوابة
 88:             'payment_url' => null,
 89:             'message' => 'تم إنشاء الطلب بنجاح',
 90:         ], 201);
 91:     }
 92: 
 93:     /** @return array{0: ?Customer, 1: Cart} */
 94:     private function currentCart(Request $request, bool $create = true): array
 95:     {
 96:         $user = auth('sanctum')->user();
 97:         // عميل موقوف/مرفوض بتوكن صالح يُعامل كزائر (F-20): لا تُربط سلاته
 98:         // وطلباته بحساب غير نشط ولا تُمنح له أسعار/حدود العميل
 99:         $customer = $user instanceof Customer
100:             && ! in_array($user->status, [CustomerStatus::Suspended, CustomerStatus::Rejected], true)
101:                 ? $user
102:                 : null;
103:         $cart = $this->carts->resolveCart($customer, $request->header('X-Cart-Session'), $create);
104: 
105:         return [$customer, $cart];
106:     }
107: }

