  5: namespace App\Models;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Models\Concerns\SerializesAccountEmail;
 10: use Illuminate\Database\Eloquent\Attributes\Fillable;
 11: use Illuminate\Database\Eloquent\Attributes\Hidden;
 12: use Illuminate\Database\Eloquent\Factories\HasFactory;
 13: use Illuminate\Database\Eloquent\Relations\BelongsTo;
 14: use Illuminate\Database\Eloquent\Relations\HasMany;
 15: use Illuminate\Database\Eloquent\SoftDeletes;
 16: use Illuminate\Foundation\Auth\User as Authenticatable;
 17: use Illuminate\Notifications\Notifiable;
 18: use Laravel\Sanctum\HasApiTokens;
 19: 
 20: #[Fillable([
 21:     'name',
 22:     'email',
 23:     'phone',
 24:     'password',
 25:     'type',
 26:     'status',
 27:     'customer_group_id',
 28:     'company_name',
 29:     'tax_number',
 30:     'commercial_register',
 31:     'credit_limit',
 32:     'rejection_reason',
 33:     'suspension_reason',
 34:     'approved_at',
 35:     'approved_by',
 36:     'phone_verified_at',
 37: ])]
 38: #[Hidden(['password', 'remember_token'])]
 39: class Customer extends Authenticatable
 40: {
 41:     use HasApiTokens, HasFactory, Notifiable, SoftDeletes;
 42:     use SerializesAccountEmail;
 43: 
 44:     protected static function booted(): void
 45:     {
 46:         static::creating(function (Customer $customer): void {
 47:             if (! array_key_exists('status', $customer->getAttributes())) {
 48:                 $customer->status = in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
 49:                     ? CustomerStatus::Pending : CustomerStatus::Approved;
 50:             }
 51:         });
 52:     }
 53: 
 54:     public function customerGroup(): BelongsTo
 55:     {
 56:         return $this->belongsTo(CustomerGroup::class);
 57:     }
 58: 
 59:     public function getEmailForPasswordReset(): string
 60:     {
 61:         return 'customer:'.$this->getKey();
 62:     }
 63: 
 64:     public function setEmailAttribute(?string $email): void
 65:     {
 66:         $normalized = $email === null ? null : mb_strtolower(trim($email));
 67:         if (($this->attributes['email'] ?? null) !== $normalized) {
 68:             $this->attributes['email_verified_at'] = null;
 69:         }
 70:         $this->attributes['email'] = $normalized;
 71:     }
 72: 
 73:     public function setPhoneAttribute(string $phone): void
 74:     {
 75:         $this->attributes['phone'] = self::normalizePhone($phone);
 76:     }
 77: 
 78:     public static function normalizePhone(string $phone): string
 79:     {
 80:         $phone = strtr(trim($phone), array_combine(
 81:             preg_split('//u', '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', -1, PREG_SPLIT_NO_EMPTY),
 82:             str_split('01234567890123456789'),
 83:         ));
 84:         $phone = preg_replace('/[\s().-]+/u', '', $phone);
 85:         if (str_starts_with($phone, '+20')) {
 86:             return '0'.substr($phone, 3);
 87:         }
 88:         if (str_starts_with($phone, '0020')) {
 89:             return '0'.substr($phone, 4);
 90:         }
 91: 
 92:         return $phone;
 93:     }
 94: 
 95:     public function auditLogs(): HasMany
 96:     {
 97:         return $this->hasMany(CustomerAuditLog::class);
 98:     }
 99: 
100:     public function approver(): BelongsTo
101:     {
102:         return $this->belongsTo(User::class, 'approved_by');
103:     }
104: 
105:     public function documents(): HasMany
106:     {
107:         return $this->hasMany(CustomerDocument::class);
108:     }
109: 
110:     public function addresses(): HasMany
111:     {
112:         return $this->hasMany(CustomerAddress::class);
113:     }
114: 
115:     public function returnRequests(): HasMany
116:     {
117:         return $this->hasMany(ReturnRequest::class);
118:     }
119: 
120:     protected function casts(): array
121:     {
122:         return [
123:             'password' => 'hashed',
124:             'type' => CustomerType::class,
125:             'status' => CustomerStatus::class,
126:             'credit_limit' => 'decimal:2',
127:             'wallet_balance' => 'decimal:2',
128:             'approved_at' => 'datetime',
129:             'phone_verified_at' => 'datetime',
130:             'email_verified_at' => 'datetime',
131:         ];
132:     }
133: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerDocumentStatus;
  8: use App\Enums\CustomerDocumentType;
  9: use App\Enums\CustomerStatus;
 10: use App\Enums\CustomerType;
 11: use App\Events\WholesaleApplicationReviewed;
 12: use App\Exceptions\BusinessException;
 13: use App\Models\Customer;
 14: use App\Models\CustomerAuditLog;
 15: use App\Models\CustomerDocument;
 16: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 17: use Illuminate\Http\UploadedFile;
 18: use Illuminate\Support\Facades\DB;
 19: use Illuminate\Support\Str;
 20: 
 21: /**
 22:  * إدارة العملاء من لوحة الإدارة: CRUD + دورة اعتماد الجملة (اعتماد/رفض/إيقاف).
 23:  * الإيقاف يقتل كل جلسات العميل فورًا؛ الرفض يبقي توكنه حيًا حتى يطّلع على
 24:  * سبب الرفض ومستنداته المرفوضة عبر application-status.
 25:  */
 26: class CustomerManagementService
 27: {
 28:     public function paginate(array $filters): LengthAwarePaginator
 29:     {
 30:         return Customer::query()
 31:             ->with('customerGroup')
 32:             ->when(($filters['trashed'] ?? null) === 'only', fn ($q) => $q->onlyTrashed())
 33:             ->when($filters['business_only'] ?? false, fn ($q) => $q->whereIn('type', ['wholesale', 'distributor']))
 34:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 35:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 36:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 37:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('search_text', SearchTerm::pattern($v), caseSensitive: false))
 38:             ->orderByDesc('id')
 39:             ->paginate($filters['per_page'] ?? 15)->withQueryString();
 40:     }
 41: 
 42:     public function find(int $id): Customer
 43:     {
 44:         return Customer::query()
 45:             ->with(['customerGroup', 'documents', 'addresses.city', 'approver'])
 46:             ->findOrFail($id);
 47:     }
 48: 
 49:     public function create(array $data, ?int $actorId = null): Customer
 50:     {
 51:         $data['type'] ??= CustomerType::Retail->value;
 52:         $data['credit_limit'] ??= 0;
 53:         // الحالة الافتراضية حسب النوع ما لم تُرسل صراحة: قطاعي معتمد، جملة/موزع قيد المراجعة
 54:         $data['status'] ??= ($data['type'] ?? CustomerType::Retail->value) === CustomerType::Retail->value
 55:             ? CustomerStatus::Approved
 56:             : CustomerStatus::Pending;
 57: 
 58:         if ($data['status'] === CustomerStatus::Approved || $data['status'] === CustomerStatus::Approved->value) {
 59:             if ($data['type'] !== CustomerType::Retail->value) {
 60:                 throw new BusinessException('أنشئ حساب الجملة قيد المراجعة ثم استخدم مسار الاعتماد.');
 61:             }
 62:         }
 63: 
 64:         return DB::transaction(function () use ($data, $actorId): Customer {
 65:             if (in_array($data['status'], [CustomerStatus::Approved, CustomerStatus::Approved->value], true)) {
 66:                 $data['approved_at'] = now();
 67:                 $data['approved_by'] = $actorId;
 68:             }
 69:             $customer = Customer::query()->create($data);
 70:             CustomerAuditLog::record($customer, 'created', $actorId);
 71: 
 72:             return $customer->load('customerGroup');
 73:         });
 74:     }
 75: 
 76:     public function update(Customer $customer, array $data, ?int $actorId = null): Customer
 77:     {
 78:         return DB::transaction(function () use ($customer, $data, $actorId): Customer {
 79:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
 80:             if (isset($data['type']) && $data['type'] !== $customer->type->value) {
 81:                 throw new BusinessException('تغيير نوع الحساب المعتمد يتطلب استخدام مسار الاعتماد.');
 82:             }
 83:             if ($customer->status === CustomerStatus::Approved && $customer->type !== CustomerType::Retail) {
 84:                 foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
 85:                     if (array_key_exists($field, $data) && blank($data[$field])) {
 86:                         throw new BusinessException('لا يمكن مسح بيانات الجملة لحساب معتمد.', [$field => ['هذا الحقل مطلوب.']]);
 87:                     }
 88:                 }
 89:             }
 90:             $businessIdentityChanged = collect(['company_name', 'tax_number', 'commercial_register'])
 91:                 ->contains(fn ($field) => array_key_exists($field, $data) && $data[$field] !== $customer->{$field});
 92:             $credentialsChanged = array_key_exists('password', $data)
 93:                 || (isset($data['email']) && $data['email'] !== $customer->email)
 94:                 || (isset($data['phone']) && $data['phone'] !== $customer->phone)
 95:                 || (array_key_exists('email', $data) && $data['email'] === null && $customer->email !== null);
 96:             if (isset($data['phone']) && $data['phone'] !== $customer->phone) {
 97:                 $customer->forceFill(['phone_verified_at' => null]);
 98:             }
 99:             $customer->fill($data);
100:             if ($credentialsChanged) {
101:                 $customer->forceFill(['remember_token' => Str::random(60)]);
102:                 $customer->tokens()->delete();
103:                 DB::table('password_reset_tokens')->where('email', $customer->getEmailForPasswordReset())->delete();
104:             }
105:             $customer->save();
106:             CustomerAuditLog::record($customer, $credentialsChanged ? 'credentials_changed' : 'updated', $actorId, ['fields' => array_keys($data)]);
107:             if ($businessIdentityChanged) {
108:                 CustomerAuditLog::record($customer, 'business_identity_changed', $actorId, ['fields' => array_keys(array_intersect_key($data, array_flip(['company_name', 'tax_number', 'commercial_register'])))]);
109:             }
110: 
111:             return $customer->load('customerGroup');
112:         });
113:     }
114: 
115:     /** حذف ناعم + إنهاء الجلسات: حساب محذوف لا يبقى مسجلًا دخوله. */
116:     public function delete(Customer $customer, ?int $actorId = null): void
117:     {
118:         DB::transaction(function () use ($customer, $actorId): void {
119:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
120:             $customer->tokens()->delete();
121:             DB::table('password_reset_tokens')->where('email', $customer->getEmailForPasswordReset())->delete();
122:             CustomerAuditLog::record($customer, 'deleted', $actorId);
123:             $customer->delete();
124:         });
125:     }
126: 
127:     /**
128:      * اعتماد حساب (غالبًا طلب جملة): يطبق اختياريًا المجموعة والحد الائتماني
129:      * والترقية لموزع، ويسجل المعتمِد ووقته، ويمسح أي سبب رفض/إيقاف سابق.
130:      */
131:     public function approve(Customer $customer, array $data, int $adminId): Customer
132:     {
133:         return DB::transaction(function () use ($customer, $data, $adminId): Customer {
134:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
135:             if ($customer->status === CustomerStatus::Approved && ($data['type'] ?? $customer->type->value) === $customer->type->value) {
136:                 throw new BusinessException('هذا الحساب معتمد بالفعل.');
137:             }
138:             $legal = [];
139:             if ($customer->documents()->where('status', '!=', 'verified')->exists()) {
140:                 throw new BusinessException('راجع واعتمد جميع المستندات المرفقة قبل اعتماد الحساب.');
141:             }
142:             if (($data['type'] ?? $customer->type->value) !== CustomerType::Retail->value) {
143:                 if (! $customer->documents()->where('status', 'verified')->exists()) {
144:                     throw new BusinessException('يلزم مستند موثّق واحد على الأقل لاعتماد حساب الجملة أو الموزع.');
145:                 }
146:                 foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
147:                     $legal[$field] = $data[$field] ?? $customer->{$field};
148:                     if (blank($legal[$field])) {
149:                         throw new BusinessException('بيانات الجملة مطلوبة قبل الاعتماد.', [$field => ['هذا الحقل مطلوب لاعتماد حساب الجملة أو الموزع.']]);
150:                     }
151:                 }
152:             }
153: 
154:             $customer->update([
155:                 ...$legal,
156:                 'status' => CustomerStatus::Approved,
157:                 'approved_by' => $adminId,
158:                 'approved_at' => now(),
159:                 'rejection_reason' => null,
160:                 'suspension_reason' => null,
161:                 'customer_group_id' => array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $customer->customer_group_id,
162:                 'credit_limit' => $data['credit_limit'] ?? $customer->credit_limit,
163:                 'type' => $data['type'] ?? $customer->type,
164:             ]);
165:             CustomerAuditLog::record($customer, 'approved', $adminId, ['type' => $customer->type->value, 'credit_limit' => $customer->credit_limit, 'customer_group_id' => $customer->customer_group_id]);
166: 
167:             if ($customer->type !== CustomerType::Retail) {
168:                 WholesaleApplicationReviewed::dispatch($customer, 'approved');
169:             }
170: 
171:             return $customer->load(['customerGroup', 'documents']);
172:         });
173:     }
174: 
175:     public function reject(Customer $customer, string $reason, ?int $actorId = null): Customer
176:     {
177:         return DB::transaction(function () use ($customer, $reason, $actorId): Customer {
178:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
179:             if ($customer->status !== CustomerStatus::Pending) {
180:                 throw new BusinessException('يمكن رفض الطلبات قيد المراجعة فقط؛ استخدم الإيقاف للحسابات المعتمدة.');
181:             }
182: 
183:             $customer->update([
184:                 'status' => CustomerStatus::Rejected,
185:                 'rejection_reason' => $reason,
186:             ]);
187:             CustomerAuditLog::record($customer, 'rejected', $actorId, ['reason' => $reason]);
188: 
189:             if ($customer->type !== CustomerType::Retail) {
190:                 WholesaleApplicationReviewed::dispatch($customer, 'rejected', $reason);
191:             }
192: 
193:             return $customer->load(['customerGroup', 'documents']);
194:         });
195:     }
196: 
197:     /** إيقاف فوري: الحالة + السبب + حذف كل توكنات العميل في نفس اللحظة. */
198:     public function suspend(Customer $customer, string $reason, ?int $actorId = null): Customer
199:     {
200:         return DB::transaction(function () use ($customer, $reason, $actorId): Customer {
201:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
202:             if ($customer->status === CustomerStatus::Suspended) {
203:                 throw new BusinessException('هذا الحساب موقوف بالفعل.');
204:             }
205:             $customer->update([
206:                 'status' => CustomerStatus::Suspended,
207:                 'suspension_reason' => $reason,
208:             ]);
209:             $customer->tokens()->delete();
210:             DB::table('password_reset_tokens')->where('email', $customer->getEmailForPasswordReset())->delete();
211:             CustomerAuditLog::record($customer, 'suspended', $actorId, ['reason' => $reason]);
212: 
213:             return $customer->load('customerGroup');
214:         });
215:     }
216: 
217:     public function restore(Customer $customer, ?int $actorId): Customer
218:     {
219:         return DB::transaction(function () use ($customer, $actorId): Customer {
220:             $customer = Customer::withTrashed()->lockForUpdate()->findOrFail($customer->id);
221:             if (! $customer->trashed()) {
222:                 throw new BusinessException('الحساب غير محذوف.');
223:             }
224:             $customer->restore();
225:             CustomerAuditLog::record($customer, 'restored', $actorId);
226: 
227:             return $customer->load('customerGroup');
228:         });
229:     }
230: 
231:     public function reviewDocument(Customer $customer, CustomerDocument $document, string $status, int $actorId): CustomerDocument
232:     {
233:         return DB::transaction(function () use ($customer, $document, $status, $actorId) {
234:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
235:             $document = $customer->documents()->whereKey($document->id)->lockForUpdate()->firstOrFail();
236:             $document->forceFill(['status' => $status, 'reviewed_by' => $actorId, 'reviewed_at' => now()])->save();
237:             CustomerAuditLog::record($customer, 'document_reviewed', $actorId, ['document_id' => $document->id, 'status' => $status]);
238: 
239:             return $document;
240:         });
241:     }
242: 
243:     public function uploadDocument(Customer $customer, UploadedFile $file, int $actorId): CustomerDocument
244:     {
245:         return PrivateAttachments::transaction(function (PrivateAttachments $files) use ($customer, $file, $actorId): CustomerDocument {
246:             $customer = Customer::whereKey($customer->id)->lockForUpdate()->firstOrFail();
247:             if ($customer->type === CustomerType::Retail || $customer->documents()->count() >= 5) {
248:                 throw new BusinessException('رفع المستندات متاح للتجار والموزعين بحد أقصى 5 مستندات.');
249:             }
250: 
251:             $path = $files->store($file, 'customer_documents/'.$customer->id);
252:             $document = $customer->documents()->create([
253:                 'document_type' => CustomerDocumentType::Other,
254:                 'file_path' => $path,
255:                 'original_name' => CustomerDocument::safeName($file->getClientOriginalName()),
256:                 'mime_type' => $file->getMimeType(),
257:                 'status' => CustomerDocumentStatus::Pending,
258:             ]);
259:             CustomerAuditLog::record($customer, 'document_uploaded', $actorId, ['document_id' => $document->id]);
260: 
261:             return $document;
262:         });
263:     }
264: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Setting;
  9: use Illuminate\Support\Facades\Cache;
 10: use Illuminate\Support\Facades\DB;
 11: use InvalidArgumentException;
 12: use JsonException;
 13: 
 14: class SettingService
 15: {
 16:     /** @var array<string, array{0: string, 1: int}> بادئة وحشو الترقيم لكل نوع — يُقرآن مرة واحدة لكل طلب (M11). */
 17:     private array $numberingConfig = [];
 18: 
 19:     private const CACHE_KEY = 'app_settings_static';
 20: 
 21:     private const CACHE_TTL_SECONDS = 3600;
 22: 
 23:     /** @var list<string> */
 24:     private const NUMBERING_COUNTER_KEYS = [
 25:         'invoice_next_number',
 26:         'order_next_number',
 27:         'purchase_order_next_number',
 28:         'quotation_next_number',
 29:         'movement_next_number',
 30:         'transfer_next_number',
 31:         'stocktake_next_number',
 32:         'return_next_number',
 33:         'purchase_request_next_number',
 34:         'delivery_next_number',
 35:         'supplier_invoice_next_number',
 36:         'supplier_payment_next_number',
 37:     ];
 38: 
 39:     /** مستندات داخلية تُرقَّم بتسلسل PostgreSQL (فجوات مقبولة) حتى لا يُحتجز قفل العداد داخل معاملات طويلة. */
 40:     private const SEQUENCE_TYPES = [
 41:         'order' => 'order_next_number',
 42:         'purchase_order' => 'purchase_order_next_number',
 43:         'quotation' => 'quotation_next_number',
 44:         'transfer' => 'transfer_next_number',
 45:         'stocktake' => 'stocktake_next_number',
 46:         'return' => 'return_next_number',
 47:         'purchase_request' => 'purchase_request_next_number',
 48:         'delivery' => 'delivery_next_number',
 49:         'supplier_invoice' => 'supplier_invoice_next_number',
 50:         'supplier_payment' => 'supplier_payment_next_number',
 51:     ];
 52: 
 53:     /**
 54:      * Return all settings grouped by their group name, with values cast to their declared types.
 55:      * Numbering counters are read fresh because they change for every generated document number.
 56:      *
 57:      * @return array<string, array<string, mixed>>
 58:      */
 59:     public function getAllGrouped(): array
 60:     {
 61:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 62:             return Setting::query()
 63:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 64:                 ->orderBy('group')
 65:                 ->orderBy('key')
 66:                 ->get()
 67:                 ->groupBy('group')
 68:                 ->map(fn ($settings): array => $settings
 69:                     ->mapWithKeys(fn (Setting $setting): array => [
 70:                         $setting->key => $this->castValue($setting->value, $setting->type),
 71:                     ])
 72:                     ->all())
 73:                 ->all();
 74:         });
 75: 
 76:         $counters = Setting::query()
 77:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 78:             ->orderBy('key')
 79:             ->get()
 80:             ->mapWithKeys(fn (Setting $setting): array => [
 81:                 $setting->key => $this->castValue($setting->value, $setting->type),
 82:             ])
 83:             ->all();
 84: 
 85:         if (isset($counters['movement_next_number'])) {
 86:             $counters['movement_next_number'] = $this->nextMovementNumber();
 87:         }
 88:         foreach (self::SEQUENCE_TYPES as $type => $key) {
 89:             if (isset($counters[$key])) {
 90:                 $counters[$key] = $this->nextDocumentNumber($type);
 91:             }
 92:         }
 93: 
 94:         if ($counters !== []) {
 95:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 96:             ksort($grouped['numbering']);
 97:         }
 98: 
 99:         return $grouped;
100:     }
101: 
102:     public function get(string $key, mixed $default = null): mixed
103:     {
104:         foreach ($this->getAllGrouped() as $settings) {
105:             if (array_key_exists($key, $settings)) {
106:                 return $settings[$key];
107:             }
108:         }
109: 
110:         return $default;
111:     }
112: 
113:     /**
114:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
115:      *
116:      * @param  array<string, mixed>  $settings
117:      *
118:      * @throws JsonException
119:      */
120:     public function updateBatch(array $settings): void
121:     {
122:         DB::transaction(function () use ($settings): void {
123:             $movementSequenceTarget = null;
124:             /** @var array<string, int> $documentSequenceTargets */
125:             $documentSequenceTargets = [];
126:             $lockedSettings = Setting::query()
127:                 ->whereIn('key', array_keys($settings))
128:                 ->orderBy('key')
129:                 ->lockForUpdate()
130:                 ->get()
131:                 ->keyBy('key');
132: 
133:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
134: 
135:             if ($missingKeys !== []) {
136:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
137:             }
138: 
139:             foreach ($settings as $key => $value) {
140:                 /** @var Setting $setting */
141:                 $setting = $lockedSettings->get($key);
142: 
143:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
144:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
145:                     if ($key === 'movement_next_number') {
146:                         $value = max($value, $this->nextMovementNumber());
147:                         $movementSequenceTarget = $value;
148:                     }
149:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
150:                     if (is_string($sequenceType)) {
151:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
152:                         $documentSequenceTargets[$sequenceType] = $value;
153:                     }
154:                 }
155: 
156:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
157:                     ? ''
158:                     : $this->serializeValue($value, $setting->type);
159:                 $setting->save();
160:             }
161: 
162:             DB::afterCommit(fn () => $this->clearCache());
163: 
164:             if ($movementSequenceTarget !== null) {
165:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
166:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
167:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
168:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
169:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
170:                     DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
171:                 });
172:             }
173:             if ($documentSequenceTargets !== []) {
174:                 DB::afterCommit(function () use ($documentSequenceTargets): void {
175:                     foreach ($documentSequenceTargets as $type => $minimum) {
176:                         DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]);
177:                     }
178:                 });
179:             }
180:         }, attempts: 3);
181:     }
182: 
183:     /**
184:      * Atomically return and increment the next document number for the requested type.
185:      *
186:      * @throws JsonException
187:      */
188:     public function generateNextNumber(string $type): string
189:     {
190:         if ($type === 'movement') {
191:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
192:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
193: 
194:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
195:         }
196:         if (isset(self::SEQUENCE_TYPES[$type])) {
197:             $definitions = $this->numberingDefinitions();
198:             $definition = $definitions[$type];
199:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
200:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
201: 
202:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
203:         }
204:         $definitions = $this->numberingDefinitions();
205: 
206:         if (! isset($definitions[$type])) {
207:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
208:         }
209: 
210:         $definition = $definitions[$type];
211:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
212: 
213:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
214:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
215:             $nextSetting = Setting::query()
216:                 ->where('key', $definition['next'])
217:                 ->lockForUpdate()
218:                 ->first();
219: 
220:             if ($nextSetting === null) {
221:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
222:             }
223: 
224:             $nextValue = $this->counterValue($nextSetting->value);
225: 
226:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
227:             $nextSetting->value = (string) ($nextValue + 1);
228:             $nextSetting->save();
229: 
230:             return $formatted;
231:         }, attempts: 3);
232:     }
233: 
234:     /**
235:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
236:      *
237:      * @return array{0: string, 1: int}
238:      */
239:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
240:     {
241:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
242:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
243: 
244:             foreach ([$prefixKey, $paddingKey] as $key) {
245:                 if (! $settings->has($key)) {
246:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
247:                 }
248:             }
249: 
250:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
251:         })();
252:     }
253: 
254:     public function clearCache(): void
255:     {
256:         Cache::forget(self::CACHE_KEY);
257:         $this->numberingConfig = [];
258:     }
259: 
260:     /**
261:      * @return array<string, array{prefix: string, next: string, padding: string}>
262:      */
263:     private function numberingDefinitions(): array
264:     {
265:         return [
266:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
267:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
268:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
269:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
270:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
271:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
272:             'return' => ['prefix' => 'return_prefix', 'next' => 'return_next_number', 'padding' => 'return_padding'],
273:             'purchase_request' => ['prefix' => 'purchase_request_prefix', 'next' => 'purchase_request_next_number', 'padding' => 'purchase_request_padding'],
274:             'delivery' => ['prefix' => 'delivery_prefix', 'next' => 'delivery_next_number', 'padding' => 'delivery_padding'],
275:             'supplier_invoice' => ['prefix' => 'supplier_invoice_prefix', 'next' => 'supplier_invoice_next_number', 'padding' => 'supplier_invoice_padding'],
276:             'supplier_payment' => ['prefix' => 'supplier_payment_prefix',    'next' => 'supplier_payment_next_number',    'padding' => 'supplier_payment_padding'],
277:             'shift' => ['prefix' => 'shift_prefix',               'next' => 'shift_next_number',               'padding' => 'shift_padding'],
278:             'expense' => ['prefix' => 'expense_prefix',             'next' => 'expense_next_number',             'padding' => 'expense_padding'],
279:             'treasury_transfer' => ['prefix' => 'treasury_transfer_prefix',   'next' => 'treasury_transfer_next_number',   'padding' => 'treasury_transfer_padding'],
280:             'payment_notice' => ['prefix' => 'payment_notice_prefix',      'next' => 'payment_notice_next_number',      'padding' => 'payment_notice_padding'],
281:         ];
282:     }
283: 
284:     private function nextMovementNumber(): int
285:     {
286:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
287: 
288:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
289:     }
290: 
291:     private function nextDocumentNumber(string $type): int
292:     {
293:         if (! isset(self::SEQUENCE_TYPES[$type])) {
294:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
295:         }
296:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
297: 
298:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
299:     }
300: 
301:     private function counterValue(mixed $value): int
302:     {
303:         $number = (is_int($value) || is_string($value))
304:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
305:             : false;
306:         if ($number === false) {
307:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
308:         }
309: 
310:         return $number;
311:     }
312: 
313:     private function castValue(?string $value, string $type): mixed
314:     {
315:         if ($value === null) {
316:             return null;
317:         }
318: 
319:         return match ($type) {
320:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
321:             'integer' => (int) $value,
322:             'float' => (float) $value,
323:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
324:             default => $value,
325:         };
326:     }
327: 
328:     /** @throws JsonException */
329:     private function serializeValue(mixed $value, string $type): ?string
330:     {
331:         if ($value === null) {
332:             return null;
333:         }
334: 
335:         if ($type === 'json') {
336:             return json_encode($value, JSON_THROW_ON_ERROR);
337:         }
338: 
339:         if ($type === 'boolean') {
340:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
341:         }
342: 
343:         return (string) $value;
344:     }
345: }

