170:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
171:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
172:     if (v instanceof Blob) return fd.append(key, v);
173:     fd.append(key, String(v));
174:   };
175:   put('name_ar', p.name_ar);
176:   put('name_en', p.name_en);
177:   put('slug', p.slug);
178:   put('description_ar', p.description_ar);
179:   put('description_en', p.description_en);
180:   put('sort_order', p.sort_order);
181:   put('is_active', p.is_active);
182:   if (p.logo) put('logo', p.logo);
183:   if (p.remove_logo) put('remove_logo', true);
184:   return fd;
185: }
186: 
187: export const brandsApi = {
188:   list: (params: BrandListParams, signal?: AbortSignal) =>
189:     apiClient.get<ResourceCollection<AdminBrand>>(BR, { params, signal }).then(r => r.data),
190:   show: (id: number) => apiClient.get<{ data: AdminBrand }>(`${BR}/${id}`).then(r => r.data.data),
191:   create: (p: BrandPayload, onProgress?: (n: number) => void) =>
192:     apiClient.post<{ data: AdminBrand }>(BR, brandFormData(p), { ...MULTIPART, onUploadProgress: progress(onProgress) }).then(r => r.data.data),
193:   update: (id: number, p: BrandPayload, onProgress?: (n: number) => void) =>
194:     apiClient.post<{ data: AdminBrand }>(`${BR}/${id}`, brandFormData(p, true), { ...MULTIPART, onUploadProgress: progress(onProgress) }).then(r => r.data.data),
195:   remove: (id: number) => apiClient.delete<{ message: string }>(`${BR}/${id}`).then(r => r.data),
196: };
197: 
198: export const productsApi = {
199:   list: (params: ProductListParams, signal?: AbortSignal) =>
200:     apiClient.get<ResourceCollection<AdminProduct>>(PR, { params, signal }).then(r => r.data),
201:   show: (id: number, signal?: AbortSignal) => apiClient.get<{ data: AdminProduct }>(`${PR}/${id}`, { signal }).then(r => r.data.data),
202:   create: (p: ProductPayload & { variants?: VariantPayload[] }) => apiClient.post<{ data: AdminProduct }>(PR, p).then(r => r.data.data),
203:   update: (id: number, p: Partial<ProductPayload> & { status?: ProductStatus; expected_updated_at?: string }) =>
204:     apiClient.put<{ data: AdminProduct }>(`${PR}/${id}`, p).then(r => r.data.data),
205:   remove: (id: number) => apiClient.delete<{ message: string }>(`${PR}/${id}`).then(r => r.data),
206: };
207: 
208: export const variantsApi = {
209:   list: (productId: number) => apiClient.get<{ data: AdminVariant[] }>(`${PR}/${productId}/variants`).then(r => r.data.data),
210:   create: (productId: number, p: VariantPayload) => apiClient.post<{ data: AdminVariant }>(`${PR}/${productId}/variants`, p).then(r => r.data.data),
211:   update: (productId: number, id: number, p: Partial<VariantPayload>) => apiClient.put<{ data: AdminVariant }>(`${PR}/${productId}/variants/${id}`, p).then(r => r.data.data),
212:   remove: (productId: number, id: number) => apiClient.delete(`${PR}/${productId}/variants/${id}`).then(r => r.data),
213: };
214: 
215: export const productMediaApi = {
216:   list: (productId: number) => apiClient.get<{ data: AdminMedia[] }>(`${PR}/${productId}/media`).then(r => r.data.data),
217:   uploadImages: (productId: number, files: File[], variantId?: number | null, onProgress?: (n: number) => void, clientUploadIds?: string[]) => {
218:     const fd = new FormData();
219:     fd.append('collection', 'images');
220:     if (variantId) fd.append('variant_id', String(variantId));
221:     files.forEach((f, index) => {
222:       fd.append('files[]', f); // max 4 per request
223:       fd.append('client_upload_ids[]', clientUploadIds?.[index] ?? crypto.randomUUID());
224:     });
225:     return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, timeout: 180000, onUploadProgress: progress(onProgress) }).then(r => r.data.data);
226:   },
227:   uploadVideo: (productId: number, file: File, onProgress?: (n: number) => void) => {
228:     const fd = new FormData();
229:     fd.append('collection', 'video');
230:     fd.append('file', file);
231:     return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, onUploadProgress: progress(onProgress), timeout: 0 }).then(r => r.data.data);
232:   },
233:   reorder: (productId: number, ids: number[]) => apiClient.put(`${PR}/${productId}/media/reorder`, { ids }).then(r => r.data),
234:   remove: (productId: number, mediaId: number) => apiClient.delete(`${PR}/${productId}/media/${mediaId}`).then(r => r.data),
235: };

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\ProductStatus;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Cart;
 12: use App\Models\CartItem;
 13: use App\Models\Customer;
 14: use App\Models\ProductVariant;
 15: use Illuminate\Support\Facades\DB;
 16: use Illuminate\Support\Str;
 17: 
 18: /**
 19:  * سلة التسوق للزائر والعميل المسجل.
 20:  * - الزائر: سلة مربوطة بـ cart_token (يُرسل في هيدر X-Cart-Session).
 21:  * - العميل: سلة مربوطة بحسابه؛ وعند تسجيل الدخول تُدمج سلة الزائر فيها.
 22:  * الأسعار دائمًا لحظية من PricingService (لا تُخزّن في السلة أبدًا).
 23:  */
 24: class CartService
 25: {
 26:     public function __construct(
 27:         protected PricingService $pricing,
 28:         protected StoreCatalogService $catalog,
 29:         protected CouponService $coupons,
 30:     ) {}
 31: 
 32:     /**
 33:      * سلة الزائر/العميل الحالية.
 34:      * - التوكن غير الـ UUID يُتجاهل تمامًا (M2)؛ وتوكن أي سلة جديدة
 35:      *   يُولّد على الخادم دائمًا (Cart::booted) ولا يُقبل مقترح العميل.
 36:      * - بوضع القراءة ($create=false) لا يُحفظ أي صف: تُرجع سلة فارغة
 37:      *   افتراضية حتى لا تملأ الزواحف جدول carts (M3).
 38:      * لو وُجدت سلة زائر بالتوكن وعميل مسجل، تُدمج فيها أولًا.
 39:      */
 40:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 41:     {
 42:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 43: 
 44:         if ($customer !== null) {
 45:             $cart = $create
 46:                 ? $this->accountCart($customer)
 47:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 48:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 49:                 $this->mergeGuestCart($customer, $guestToken);
 50:                 $cart = $cart->fresh();
 51:             }
 52: 
 53:             return $cart->loadMissing('items');
 54:         }
 55: 
 56:         $cart = $guestToken !== null
 57:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 58:             : null;
 59:         if ($cart !== null) {
 60:             return $cart->loadMissing('items');
 61:         }
 62: 
 63:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 64:     }
 65: 
 66:     /**
 67:      * سلة حساب العميل الوحيدة — القيد الفريد على customer_id يحسم السباق (M6).
 68:      * createOrFirst يغلّف الإدراج في savepoint داخل المعاملات (F-10):
 69:      * firstOrCreate العادي إذا فشل إدراجه هنا — والدمج كله داخل transaction
 70:      * خارجية — ترك المعاملة aborted (25P02) فخرج 500 رغم الـ catch.
 71:      */
 72:     private function accountCart(Customer $customer): Cart
 73:     {
 74:         return Cart::query()->where('customer_id', $customer->id)->first()
 75:             ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
 76:     }
 77: 
 78:     /** دمج سلة زائر (بالتوكن) في سلة حساب العميل — تُستدعى عند تسجيل الدخول. */
 79:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 80:     {
 81:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 82:         if ($guestToken === null) {
 83:             return;
 84:         }
 85: 
 86:         // كل الدمج داخل transaction واحدة وسلة الزائر مقفولة: طلبات متوازية
 87:         // بعد تسجيل الدخول بنفس التوكن لا تضاعف الكميات (M6)
 88:         DB::transaction(function () use ($customer, $guestToken): void {
 89:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 90:                 ->lockForUpdate()->first();
 91:             if ($guest === null) {
 92:                 return;
 93:             }
 94:             if (! $guest->items()->exists()) {
 95:                 $guest->delete();
 96: 
 97:                 return;
 98:             }
 99: 
100:             $account = $this->accountCart($customer);
101:             // الدمج يحترم سقوف السلة (M2): بغير ذلك بضع سلال زائر بحد البنود
102:             // تُنتج سلة حساب بمئات البنود فتُلغي حماية F15
103:             $maxLines = (int) config('store.max_cart_lines', 50);
104:             $lineCap = $this->lineQtyCap($customer);
105:             $accountQty = $account->items()->pluck('qty', 'product_variant_id')
106:                 ->map(fn ($qty): float => (float) $qty)->all();
107:             $accountLines = count($accountQty);
108: 
109:             foreach ($guest->items as $item) {
110:                 $variantId = (int) $item->product_variant_id;
111:                 $existingQty = $accountQty[$variantId] ?? null;
112:                 $isNew = $existingQty === null;
113: 
114:                 // بنود جديدة فوق السقف تُتجاهل (لا تُفشل تسجيل الدخول)
115:                 if ($isNew && $maxLines > 0 && $accountLines >= $maxLines) {
116:                     continue;
117:                 }
118: 
119:                 $qty = (float) $item->qty;
120:                 if ($lineCap > 0) {
121:                     $allowed = $lineCap - (float) ($existingQty ?? 0);
122:                     if ($allowed <= 0) {
123:                         continue;
124:                     }
125:                     $qty = min($qty, $allowed);
126:                 }
127: 
128:                 // UPSERT ذرّي: دمج متزامن لا يصطدم بقيد التفرد (F-09)
129:                 CartItem::query()->upsert(
130:                     [[
131:                         'cart_id' => $account->id,
132:                         'product_variant_id' => $variantId,
133:                         'qty' => $qty,
134:                         'created_at' => now(),
135:                         'updated_at' => now(),
136:                     ]],
137:                     ['cart_id', 'product_variant_id'],
138:                     ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
139:                 );
140: 
141:                 $accountQty[$variantId] = (float) ($existingQty ?? 0) + $qty;
142:                 if ($isNew) {
143:                     $accountLines++;
144:                 }
145:             }
146:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
147:                 $account->update(['coupon_id' => $guest->coupon_id]);
148:             }
149:             $guest->items()->delete();
150:             $guest->delete();
151:         });
152:     }
153: 
154:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
155:     {
156:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
157:             // قفل صف السلة (F19): إضافتان متزامنتان تتسلسلان فلا تُحسب
158:             // الكمية على قراءة قديمة ولا يُتجاوز سقف البنود
159:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
160: 
161:             $variant = $this->purchasableVariant($variantId);
162:             $existing = $cart->items()->where('product_variant_id', $variantId)->first();
163: 
164:             // سقف أصناف السلة (F15): سلة بآلاف البنود تُثقل التسعير وكل عرض
165:             if ($existing === null) {
166:                 $maxLines = (int) config('store.max_cart_lines', 50);
167:                 if ($maxLines > 0 && $cart->items()->count() >= $maxLines) {
168:                     throw new BusinessException("بلغت سلة التسوق سقف الأصناف ({$maxLines})؛ احذف صنفًا قبل الإضافة.");
169:                 }
170:             }
171: 
172:             $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
173:             $this->assertLineQty($customer, $targetQty);
174:             $this->assertAvailable($variantId, $targetQty);
175:             $this->assertPriced($variant, $customer, $targetQty);
176: 
177:             // كتابة ذرّية UPSERT (F-09): نقرتان متزامنتان على «أضف للسلة»
178:             // كانتا تصطدمان بقيد التفرد عند الإدراج الثاني فتخرج 500 —
179:             // ON CONFLICT تجمع الكمية على الصف نفسه. القراءة أعلاه تبقى
180:             // للتحقق من حد التوفر فقط
181:             CartItem::query()->upsert(
182:                 [[
183:                     'cart_id' => $cart->id,
184:                     'product_variant_id' => $variantId,
185:                     'qty' => $qty,
186:                     'created_at' => now(),
187:                     'updated_at' => now(),
188:                 ]],
189:                 ['cart_id', 'product_variant_id'],
190:                 ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
191:             );
192: 
193:             return $cart->fresh('items');
194:         });
195:     }
196: 
197:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
198:     {
199:         if ($qty <= 0) {
200:             return $this->removeItem($cart, $variantId);
201:         }
202: 
203:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
204:             // قفل صف السلة (F19) بنفس منطق addItem
205:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
206:             $variant = $this->purchasableVariant($variantId);
207:             $this->assertLineQty($customer, $qty);
208:             $this->assertAvailable($variantId, $qty);
209:             $this->assertPriced($variant, $customer, $qty);
210: 
211:             // UPSERT ذرّي بنفس منطق addItem — updateOrCreate كان يصطدم
212:             // بقيد التفرد تحت التزامن (F-09)، وهنا القيمة مطلقة لا تراكمية
213:             CartItem::query()->upsert(
214:                 [[
215:                     'cart_id' => $cart->id,
216:                     'product_variant_id' => $variantId,
217:                     'qty' => $qty,
218:                     'created_at' => now(),
219:                     'updated_at' => now(),
220:                 ]],
221:                 ['cart_id', 'product_variant_id'],
222:                 ['qty' => $qty, 'updated_at' => now()],
223:             );
224: 
225:             return $cart->fresh('items');
226:         });
227:     }
228: 
229:     public function removeItem(Cart $cart, int $variantId): Cart
230:     {
231:         $cart->items()->where('product_variant_id', $variantId)->delete();
232: 
233:         return $cart->fresh('items');
234:     }
235: 
236:     /**
237:      * بنود السلة بأسعار لحظية من PricingService.
238:      * بند غير قابل للتسعير يرجع بـ unit_price = null (العرض يتجاوزه،
239:      * وإتمام الشراء يرفضه — يتحقق المستدعي).
240:      *
241:      * @return array<int, array{variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
242:      */
243:     public function pricedLines(Cart $cart, ?Customer $customer): array
244:     {
245:         $cart->loadMissing('items.variant.product');
246:         $lines = [];
247:         foreach ($cart->items as $item) {
248:             $variant = $item->variant;
249:             $qty = (float) $item->qty;
250:             try {
251:                 $resolved = $this->pricing->resolve($variant, $customer, $qty);
252:                 $unit = (float) $resolved['unit_price'];
253:                 $base = (float) $resolved['base_price'];
254:                 $lines[] = [
255:                     'item_id' => $item->id,
256:                     'variant' => $variant,
257:                     'qty' => $qty,
258:                     'unit_price' => $unit,
259:                     'base_price' => $base,
260:                     'line_discount' => round(($base - $unit) * $qty, 2),
261:                     'line_total' => round($unit * $qty, 2),
262:                 ];
263:             } catch (BusinessException) {
264:                 $lines[] = [
265:                     'item_id' => $item->id,
266:                     'variant' => $variant,
267:                     'qty' => $qty,
268:                     'unit_price' => null,
269:                     'base_price' => null,
270:                     'line_discount' => 0.0,
271:                     'line_total' => 0.0,
272:                 ];
273:             }
274:         }
275: 
276:         return $lines;
277:     }
278: 
279:     /**
280:      * ملخص السلة المالي بالأسعار اللحظية.
281:      *
282:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
283:      */
284:     /**
285:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
286:      *                                                        لتجنب إعادة التسعير (M15)
287:      */
288:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
289:     {
290:         $lines ??= $this->pricedLines($cart, $customer);
291:         $subtotal = 0.0;
292:         $itemsTotal = 0.0;
293:         foreach ($lines as $line) {
294:             if ($line['unit_price'] === null) {
295:                 continue;
296:             }
297:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
298:             $subtotal += round((float) $line['base_price'] * $line['qty'], 2);
299:             $itemsTotal += $line['line_total'];
300:         }
301: 
302:         // الخصم السعري = الفرق بين الإجماليين المقرّبين، لا مجموع فروق
303:         // السطور المقرّبة (F-26) حتى لا يظهر فرق قرش بين العرض والمحصّل.
304:         // ‏(L6) سعر مخصص أعلى من الأساسي لا يصنع خصمًا سالبًا: يُرفع المرجع
305:         // لسعر البيع الفعلي، فلا يزيد الخصم السالب الإجمالي المحصّل.
306:         if ($subtotal < $itemsTotal) {
307:             $subtotal = $itemsTotal;
308:             $pricingDiscount = 0.0;
309:         } else {
310:             $pricingDiscount = round($subtotal - $itemsTotal, 2);
311:         }
312: 
313:         $couponDiscount = 0.0;
314:         $couponCode = null;
315:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
316:             try {
317:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
318:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
319:                 $couponCode = $coupon->code;
320:             } catch (BusinessException) {
321:                 // كوبون لم يعد صالحًا: يُعرض الملخص بدونه (إتمام الشراء سيعيد التحقق)
322:             }
323:         }
324: 
325:         return [
326:             'subtotal' => round($subtotal, 2),
327:             'pricing_discount' => round($pricingDiscount, 2),
328:             'items_total' => round($itemsTotal, 2),
329:             'coupon_discount' => $couponDiscount,
330:             'total' => round($itemsTotal - $couponDiscount, 2),
331:             'coupon_code' => $couponCode,
332:         ];
333:     }
334: 
335:     /**
336:      * إعادة التحقق من قابلية البيع لكل بند لحظة الشراء بشكل مجمّع (M14):
337:      * متغير معطّل أو منتج غير منشور/محذوف ناعمًا بعد الإضافة يوقف الطلب.
338:      *
339:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
340:      */
341:     public function assertLinesPurchasable(array $lines): void
342:     {
343:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
344:         $variants = ProductVariant::query()->with('product')
345:             ->whereIn('id', $ids)->get()->keyBy('id');
346:         foreach ($lines as $line) {
347:             $variant = $variants->get($line['variant']->id) ?? $line['variant'];
348:             if (! $variant->is_active || $variant->product === null
349:                 || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
350:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
351:             }
352:         }
353:     }
354: 
355:     /**
356:      * إعادة التحقق من توفر بنود مُسعّرة لحظة الشراء.
357:      *
358:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
359:      */
360:     public function assertLinesAvailable(array $lines): void
361:     {
362:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
363:         $map = $this->catalog->availabilityMap($ids);
364:         foreach ($lines as $line) {
365:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
366:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
367:             }
368:         }
369:     }
370: 
371:     /**
372:      * تمثيل السلة للعرض: البنود بأسعار ومتاح لحظي + الملخص المالي.
373:      *
374:      * @return array<string, mixed>
375:      */
376:     public function present(Cart $cart, ?Customer $customer): array
377:     {
378:         $lines = $this->pricedLines($cart, $customer);
379:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
380:         $availability = $this->catalog->availabilityMap($ids);
381: 
382:         $items = [];
383:         foreach ($lines as $line) {
384:             $variant = $line['variant'];
385:             $items[] = [
386:                 'id' => $line['item_id'],
387:                 'product_variant_id' => $variant->id,
388:                 'product_id' => $variant->product_id,
389:                 'product_name' => $variant->product?->name_ar,
390:                 'sku' => $variant->sku,
391:                 'qty' => $line['qty'],
392:                 'unit_price' => $line['unit_price'],
393:                 'base_price' => $line['base_price'],
394:                 'line_discount' => $line['line_discount'],
395:                 'line_total' => $line['line_total'],
396:                 'available' => $availability[$variant->id] ?? 0,
397:                 'priced' => $line['unit_price'] !== null,
398:             ];
399:         }
400: 
401:         return [
402:             'id' => $cart->id,
403:             'cart_token' => $cart->cart_token,
404:             'customer_id' => $cart->customer_id,
405:             'items' => $items,
406:             'totals' => $this->totals($cart, $customer, $lines),
407:         ];
408:     }
409: 
410:     private function purchasableVariant(int $variantId): ProductVariant
411:     {
412:         $variant = ProductVariant::query()->with('product')->find($variantId);
413:         if ($variant === null || ! $variant->is_active || $variant->product === null
414:             || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
415:             throw new BusinessException('الصنف غير متاح للشراء.');
416:         }
417: 
418:         return $variant;
419:     }
420: 
421:     /** سقف كمية البند الواحد (H2): للزوار، وللمسجّلين غير الجملة سقف تجزئة. */
422:     private function assertLineQty(?Customer $customer, float $qty): void
423:     {
424:         $cap = $this->lineQtyCap($customer);
425:         if ($cap > 0 && $qty > $cap) {
426:             throw new BusinessException($customer === null
427:                 ? "سقف كمية البند الواحد للزوار ({$cap}) — سجّل الدخول للكميات الأكبر."
428:                 : "سقف كمية البند الواحد ({$cap}) — للكميات الأكبر تواصل مع مسار الجملة.");
429:         }
430:     }
431: 
432:     /** سقف كمية السطر الفعّال للهوية: 0 = بلا سقف (عملاء الجملة المعتمدون). */
433:     private function lineQtyCap(?Customer $customer): float
434:     {
435:         if ($customer === null) {
436:             return (float) config('store.guest_max_line_qty', 10);
437:         }
438:         if ($customer->status === CustomerStatus::Approved
439:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
440:             return 0.0;
441:         }
442: 
443:         return (float) config('store.retail_max_line_qty', 50);
444:     }
445: 
446:     private function assertAvailable(int $variantId, float $qty): void
447:     {
448:         $available = $this->catalog->availabilityMap([$variantId])[$variantId] ?? 0;
449:         if ($available < $qty) {
450:             throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف.');
451:         }
452:     }
453: 
454:     private function assertPriced(ProductVariant $variant, ?Customer $customer, float $qty): void
455:     {
456:         $this->pricing->resolve($variant, $customer, $qty); // يرمي BusinessException عند غياب السعر
457:     }
458: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Cart;
 10: use App\Models\Coupon;
 11: use App\Models\CouponUsage;
 12: use App\Models\Customer;
 13: use App\Models\Order;
 14: use Illuminate\Support\Facades\DB;
 15: use Illuminate\Support\Facades\RateLimiter;
 16: 
 17: /**
 18:  * التحقق من الكوبونات وربطها بالسلة وحساب خصمها وتسجيل استخدامها.
 19:  * الفحوص: التفعيل، النافذة الزمنية، الحد الكلي للاستخدام، حد العميل
 20:  * الواحد (usage_limit_per_customer — افتراضي 1)، والحد الأدنى للسلة.
 21:  * الخصم النسبي: min(subtotal × value/100, max_discount_amount).
 22:  * كوبون free_shipping خصمه المالي على البضاعة صفر — أثره إلغاء الشحن
 23:  * عند إتمام الشراء (يُسجل مبلغ الشحن المُعفى في سجل الاستخدام).
 24:  */
 25: class CouponService
 26: {
 27:     // رسالة موحّدة لعدم صلاحية الكود (F-24): «غير موجود» و«موجود لكن غير
 28:     // قابل للاستخدام» يجب ألا يتيحا تمييز وجود الكود بالتخمين
 29:     private const NOT_REDEEMABLE = 'كود الخصم غير صحيح أو غير متاح أو انتهت صلاحيته أو استُنفد حد استخدامه.';
 30: 
 31:     public function validateAndApply(Cart $cart, string $code, float $subtotal, ?Customer $customer = null): float
 32:     {
 33:         $coupon = $this->findRedeemable($code, $subtotal, $customer);
 34:         $this->enforceRateLimit($coupon, 'apply');
 35: 
 36:         $cart->update(['coupon_id' => $coupon->id]);
 37: 
 38:         return $this->discountFor($coupon, $subtotal);
 39:     }
 40: 
 41:     /**
 42:      * حد معدّل لكل (كوبون + IP) (H3): بديل آمن عن السقف العالمي لطلبات
 43:      * الزوار المعلّقة الذي كان مهاجم واحد يُعطّل به الحملة على كل الزوار.
 44:      * يُستدعى عند التطبيق وعند إتمام الشراء.
 45:      */
 46:     public function enforceRateLimit(Coupon $coupon, string $action = 'apply'): void
 47:     {
 48:         $max = (int) config('store.coupon_apply_per_minute', 20);
 49:         if ($max <= 0) {
 50:             return;
 51:         }
 52: 
 53:         $key = 'coupon:'.$action.':'.$coupon->id.':'.(request()->ip() ?? 'unknown');
 54:         if (RateLimiter::tooManyAttempts($key, $max)) {
 55:             throw new BusinessException(self::NOT_REDEEMABLE, [], 429);
 56:         }
 57:         RateLimiter::hit($key, 60);
 58:     }
 59: 
 60:     /** يتحقق من كوبون مرتبط بسلة (عند إتمام الشراء) ويرجعه أو يرمي استثناءً. */
 61:     public function redeemableById(int $couponId, float $subtotal, ?Customer $customer = null, ?string $guestPhone = null): Coupon
 62:     {
 63:         $coupon = Coupon::query()->find($couponId);
 64:         if ($coupon === null) {
 65:             throw new BusinessException(self::NOT_REDEEMABLE);
 66:         }
 67:         $this->assertRedeemable($coupon, $subtotal, $customer, $guestPhone);
 68: 
 69:         return $coupon;
 70:     }
 71: 
 72:     /** خصم البضاعة: النسبي بسقف، والثابت بحد الإجمالي، والشحن المجاني صفر هنا. */
 73:     public function discountFor(Coupon $coupon, float $subtotal): float
 74:     {
 75:         if ($subtotal <= 0 || $coupon->type === 'free_shipping') {
 76:             return 0.0;
 77:         }
 78: 
 79:         $discount = $coupon->type === 'percentage'
 80:             ? $subtotal * (float) $coupon->value / 100
 81:             : (float) $coupon->value;
 82: 
 83:         if ($coupon->max_discount_amount !== null) {
 84:             $discount = min($discount, (float) $coupon->max_discount_amount);
 85:         }
 86: 
 87:         return round(min($discount, $subtotal), 2);
 88:     }
 89: 
 90:     /**
 91:      * تسجيل استخدام فعلي عند إتمام الطلب + تحديث العداد الكلي ذرّيًا (F4).
 92:      * قفل استشاري على (الكوبون + هوية المستخدم) يمنع سباق الحد الفردي،
 93:      * والزيادة الشرطية على العداد الكلي تمنع تجاوز usage_limit حتى بلا
 94:      * قفل صف الكوبون على مسار الشراء (أُزيل القفل المسبق من OrderService).
 95:      */
 96:     public function recordUsage(Coupon $coupon, Order $order, ?Customer $customer, float $discountAmount): CouponUsage
 97:     {
 98:         $guestPhoneNormalized = $customer === null && $order->guest_phone !== null
 99:             ? Customer::normalizePhone($order->guest_phone)
100:             : null;
101: 
102:         $identity = $customer !== null
103:             ? 'customer:'.$customer->id
104:             : 'phone:'.($guestPhoneNormalized ?? 'anonymous');
105:         DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['coupon-usage:'.$coupon->id.':'.$identity]);
106: 
107:         // إعادة التحقق الفردي تحت القفل: استخدامان متزامنان لنفس الهوية
108:         // يتسلسلان فيرى الثاني استخدام الأول
109:         $this->assertPerIdentityAllowed($coupon, $customer, $guestPhoneNormalized);
110: 
111:         $incremented = Coupon::query()
112:             ->whereKey($coupon->id)
113:             ->where(fn ($q) => $q->whereNull('usage_limit')->orWhereColumn('used_count', '<', 'usage_limit'))
114:             ->increment('used_count');
115:         if ($incremented === 0) {
116:             throw new BusinessException(self::NOT_REDEEMABLE);
117:         }
118: 
119:         return CouponUsage::create([
120:             'coupon_id' => $coupon->id,
121:             'customer_id' => $customer?->id,
122:             'order_id' => $order->id,
123:             'discount_amount' => $discountAmount,
124:             // هاتف الزائر الموحد يُخزَّن مع الاستخدام لفحص الحد لاحقًا في SQL (F-04)
125:             'guest_phone_normalized' => $guestPhoneNormalized,
126:         ]);
127:     }
128: 
129:     private function findRedeemable(string $code, float $subtotal, ?Customer $customer): Coupon
130:     {
131:         $coupon = Coupon::query()->where('code', strtoupper(trim($code)))->first();
132:         if ($coupon === null) {
133:             throw new BusinessException(self::NOT_REDEEMABLE);
134:         }
135:         $this->assertRedeemable($coupon, $subtotal, $customer);
136: 
137:         return $coupon;
138:     }
139: 
140:     private function assertRedeemable(Coupon $coupon, float $subtotal, ?Customer $customer, ?string $guestPhone = null): void
141:     {
142:         if (! $coupon->isRedeemableNow()) {
143:             throw new BusinessException(self::NOT_REDEEMABLE);
144:         }
145:         // رسالة موحّدة (F20): لا تُفصح عن سبب الرفض فيُستخدم لتمييز السياسات
146:         if ($coupon->min_order_amount !== null && $subtotal < (float) $coupon->min_order_amount) {
147:             throw new BusinessException(self::NOT_REDEEMABLE);
148:         }
149: 
150:         $guestPhoneNormalized = ($guestPhone !== null && trim($guestPhone) !== '')
151:             ? Customer::normalizePhone($guestPhone)
152:             : null;
153: 
154:         // (H3) أُزيل السقف العالمي لطلبات الزوار المعلّقة: كان مهاجم واحد
155:         // ينشئ حدًا من الطلبات الوهمية فيعطّل الحملة على كل زائر شرعي. الحماية
156:         // الآن: حد لكل هوية (أدناه) + حد معدّل لكل كوبون/IP + تقصير مهلة
157:         // المعلّق — حماية أضعف ضد تدوير الأرقام عبر IPs لكنها لا تعطّل الحملة.
158:         $this->assertPerIdentityAllowed($coupon, $customer, $guestPhoneNormalized);
159:     }
160: 
161:     /**
162:      * حد الاستخدام لكل هوية (عميل/رقم زائر) — الطلبات الملغاة لا تحتسب.
163:      * limit <= 0 يعني بلا حد فردي.
164:      */
165:     private function assertPerIdentityAllowed(Coupon $coupon, ?Customer $customer, ?string $guestPhoneNormalized): void
166:     {
167:         $limit = (int) $coupon->usage_limit_per_customer;
168:         if ($limit <= 0) {
169:             return;
170:         }
171: 
172:         if ($customer !== null) {
173:             $usedByCustomer = $coupon->usages()
174:                 ->where('customer_id', $customer->id)
175:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
176:                 ->count();
177:             if ($usedByCustomer >= $limit) {
178:                 throw new BusinessException(self::NOT_REDEEMABLE);
179:             }
180: 
181:             return;
182:         }
183: 
184:         if ($guestPhoneNormalized !== null) {
185:             // هوية الزائر هي رقم هاتفه الموحد — تبديل cart_token لا يتجاوز
186:             // الحد (H3)، والعدّ في SQL على العمود المفهرس (F-04)
187:             $usedByPhone = $coupon->usages()
188:                 ->where('guest_phone_normalized', $guestPhoneNormalized)
189:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
190:                 ->count();
191:             if ($usedByPhone >= $limit) {
192:                 throw new BusinessException(self::NOT_REDEEMABLE);
193:             }
194:         }
195:     }
196: }

 1: import { hasPermission } from '@alfarid/utils';
 2: import { defaultApiClient, resolveServiceUrl } from '@alfarid/api-client';
 3: import { ProtectedRoute } from './components/auth/ProtectedRoute';
 4: import AuthCallbackPage from './pages/auth/AuthCallbackPage';
 5: import LoginPage from './pages/auth/LoginPage';
 6: import SessionProbePage from './pages/auth/SessionProbePage';
 7: import { FinancialDashboard } from '@alfarid/ui';
 8: import { lazy, Suspense, useCallback, useEffect, useState } from 'react';
 9: import { useAuthStore } from './stores/auth.store';
10: import CategoriesMockPage from './pages/admin/categories-mock/CategoriesMockPage';
11: import PosPage from './pages/pos/PosPage';
12: import CatalogMockPage from './pages/admin/catalog-mock/CatalogMockPage';
13: const InventoryPage = lazy(() => import('./pages/admin/inventory-mock/InventoryPage'));
14: 
15: defaultApiClient.defaults.baseURL = resolveServiceUrl(import.meta.env.VITE_API_URL ?? 'http://localhost:8000');
16: 
17: export function App() {
18:   if (window.location.pathname === '/auth/session') return <SessionProbePage />;
19:   if (window.location.pathname === '/auth/callback') return <AuthCallbackPage />;
20:   if (window.location.pathname === '/login') return <LoginPage />;
21:   return <ProtectedRoute><AuthenticatedApp /></ProtectedRoute>;
22: }
23: 
24: function AuthenticatedApp() {
25:   const user = useAuthStore((state) => state.user);
26:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
27:   const readRoute = () => window.location.hash.replace(/^#/, '').split('?')[0]
28:     || window.location.pathname;
29:   const [route, setRoute] = useState(readRoute);
30:   const can = useCallback((permission: string) =>
31:     hasPermission(user?.permissions, permission), [user]);
32:   const cashierOnly = user?.roles.length === 1 && user.roles[0] === 'cashier';
33:   useEffect(() => {
34:     // Stocktake navigation guards may synchronously restore the accepted hash.
35:     const changed = () => queueMicrotask(() => setRoute(readRoute()));
36:     window.addEventListener('hashchange', changed);
37:     window.addEventListener('popstate', changed);
38:     return () => {
39:       window.removeEventListener('hashchange', changed);
40:       window.removeEventListener('popstate', changed);
41:     };
42:   }, []);
43:   useEffect(() => {
44:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) window.location.replace('/dashboard');
45:     else if (!['/', '/dashboard', '/categories', '/dealers', '/production', '/pos'].includes(route) && !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route) && !/^\/inventory(?:\/[a-z-]+)?$/.test(route)) window.location.replace('/dashboard');
46:   }, [cashierOnly, route]);
47:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
48:   if (route === '/pos') return <PosPage />;
49:   const categoriesActive = route === '/categories';
50:   const inventoryActive = route === '/inventory' || route.startsWith('/inventory/');
51:   const catalogActive = inventoryActive ? 'inventory' : route.startsWith('/products') ? 'products' : route === '/dealers' ? 'dealers' : route === '/production' ? 'production' : null;
52:   return <FinancialDashboard
53:     onLogout={logoutRemote}
54:     catalogActive={catalogActive}
55:     catalogPage={inventoryActive ? (can('inventory.view') ? <Suspense fallback={<div dir="rtl" className="p-6">جارٍ تحميل المخزون…</div>}><InventoryPage can={can}/></Suspense> : <div dir="rtl" className="p-6">ليس لديك صلاحية عرض المخزون.</div>) : catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />}
56:     catalogNav={!cashierOnly ? [
57:       ...(can('inventory.view') ? [{ id: 'inventory', label: 'المخزون', onOpen: () => { window.location.hash = '/inventory/stock'; } }] : []),
58:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
59:       ...(can('customers.view') ? [{ id: 'dealers', label: 'التجار والموزعون', onOpen: () => { window.location.hash = '/dealers'; } }] : []),
60:       ...(can('inventory.view') ? [{ id: 'production', label: 'استلام الإنتاج', onOpen: () => { window.location.hash = '/production'; } }] : []),
61:     ] : []}
62:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
63:     categoriesActive={categoriesActive}
64:     categoriesPage={<CategoriesMockPage can={can} embedded />}
65:     onOpenCategories={!cashierOnly && can('categories.view')
66:       ? () => { window.location.hash = '/categories'; }
67:       : undefined}
68:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
69:   />;
70: }
71: 
72: export default App;

