  2: 
  3: use App\Http\Middleware\EnsureCustomerAuthenticated;
  4: use App\Http\Middleware\EnsureOpenPosShift;
  5: use App\Http\Middleware\EnsureStaffAuthenticated;
  6: use App\Http\Middleware\EnsureSupplierAuthenticated;
  7: use App\Http\Middleware\EnsureWholesaleApproved;
  8: use App\Http\Middleware\ManufacturingBusiness;
  9: use Illuminate\Database\Eloquent\ModelNotFoundException;
 10: use Illuminate\Database\QueryException;
 11: use Illuminate\Database\UniqueConstraintViolationException;
 12: use Illuminate\Foundation\Application;
 13: use Illuminate\Foundation\Configuration\Exceptions;
 14: use Illuminate\Foundation\Configuration\Middleware;
 15: use Illuminate\Http\Request;
 16: use Illuminate\Support\Facades\Route;
 17: use Spatie\Permission\Middleware\PermissionMiddleware;
 18: use Spatie\Permission\Middleware\RoleMiddleware;
 19: use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
 20: 
 21: return Application::configure(basePath: dirname(__DIR__))
 22:     ->withRouting(
 23:         web: __DIR__.'/../routes/web.php',
 24:         commands: __DIR__.'/../routes/console.php',
 25:         health: '/up',
 26:         then: function (): void {
 27:             Route::middleware('api')
 28:                 ->prefix('api/v1/admin')
 29:                 ->group(base_path('routes/api/admin.php'));
 30:             Route::middleware('api')
 31:                 ->prefix('api/v1/store')
 32:                 ->name('store.')
 33:                 ->group(base_path('routes/api/store.php'));
 34:             Route::middleware('api')
 35:                 ->prefix('api/v1/wholesale')
 36:                 ->name('wholesale.')
 37:                 ->group(base_path('routes/api/wholesale.php'));
 38:             // بوابة المورد: مصادقة supplier_users وكل الاستعلامات مقيدة بمورد المستخدم
 39:             Route::middleware('api')
 40:                 ->prefix('api/v1/supplier')
 41:                 ->name('supplier.')
 42:                 ->group(base_path('routes/api/supplier.php'));
 43:             // ويب هوكس خارجية: بلا مصادقة — الحماية بالتوقيع الرقمي داخل المتحكمات
 44:             Route::middleware('api')
 45:                 ->prefix('api/v1/webhooks')
 46:                 ->name('webhooks.')
 47:                 ->group(base_path('routes/api/webhooks.php'));
 48:             // بوابة الـ POS: كاشير الفرع — توكن موظف + وردية مفتوحة لعمليات البيع
 49:             Route::middleware('api')
 50:                 ->prefix('api/v1/pos')
 51:                 ->name('pos.')
 52:                 ->group(base_path('routes/api/pos.php'));
 53:             // الدخول الموحد: users ← supplier_users ← customers + handoff للموظفين
 54:             Route::middleware('api')
 55:                 ->prefix('api/v1/auth')
 56:                 ->name('unified-auth.')
 57:                 ->group(base_path('routes/api/auth.php'));
 58:         },
 59:     )
 60:     ->withMiddleware(function (Middleware $middleware): void {
 61:         $middleware->api(prepend: [ManufacturingBusiness::class]);
 62:         $middleware->alias([
 63:             'auth.staff' => EnsureStaffAuthenticated::class,
 64:             'auth.customer' => EnsureCustomerAuthenticated::class,
 65:             'auth.supplier' => EnsureSupplierAuthenticated::class,
 66:             'wholesale.approved' => EnsureWholesaleApproved::class,
 67:             'role' => RoleMiddleware::class,
 68:             'permission' => PermissionMiddleware::class,
 69:             'pos.shift' => EnsureOpenPosShift::class,
 70:         ]);
 71:     })
 72:     ->withExceptions(function (Exceptions $exceptions): void {
 73:         $exceptions->render(function (QueryException $e, Request $request) {
 74:             if (($request->is('api/*') || $request->expectsJson())
 75:                 && in_array($e->errorInfo[0] ?? $e->getCode(), ['55P03', '40P01'], true)) {
 76:                 return response()->json(['message' => 'العملية مشغولة بطلب آخر؛ أعد المحاولة بعد لحظات.'], 409);
 77:             }
 78: 
 79:             // M4: حذف مورد له مستخدمون (restrictOnDelete) يرمي 23503 — رد 409
 80:             // مفهوم بدل 500 في لوحة الإدارة.
 81:             if (($request->is('api/*') || $request->expectsJson())
 82:                 && in_array($e->errorInfo[0] ?? $e->getCode(), ['23503'], true)) {
