 11: use App\Models\Stocktake;
 12: use App\Models\StockTransfer;
 13: use App\Models\TreasuryTransfer;
 14: use App\Models\WholesalePaymentNotice;
 15: use App\Services\BranchAccess;
 16: use App\Services\SettingService;
 17: use Illuminate\Cache\RateLimiting\Limit;
 18: use Illuminate\Database\Eloquent\Relations\Relation;
 19: use Illuminate\Http\Middleware\TrustProxies;
 20: use Illuminate\Http\Request;
 21: use Illuminate\Queue\Events\QueueBusy;
 22: use Illuminate\Support\Facades\Event;
 23: use Illuminate\Support\Facades\RateLimiter;
 24: use Illuminate\Support\ServiceProvider;
 25: use Illuminate\Support\Str;
 26: 
 27: class AppServiceProvider extends ServiceProvider
 28: {
 29:     /**
 30:      * Register any application services.
 31:      */
 32:     public function register(): void
 33:     {
 34:         // scoped لا singleton: ذاكرة المستخدمين لكل طلب تعمل داخل الطلب، ولا
 35:         // تتسرب صلاحيات مستخدم لطلب آخر تحت Octane (L-6).
 36:         $this->app->scoped(BranchAccess::class);
 37:         $this->app->scoped(SettingService::class);
 38:     }
 39: 
 40:     /**
 41:      * Bootstrap any application services.
 42:      */
 43:     public function boot(): void
 44:     {
 45:         $proxies = config('app.trusted_proxies');
 46:         if ($this->app->environment('production') && (! is_string($proxies) || trim($proxies) === '' || preg_match('/(?:^|,)\s*\*{1,2}\s*(?:,|$)/', $proxies))) {
 47:             throw new \LogicException('Set TRUSTED_PROXIES to explicit proxy IPs/CIDRs, or none for direct access. Wildcards are not allowed in production.');
 48:         }
 49:         TrustProxies::at(is_string($proxies) && trim($proxies) !== '' && $proxies !== 'none'
 50:             ? array_map('trim', explode(',', $proxies)) : []);
 51:         Event::listen(QueueBusy::class,
 52:             fn ($event) => logger()->error('Queue backlog exceeded its configured threshold.', ['connection' => $event->connectionName, 'queue' => $event->queue, 'size' => $event->size]));
 53: 
 54:         // مستمعو نظام الإشعارات الموحد (المرحلة 13.1) يُكتشفون تلقائيًا من
 55:         // app/Listeners عبر تلميحات أنواع الأحداث — لا تسجيل صريح هنا حتى
 56:         // لا تُستدعى المستمعات مرتين.
 57:         RateLimiter::for('customer-registration', fn (Request $request) => [
 58:             Limit::perMinute(config('auth.customer_limits.registration_ip_minute', 20))->by('customer-register-minute:'.$request->ip()),
 59:             Limit::perDay(config('auth.customer_limits.registration_ip_day', 500))->by('customer-register-day:'.$request->ip()),
 60:         ]);
 61:         RateLimiter::for('store-catalog', fn (Request $request) => [
 62:             Limit::perMinute(config('auth.customer_limits.catalog_ip_minute', 600))->by('store-catalog:'.$request->ip()),
 63:             ...($request->hasAny(['price_min', 'price_max']) || in_array($request->input('sort'), ['price_asc', 'price_desc'], true)
 64:                 ? [Limit::perMinute(config('auth.customer_limits.price_ip_minute', 20))->by('store-price-query:'.$request->ip()),
 65:                     Limit::perMinute(config('auth.customer_limits.price_global_minute', 200))->by('store-price-query:global')] : []),
 66:         ]);
 67:         $identifierKey = function (Request $request): string {
 68:             $email = $request->input('email');
 69:             $phone = $request->input('phone');
 70: 
 71:             return hash('sha256', is_string($email) && $email !== '' ? mb_strtolower(trim($email))
 72:                 : (is_string($phone) ? Customer::normalizePhone($phone) : 'invalid'));
 73:         };
 74:         RateLimiter::for('customer-reset-confirm', fn (Request $request) => [
 75:             Limit::perMinute(config('auth.customer_limits.reset_confirm_ip_minute', 120))->by('reset-confirm-ip:'.$request->ip()),
 76:             Limit::perMinute(10)->by('reset-confirm-id:'.$identifierKey($request)),
 77:         ]);
 78:         $phoneKey = fn (Request $request): string => hash('sha256', is_string($request->input('phone')) ? Customer::normalizePhone($request->input('phone')) : 'invalid');
 79:         RateLimiter::for('customer-phone-send', fn (Request $request) => [
 80:             Limit::perMinute(config('auth.customer_limits.phone_ip_minute', 20))->by('phone-send-ip:'.$request->ip()),
 81:             Limit::perDay(config('auth.customer_limits.phone_ip_day', 500))->by('phone-send-day:'.$request->ip()),
 82:             Limit::perMinute(1)->by('phone-send-id:'.$phoneKey($request)),
 83:         ]);
 84:         RateLimiter::for('customer-phone-verify', fn (Request $request) => [
 85:             Limit::perMinute(config('auth.customer_limits.phone_verify_ip_minute', 120))->by('phone-verify-ip:'.$request->ip()),
 86:             Limit::perMinute(5)->by('phone-verify-id:'.$phoneKey($request)),
 87:         ]);
 88:         // أسماء قصيرة ثابتة لمراجع الدفتر (stock_movements.reference_type):
 89:         // إعادة تسمية/نقل الكلاسات لاحقًا لا تكسر أثر التدقيق التاريخي.
 90:         // الصفوف القديمة المخزنة باسم الكلاس الكامل تظل قابلة للقراءة.
 91:         Relation::morphMap([
 92:             'stock_transfer' => StockTransfer::class,
 93:             'stocktake' => Stocktake::class,
 94:             'order' => Order::class,
 95:             'return_request' => ReturnRequest::class,
 96:             'purchase_order' => PurchaseOrder::class,
 97:             'pos_shift' => PosShift::class,
 98:             'expense' => Expense::class,
 99:             'treasury_transfer' => TreasuryTransfer::class,
100:             'wholesale_payment_notice' => WholesalePaymentNotice::class,
101:         ]);
102: 
103:         // حد دخول العملاء (متجر/جملة): بالمُعرّف (بريد/هاتف) وبالـ IP معًا
104:         RateLimiter::for('customer-login', function (Request $request): array {
105:             $identifier = $request->input('login');
106:             $idKey = is_string($identifier) ? hash('sha256', str_contains($identifier, '@')
107:                 ? Str::lower(trim($identifier)) : Customer::normalizePhone($identifier)) : 'none';
108: 
109:             return [
110:                 Limit::perMinute(5)->by('customer-login-id:'.$idKey),
111:                 Limit::perHour(config('auth.customer_limits.login_id_hour', 30))->by('customer-login-id-hour:'.$idKey),
112:                 Limit::perDay(config('auth.customer_limits.login_id_day', 100))->by('customer-login-id-day:'.$idKey),
113:                 Limit::perMinute(config('auth.customer_limits.login_ip_minute', 120))->by('customer-login-ip:'.($request->ip() ?? 'unknown')),
114:             ];
115:         });
116: 
117:         // حدود مسارات السلة وإتمام الشراء وتتبع الطلب والويب هوك (M3/M5)
118:         RateLimiter::for('cart', fn (Request $request) => [
119:             Limit::perMinute(60)->by('cart-ip:'.$request->ip()),
120:         ]);
121:         // تخمين أكواد الكوبونات (F-24): حد ضيق خاص لكل IP وأيضًا لكل
122:         // توكن/جلسة سلة، بدل الاعتماد على حد السلة العام فقط
123:         RateLimiter::for('coupon', function (Request $request): array {
124:             $identity = $request->bearerToken() ?? $request->header('X-Cart-Session') ?? 'guest';
125: 
126:             return [
127:                 Limit::perMinute(10)->by('coupon-ip:'.$request->ip()),
128:                 Limit::perMinute(10)->by('coupon-id:'.hash('sha256', (string) $identity)),
129:             ];
130:         });
131:         // إتمام الشراء: بالـ IP وأيضًا بالهاتف المُوحَّد (F5) — الزائر بلا
132:         // تحقق من الهاتف لا يراكم طلبات وهمية يحبس بها مخزونًا برقم واحد
133:         RateLimiter::for('checkout', function (Request $request): array {
134:             $phone = $request->input('recipient_phone');
135:             $phoneKey = hash('sha256', is_string($phone) && trim($phone) !== ''
136:                 ? Customer::normalizePhone($phone) : 'guest');
137: 
138:             return [
139:                 Limit::perMinute(10)->by('checkout-ip:'.$request->ip()),
140:                 Limit::perMinute(5)->by('checkout-phone:'.$phoneKey),
141:                 Limit::perDay(20)->by('checkout-phone-day:'.$phoneKey),
142:             ];
143:         });
144:         RateLimiter::for('order-tracking', fn (Request $request) => [
145:             Limit::perMinute(10)->by('order-tracking-ip:'.$request->ip()),
146:         ]);
147:         RateLimiter::for('webhooks', fn (Request $request) => [
148:             Limit::perMinute(120)->by('webhooks-ip:'.$request->ip()),
149:         ]);
150: 
151:         RateLimiter::for('supplier-login', function (Request $request): array {
152:             $email = $request->input('email');
153:             $normalizedEmail = is_string($email)
154:                 ? Str::transliterate(Str::lower(trim($email)))
155:                 : '';
156:             $emailKey = hash('sha256', $normalizedEmail);
157: 
158:             return [
159:                 Limit::perMinute(5)->by('supplier-login-email:'.$emailKey),
160:                 Limit::perHour(30)->by('supplier-login-email-hour:'.$emailKey),
161:                 Limit::perMinute(120)->by('supplier-login-ip:'.($request->ip() ?? 'unknown')),
162:             ];
163:         });
164: 
165:         RateLimiter::for('admin-login', function (Request $request): array {
166:             $email = $request->input('email');
167:             $normalizedEmail = is_string($email)
168:                 ? Str::transliterate(Str::lower(trim($email)))
169:                 : '';
170:             $emailKey = hash('sha256', $normalizedEmail);
171: 
172:             return [
173:                 Limit::perMinute(5)->by('admin-login-email:'.$emailKey),
174:                 Limit::perHour(30)->by('admin-login-email-hour:'.$emailKey),
175:                 Limit::perMinute(120)->by('admin-login-ip:'.($request->ip() ?? 'unknown')),
176:             ];
177:         });
178: 
179:         RateLimiter::for('customer-password-reset', fn (Request $request) => [
180:             Limit::perMinute(config('auth.customer_limits.reset_ip_minute', 20))->by('customer-password-reset:'.$request->ip()),
181:             Limit::perDay(config('auth.customer_limits.reset_ip_day', 500))->by('customer-password-reset-day:'.$request->ip()),
182:             Limit::perMinute(5)->by('customer-password-reset-id:'.$identifierKey($request)),
183:             Limit::perDay(10)->by('customer-password-reset-id-day:'.$identifierKey($request)),
184:         ]);
185: 
186:         // حد تسجيل دخول الكاشير على نقطة البيع
187:         RateLimiter::for('pos-login', function (Request $request): array {
188:             $email = $request->input('email');
189:             $emailKey = hash('sha256', Str::lower(trim(is_string($email) ? $email : '')));
190: 
191:             return [
192:                 Limit::perMinute(5)->by('pos-login-email:'.$emailKey),
193:                 Limit::perHour(30)->by('pos-login-email-hour:'.$emailKey),
194:                 Limit::perMinute(120)->by('pos-login-ip:'.($request->ip() ?? 'unknown')),
195:             ];
196:         });
197: 
198:         // حد الدخول الموحد: بالـ IP وبالمعرّف (بريد/هاتف) معًا
199:         RateLimiter::for('unified-login', function (Request $request) {
200:             // H2: طبّع المعرّف بنفس منطق CustomerAuthService::login، وإلا كانت
201:             // كل صيغة هاتف (‎+20/0020/مسافات/أرقام عربية) بعدّاد مستقل.
202:             // M3: المدخل قد يكون array فيصل قبل الـ validation — لا تصبه لـ string.
203:             $raw = $request->input('login');
204:             $normalized = ! is_string($raw) || trim($raw) === ''
205:                 ? 'invalid'
206:                 : (str_contains($raw, '@')
207:                     ? Str::lower(trim($raw))
208:                     : Customer::normalizePhone($raw));
209:             $id = hash('sha256', $normalized);
210: 
211:             return [
212:                 // M6: حد الـ IP قابل للضبط (شبكات CGNAT والفروع المشتركة)، وحد
213:                 // إبقاء حد ضيق لكل (IP + معرّف) ضد التخمين المركّز.
214:                 // الحدود العامة تحسب الفشل فقط داخل UnifiedAuthService.
215:                 Limit::perMinute((int) config('auth.unified_login_ip_minute', 120))->by('ip:'.$request->ip()),
216:                 Limit::perMinute(5)->by('id:'.$id.':'.$request->ip()),
217:             ];
218:         });
219: 
220:         RateLimiter::for('unified-handoff', fn (Request $request) => Limit::perMinute((int) config('auth.unified_handoff_ip_minute', 60))->by($request->ip()));
221: 
222:         // M8: الـ handoff يعتمد على cache مشترك يدعم الأقفال عبر الخوادم.
223:         // file/array يكسرانه بصمت على عدة nodes — نبّه في الإنتاج مبكرًا.
224:         if ($this->app->environment('production')
225:             && ! in_array((string) config('cache.default'), ['redis', 'database', 'memcached', 'dynamodb'], true)) {
226:             throw new \LogicException('Staff handoff requires a shared lockable cache store in production. Use Redis or a shared database cache.');
227:         }
228:     }
229: }

